INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00014-1cc2-7ba9-9803-e64fb81a57fc', 'es-ES', 'Su poder principal le permite al usuario producir y controlar espuma de jabón densa y burbujas desde su cuerpo, capaces de lavar la suciedad, las toxinas e incluso la fuerza física y la energía.
', ARRAY['Transformación "Suave-Suave" (Limpieza de Poder): La espuma de jabón puede lavar las imperfecciones del cuerpo de una persona, dejando su piel completamente pulida, resbaladiza y suave. Esto elimina toda fricción y fuerza muscular, dejando a las víctimas incapaces de ponerse en pie, sostener armas o luchar con eficacia.','Barreras y Creaciones de Jabón: El usuario puede manipular las burbujas para crear muros defensivos, escudos de espuma densa (Oveja de Jabón) o proyectiles de burbujas ofensivos para atacar a sus objetivos desde la distancia.','Utilidad de Limpieza: La espuma puede lavar rápidamente la mugre, el veneno o las sustancias nocivas de las superficies o de las personas.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00014-1cc2-7ba9-9803-e64fb81a57fc' AND updated_at <= '2026-09-06T16:00:30.629055Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00014-1cc2-7ba9-9803-e64fb81a57fc' AND updated_at <= '2026-09-06T16:00:30.629055Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00014-1cc2-7ba9-9803-e64fb81a57fc', 'en-GB', 'Its main power allows the user to produce and control dense soap suds and bubbles from their body, capable of washing away dirt, toxins, and even physical strength and energy.', ARRAY['"Smooth-Smooth" Transformation (Power Cleanse): The soap suds can wash away the rough edges of a person''s body, leaving their skin completely polished, slippery, and smooth. This strips away all friction and muscle power, rendering victims unable to stand, hold weapons, or fight effectively.','Soap Barriers & Constructs: The user can manipulate bubbles into defensive walls, dense foam shields (Soap Sheep), or offensive bubble projectiles to attack targets from a distance.','Cleansing Utility: The suds can quickly wash away grime, poison, or harmful substances from surfaces or individuals.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00014-1cc2-7ba9-9803-e64fb81a57fc' AND updated_at <= '2026-09-06T16:00:30.629055Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00014-1cc2-7ba9-9803-e64fb81a57fc' AND updated_at <= '2026-09-06T16:00:30.629055Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00014-1cc2-7ba9-9803-e64fb81a57fc', 'ca-ES', 'El seu poder principal permet a l''usuari produir i controlar una escuma i bombolles de sabó denses des del seu cos, capaces de netejar la brutícia, les toxines i fins i tot la força física i l''energia.', ARRAY['Transformació "Suau-Suau" (Neteja de Poder): L''escuma de sabó pot allisar les asprors del cos d''una persona, deixant la seva pell completament polida, lliscosa i suau. Això elimina tota la fricció i la força muscular, deixant les víctimes incapaces de mantenir-se dretes, empunyar armes o lluitar amb eficàcia.','Barreres i Construccions de Sabó: L''usuari pot transformar bombolles en murs defensius, escuts d''escuma densa (Soap Sheep) o projectils ofensius de bombolles per atacar objectius a distància.','Utilitat de Neteja: L''escuma pot netejar ràpidament la brutícia, el verí o substàncies nocives de superfícies o persones.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00014-1cc2-7ba9-9803-e64fb81a57fc' AND updated_at <= '2026-09-06T16:00:30.629055Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00014-1cc2-7ba9-9803-e64fb81a57fc' AND updated_at <= '2026-09-06T16:00:30.629055Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00007-0a79-7d4c-beb1-eed424ee82d4', 'en-GB', 'Its main power allows the user to eat absolutely anything—including organic material, metal, weapons, wood, poison, and even living beings or themselves—and digest it completely without harm.', ARRAY['Weapon Integration: If the user eats cannons, guns, or swords, their limbs and torso can transform into functional artillery and bladed weapons.','Material Assimilation: Eating rare minerals or metals allows the user to synthesize brand-new materials.','Self-Consumption (Slim-Down): The user can eat their own body to reshape their physical frame, such as consuming excess fat to become thin and agile','Human Merging: The user can swallow two or more people simultaneously and combine them into a single, merged fighter inside their stomach.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00007-0a79-7d4c-beb1-eed424ee82d4' AND updated_at <= '2026-08-26T17:36:54.548019Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00007-0a79-7d4c-beb1-eed424ee82d4' AND updated_at <= '2026-08-26T17:36:54.548019Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00007-0a79-7d4c-beb1-eed424ee82d4', 'es-ES', 'Su poder principal permite al usuario comer absolutamente cualquier cosa —incluyendo material orgánico, metal, armas, madera, veneno e incluso seres vivos o a sí mismo— y digerirlo por completo sin sufrir daño alguno.', ARRAY['Integración de Armas: Si el usuario come cañones, pistolas o espadas, sus extremidades y torso pueden transformarse en artillería y armas blancas funcionales.','Asimilación de Materiales: Comer minerales o metales raros le permite sintetizar materiales completamente nuevos.','Autoconsumo (Adelgazamiento): El usuario puede comerse su propio cuerpo para remodelar su complexión física, como consumir el exceso de grasa para volverse delgado y ágil.','Fusión Humana: El usuario puede tragarse a dos o más personas simultáneamente y combinarlas en un único luchador fusionado dentro de su estómago.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00007-0a79-7d4c-beb1-eed424ee82d4' AND updated_at <= '2026-08-26T17:36:54.548019Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00007-0a79-7d4c-beb1-eed424ee82d4' AND updated_at <= '2026-08-26T17:36:54.548019Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00007-0a79-7d4c-beb1-eed424ee82d4', 'ca-ES', 'El seu poder principal permet a l''usuari menjar absolutament qualsevol cosa —incloent-hi material orgànic, metall, armes, fusta, verí i fins i tot éssers vius o a si mateix— i digerir-ho completament sense patir cap dany.', ARRAY['Integració d''Armes: Si l''usuari menja canons, pistoles o espases, les seves extremitats i el tors es poden transformar en artilleria i armes blanques funcionals.','Assimilació de Materials: Menjar minerals o metalls rars li permet sintetitzar materials completament nous.','Autoconsum (Aprimament): L''usuari es pot menjar el seu propi cos per remodelar la seva complexió física, com ara consumir l''excés de greix per tornar-se prim i àgil.','Fusió Humana: L''usuari pot engolir dues o més persones simultàniament i combinar-les en un únic lluitador fusionat dins del seu estómac.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00007-0a79-7d4c-beb1-eed424ee82d4' AND updated_at <= '2026-08-26T17:36:54.548019Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00007-0a79-7d4c-beb1-eed424ee82d4' AND updated_at <= '2026-08-26T17:36:54.548019Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fffed-bad7-782e-ac69-6c7a84234444', 'en-GB', 'This fruit grants the user the ability to split their body into multiple pieces and control those pieces while they levitate through the air, effectively making them a "Chop-Chop Human."', ARRAY['Immunity to Slashing Attacks: The user is completely immune to being cut, sliced, or chopped up. Any cutting attack (even from world-class swordsmen) simply splits the user''s body into pieces without causing any harm.','Body Splitting & Levitation: The user can detach individual limbs or body parts at will and fly them around freely within a specific radius around their feet.','Surprise & Evasion: Splitting body parts allows the user to strike enemies from unexpected angles, detach hands to grab far-away targets, or dodge incoming physical strikes by separating their body right before impact.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019fffed-bad7-782e-ac69-6c7a84234444' AND updated_at <= '2026-08-14T11:07:21.192862Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019fffed-bad7-782e-ac69-6c7a84234444' AND updated_at <= '2026-08-14T11:07:21.192862Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fffed-bad7-782e-ac69-6c7a84234444', 'es-ES', 'Esta fruta otorga al usuario la capacidad de dividir su cuerpo en múltiples piezas y controlarlas mientras levitan por el aire, convirtiéndolo efectivamente en un "Humano Corte-Corte".', ARRAY['Inmunidad a Ataques Cortantes: El usuario es completamente inmune a ser cortado, rebanado o troceado. Cualquier ataque cortante (incluso el de espadachines de talla mundial) simplemente divide el cuerpo del usuario en piezas sin causarle ningún daño.','División Corporal y Levitación: El usuario puede desprender a voluntad extremidades o partes del cuerpo y hacerlas volar libremente dentro de un radio específico alrededor de sus pies.','Sorpresa y Evasión: Dividir partes del cuerpo permite al usuario golpear a los enemigos desde ángulos inesperados, desprender las manos para agarrar objetivos lejanos, o esquivar golpes físicos entrantes separando su cuerpo justo antes del impacto.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019fffed-bad7-782e-ac69-6c7a84234444' AND updated_at <= '2026-08-14T11:07:21.192862Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019fffed-bad7-782e-ac69-6c7a84234444' AND updated_at <= '2026-08-14T11:07:21.192862Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fffed-bad7-782e-ac69-6c7a84234444', 'ca-ES', 'Aquesta fruita atorga a l''usuari la capacitat de dividir el seu cos en múltiples peces i controlar-les mentre leviten per l''aire, convertint-lo efectivament en un "Humà Talla-Talla".', ARRAY['Immunitat als Atacs Tallants: L''usuari és completament immune a ser tallat, trossejat o esbocinat. Qualsevol atac tallant (fins i tot el d''espadatxins de categoria mundial) simplement divideix el cos de l''usuari en peces sense causar-li cap dany.','Divisió Corporal i Levitació: L''usuari pot desprendre''s a voluntat d''extremitats o parts del cos i fer-les volar lliurement dins d''un radi específic al voltant dels seus peus.','Sorpresa i Evasió: Dividir parts del cos permet a l''usuari colpejar els enemics des d''angles inesperats, desprendre les mans per agafar objectius llunyans, o esquivar cops físics entrants separant el seu cos just abans de l''impacte.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019fffed-bad7-782e-ac69-6c7a84234444' AND updated_at <= '2026-08-14T11:07:21.192862Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
