INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000da-7f53-7aa9-9dbd-f7138cfd23f9', 'en-GB', 'Allows the user to sprout large bat-like wings and sharp fangs, granting silent flight and the ability to instantly put targets into a deep sleep by biting their neck and drinking their blood.', ARRAY['Blood-Sucking Sedation: The user''s primary combat maneuver involves biting targets on the neck with her retractable fangs. Rather than merely dealing physical damage, drinking a victim''s blood renders them unconscious almost instantly, bypassing standard physical defenses and armor.','Winged Flight & Stealth: Her transformation summons large, dark, membrane wings from her back without requiring a full body alteration, granting her quiet, high-speed aerial movement and perching abilities.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000da-7f53-7aa9-9dbd-f7138cfd23f9' AND updated_at <= '2026-08-14T15:18:35.560282Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000da-7f53-7aa9-9dbd-f7138cfd23f9' AND updated_at <= '2026-08-14T15:18:35.560282Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000da-7f53-7aa9-9dbd-f7138cfd23f9', 'es-ES', 'Permite al usuario hacer brotar grandes alas similares a las de un murciélago y colmillos afilados, otorgándole un vuelo silencioso y la capacidad de sumir instantáneamente a sus objetivos en un sueño profundo mordiéndoles el cuello y bebiendo su sangre.', ARRAY['Sedación por Succión de Sangre: La maniobra de combate principal de la usuaria consiste en morder a los objetivos en el cuello con sus colmillos retráctiles. En lugar de limitarse a infligir daño físico, beber la sangre de la víctima la deja inconsciente casi al instante, sorteando las defensas físicas y las armaduras habituales.','Vuelo Alado y Sigilo: Su transformación invoca unas grandes alas membranosas y oscuras desde su espalda sin requerir una alteración corporal completa, otorgándole un movimiento aéreo silencioso y veloz, además de la capacidad de posarse.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000da-7f53-7aa9-9dbd-f7138cfd23f9' AND updated_at <= '2026-08-14T15:18:35.560282Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000da-7f53-7aa9-9dbd-f7138cfd23f9' AND updated_at <= '2026-08-14T15:18:35.560282Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000da-7f53-7aa9-9dbd-f7138cfd23f9', 'ca-ES', 'Permet a l''usuària fer brotar unes grans ales semblants a les d''un ratpenat i ullals esmolats, atorgant-li un vol silenciós i la capacitat de submergir instantàniament els seus objectius en un son profund mossegant-los el coll i bevent-ne la sang.', ARRAY['Sedació per Succió de Sang: La maniobra de combat principal de la usuària consisteix a mossegar els objectius al coll amb els seus ullals retràctils. En comptes de limitar-se a infligir dany físic, beure la sang de la víctima la deixa inconscient gairebé a l''instant, esquivant les defenses físiques i les armadures habituals.','Vol Alat i Sigil: La seva transformació invoca unes grans ales membranoses i fosques des de la seva esquena sense requerir una alteració corporal completa, atorgant-li un moviment aeri silenciós i veloç, a més de la capacitat de posar-se.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000da-7f53-7aa9-9dbd-f7138cfd23f9' AND updated_at <= '2026-08-14T15:18:35.560282Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000da-7f53-7aa9-9dbd-f7138cfd23f9' AND updated_at <= '2026-08-14T15:18:35.560282Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019ffffa-0bbc-794b-a0da-77aa8aba6cb3', 'en-GB', 'Its main power allows the user to make any part of their body explode on command without sustaining any harm from their own detonations.', ARRAY['Explosive Arsenal: The user can detonate any body part—ranging from limbs to breath, sweat, hair, and even dried nasal mucus (boogers)—turning every part of themselves into a projectile or weapon.','Immunity to Explosions: The consumer becomes completely immune to all external explosions, blasts, and concussive shockwaves.','Enhanced Melee Attacks: By triggering localized explosions upon impact, the user can dramatically boost the strength of their physical strikes (such as explosive punches or kicks).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019ffffa-0bbc-794b-a0da-77aa8aba6cb3' AND updated_at <= '2026-08-14T11:13:25.483767Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019ffffa-0bbc-794b-a0da-77aa8aba6cb3' AND updated_at <= '2026-08-14T11:13:25.483767Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019ffffa-0bbc-794b-a0da-77aa8aba6cb3', 'es-ES', 'Su poder principal permite al usuario hacer estallar cualquier parte de su cuerpo a voluntad sin sufrir ningún daño por sus propias detonaciones.', ARRAY['Arsenal Explosivo: El usuario puede detonar cualquier parte de su cuerpo —desde extremidades hasta el aliento, el sudor, el cabello e incluso los mocos secos— convirtiendo cada parte de sí mismo en un proyectil o un arma.','Inmunidad a las Explosiones: Quien come la fruta se vuelve completamente inmune a todas las explosiones externas, deflagraciones y ondas de choque.','Ataques Cuerpo a Cuerpo Mejorados: Al provocar explosiones localizadas en el momento del impacto, el usuario puede aumentar drásticamente la fuerza de sus golpes físicos (como puñetazos o patadas explosivas).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019ffffa-0bbc-794b-a0da-77aa8aba6cb3' AND updated_at <= '2026-08-14T11:13:25.483767Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019ffffa-0bbc-794b-a0da-77aa8aba6cb3' AND updated_at <= '2026-08-14T11:13:25.483767Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019ffffa-0bbc-794b-a0da-77aa8aba6cb3', 'ca-ES', 'El seu poder principal permet a l''usuari fer esclatar qualsevol part del seu cos a voluntat sense patir cap dany per les seves pròpies detonacions.', ARRAY['Arsenal Explosiu: L''usuari pot detonar qualsevol part del seu cos —des d''extremitats fins a l''alè, la suor, els cabells i fins i tot els mocs secs— convertint cada part de si mateix en un projectil o una arma.','Immunitat a les Explosions: Qui menja la fruita esdevé completament immune a totes les explosions externes, deflagracions i ones expansives.','Atacs Cos a Cos Millorats: En provocar explosions localitzades en el moment de l''impacte, l''usuari pot augmentar dràsticament la força dels seus cops físics (com ara puntades o cops de puny explosius).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019ffffa-0bbc-794b-a0da-77aa8aba6cb3' AND updated_at <= '2026-08-14T11:13:25.483767Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019ffffa-0bbc-794b-a0da-77aa8aba6cb3' AND updated_at <= '2026-08-14T11:13:25.483767Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fea51-b58d-789a-ab81-361abf533ec1', 'ca-ES', 'Silver Chariot Requiem (anomenat habitualment Chariot Requiem) és la forma evolucionada de Silver Chariot, transformada després de ser travessat per la Fitxa/Fletxa de Stand a la Part 5: Golden Wind. Té l''aspecte d''una figura ombrívola amb barret que porta un gran arc; és un Stand autònom que manipula les ànimes i que actua de manera independent després de la mort de Polnareff per protegir la Fletxa a qualsevol preu.', ARRAY['Manipulació i Intercanvi d''Ànimes: Fa caure en un son profund tots els éssers vius del seu voltant i, en despertar, intercanvia les ànimes de les persones pròximes amb els cossos veïns. Amb el temps, fa que els organismes afectats mutin en entitats desconegudes i grotesques.','Control i Reflex de Stands: Controla els altres Stands dins de la seva àrea d''influència, fent que es girin contra els seus pròpis usuaris si intenten atacar Chariot Requiem o prendre-li la Fletxa.','Autonomia Total: Funciona sense un usuari viu, seguint cecament la seva darrera ordre de custodiar la Fletxa de Stand independentment del dany que rebi.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019fea51-b58d-789a-ab81-361abf533ec1' AND updated_at <= '2026-09-27T14:53:37.97178Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019fea51-b58d-789a-ab81-361abf533ec1' AND updated_at <= '2026-09-27T14:53:37.97178Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fea51-b58d-789a-ab81-361abf533ec1', 'en-GB', 'Silver Chariot Requiem (often simply called Chariot Requiem) is the evolved form of Silver Chariot, transformed after being pierced by the Stand Arrow in Part 5: Golden Wind. Appearing as a shadowy, hat-wearing figure carrying a large bow, it is an autonomous, soul-manipulating Stand that acts independently after Polnareff''s death to protect the Arrow at all costs.', ARRAY['Soul Manipulation & Swapping: Forces all living beings in its vicinity into a deep sleep, swapping the souls of nearby individuals into adjacent bodies upon waking up. Over time, it causes affected organisms to mutate into unknown, grotesque entities.','Stand Control & Reflection: Controls other Stands in its area of influence, turning them against their masters if they attempt to attack Chariot Requiem or take the Arrow.','Complete Autonomy: Functions without a living user, blindly following its final directive to guard the Stand Arrow regardless of damage sustained.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019fea51-b58d-789a-ab81-361abf533ec1' AND updated_at <= '2026-09-27T14:53:37.97178Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019fea51-b58d-789a-ab81-361abf533ec1' AND updated_at <= '2026-09-27T14:53:37.97178Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fea51-b58d-789a-ab81-361abf533ec1', 'es-ES', 'Usuario: Ninguno (se separa de Jean Pierre Polnareff)

Silver Chariot Requiem (conocido habitualmente como Chariot Requiem) es la forma evolucionada de Silver Chariot, transformada tras ser atravesado por la Flecha de Stand en la Parte 5: Golden Wind. Se presenta como una figura sombría con sombrero que lleva un gran arco; es un Stand autónomo capaz de manipular las almas que actúa de forma independiente tras la muerte de Polnareff para proteger la Flecha a toda costa.', ARRAY['Manipulación e Intercambio de Almas','Control y Reflejo de Stands','Autonomía Total']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019fea51-b58d-789a-ab81-361abf533ec1' AND updated_at <= '2026-09-27T14:53:37.97178Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019fea51-b58d-789a-ab81-361abf533ec1' AND updated_at <= '2026-09-27T14:53:37.97178Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00005-04fb-711c-b883-9543bf931e09', 'en-GB', 'Its main power allows the user to produce and manipulate vast amounts of candle wax from their body. This wax emerges as a liquid that can be molded into any shape and then hardened instantly.', ARRAY['Steel-Like Hardness: Once the wax solidifies, it becomes as hard as steel, making it useful for both impenetrable defenses and lethal sharp weapons.','Versatile Crafting: The user can construct a wide variety of objects on the fly, including keys, shackles, giant battle armor, walls, and sharp blades.','Fire Creation: The user can ignite the wax on their head or constructed objects, using open flames to enhance attacks or illuminate dark areas.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00005-04fb-711c-b883-9543bf931e09' AND updated_at <= '2026-08-14T11:25:24.619174Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00005-04fb-711c-b883-9543bf931e09' AND updated_at <= '2026-08-14T11:25:24.619174Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00005-04fb-711c-b883-9543bf931e09', 'es-ES', 'Su poder principal permite al usuario producir y manipular grandes cantidades de cera de vela desde su cuerpo. Esta cera surge en forma líquida, puede moldearse en cualquier forma y luego se endurece al instante.', ARRAY['Dureza Similar al Acero: Una vez que la cera se solidifica, se vuelve tan dura como el acero, lo que la hace útil tanto para defensas impenetrables como para armas afiladas y letales.','Artesanía Versátil: El usuario puede construir sobre la marcha una amplia variedad de objetos, incluyendo llaves, grilletes, armaduras de batalla gigantes, muros y hojas afiladas.','Creación de Fuego: El usuario puede prender fuego a la cera de su cabeza o a los objetos construidos, usando llamas abiertas para potenciar sus ataques o iluminar zonas oscuras.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00005-04fb-711c-b883-9543bf931e09' AND updated_at <= '2026-08-14T11:25:24.619174Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00005-04fb-711c-b883-9543bf931e09' AND updated_at <= '2026-08-14T11:25:24.619174Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00005-04fb-711c-b883-9543bf931e09', 'ca-ES', 'El seu poder principal permet a l''usuari produir i manipular grans quantitats de cera de vela des del seu cos. Aquesta cera sorgeix en forma líquida, es pot modelar amb qualsevol forma i tot seguit s''endureix a l''instant.', ARRAY['Duresa Similar a l''Acer: Un cop la cera es solidifica, esdevé tan dura com l''acer, cosa que la fa útil tant per a defenses impenetrables com per a armes esmolades i letals.','Artesania Versàtil: L''usuari pot construir sobre la marxa una àmplia varietat d''objectes, incloent-hi claus, grillons, armadures de batalla gegants, murs i fulles esmolades.','Creació de Foc: L''usuari pot encendre la cera del seu cap o els objectes construïts, fent servir flames obertes per potenciar els atacs o il·luminar zones fosques.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00005-04fb-711c-b883-9543bf931e09' AND updated_at <= '2026-08-14T11:25:24.619174Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00005-04fb-711c-b883-9543bf931e09' AND updated_at <= '2026-08-14T11:25:24.619174Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0002b-f925-7f22-8eb0-84162c7b5132', 'en-GB', 'Its main power allows the user to manifest ink into real, physical matter, turning whatever they draw into living, functional entities or objects.', ARRAY['Art Materialization: Anything painted by the user—whether animals, weapons, food, or tools—leaps off the drawing surface as a physical creation with real-world functionality (e.g., drawn birds can fly, drawn food can be eaten).','Self-Cloning & Decoys: The user can paint flawless life-sized clones of themselves or others that move, speak, and act independently. These clones are practically indistinguishable from the real person until heavily damaged.','Disguise & Change of Appearance: The user can paint realistic facial features, armor, or clothing directly onto themselves or allies to create convincing disguises.','Ink Rain & Ranged Offense (Ink Clouds): The user can shoot streams of ink into the sky to create dark storm clouds that shower sharp, needle-like ink arrows (Sumigumo) over a wide area.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0002b-f925-7f22-8eb0-84162c7b5132' AND updated_at <= '2026-08-14T12:07:57.646501Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0002b-f925-7f22-8eb0-84162c7b5132' AND updated_at <= '2026-08-14T12:07:57.646501Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0002b-f925-7f22-8eb0-84162c7b5132', 'es-ES', 'Su poder principal permite al usuario materializar tinta en materia física real, convirtiendo cualquier cosa que dibuje en entidades u objetos vivos y funcionales.', ARRAY['Materialización Artística: Cualquier cosa pintada por el usuario —ya sean animales, armas, comida o herramientas— salta de la superficie del dibujo como una creación física con funcionalidad real (por ejemplo, los pájaros dibujados pueden volar, la comida dibujada puede comerse).','Autoclonación y Señuelos: El usuario puede pintar clones perfectos, a tamaño real, de sí mismo o de otras personas, que se mueven, hablan y actúan de forma independiente. Estos clones son prácticamente indistinguibles de la persona real hasta que sufren daños graves.','Disfraz y Cambio de Apariencia: El usuario puede pintar rasgos faciales realistas, armaduras o ropa directamente sobre sí mismo o sus aliados para crear disfraces convincentes.','Lluvia de Tinta y Ofensiva a Distancia (Nubes de Tinta): El usuario puede disparar chorros de tinta hacia el cielo para crear nubes de tormenta oscuras que hacen llover afiladas flechas de tinta en forma de aguja (Sumigumo) sobre una amplia área.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0002b-f925-7f22-8eb0-84162c7b5132' AND updated_at <= '2026-08-14T12:07:57.646501Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0002b-f925-7f22-8eb0-84162c7b5132' AND updated_at <= '2026-08-14T12:07:57.646501Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0002b-f925-7f22-8eb0-84162c7b5132', 'ca-ES', 'El seu poder principal permet a l''usuari materialitzar tinta en matèria física real, convertint qualsevol cosa que dibuixi en entitats o objectes vius i funcionals.', ARRAY['Materialització Artística: Qualsevol cosa pintada per l''usuari —ja siguin animals, armes, menjar o eines— salta de la superfície del dibuix com una creació física amb funcionalitat real (per exemple, els ocells dibuixats poden volar, el menjar dibuixat es pot menjar).','Autoclonació i Senyalets: L''usuari pot pintar clons perfectes, a mida real, de si mateix o d''altres persones, que es mouen, parlen i actuen de manera independent. Aquests clons són pràcticament indistingibles de la persona real fins que pateixen danys greus.','Disfressa i Canvi d''Aparença: L''usuari pot pintar trets facials realistes, armadures o roba directament sobre si mateix o els seus aliats per crear disfresses convincents.','Pluja de Tinta i Ofensiva a Distància (Núvols de Tinta): L''usuari pot disparar raigs de tinta cap al cel per crear núvols de tempesta foscos que fan ploure fletxes de tinta esmolades en forma d''agulla (Sumigumo) sobre una àmplia zona.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0002b-f925-7f22-8eb0-84162c7b5132' AND updated_at <= '2026-08-14T12:07:57.646501Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0002b-f925-7f22-8eb0-84162c7b5132' AND updated_at <= '2026-08-14T12:07:57.646501Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00092-627b-7a08-aec2-1ae43bd035ab', 'en-GB', 'Allows the user to create, control, and transform their body into various types of chemical gases and vapor mixtures at will.', ARRAY['Oxygen Depletion & Suffocation: One of the fruit''s most dangerous passive techniques is Karakuni (Empty World). Caesar can remove oxygen completely within a specific radius around himself, causing anyone inside the perimeter to suffocate and lose consciousness within seconds—bypassing raw physical strength or defenses.','Poisonous Gas: Emitting lethal nerve toxins and poisonous clouds (Gastanet) that corrode lungs and skin.','Flammable & Explosive Gas: Filling an area with volatile, combustible gas and igniting it for massive thermobaric explosions (Gastille).','Hallucinogens & Anesthetics: Producing gases that induce sleep, disorientation, or paralysis.','Intangibility & Flight: As a gaseous Logia, physical non-Haki attacks pass harmlessly through Caesar''s cloud-like body. He can compress or expand his gas form to fly through the sky or slip through small cracks, pipes, and keyholes.','Gas Absorption & Fusion: The user can absorb external gas clouds to dramatically increase their size, mass, and power output.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00092-627b-7a08-aec2-1ae43bd035ab' AND updated_at <= '2026-08-14T14:00:15.08003Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00092-627b-7a08-aec2-1ae43bd035ab' AND updated_at <= '2026-08-14T14:00:15.08003Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00092-627b-7a08-aec2-1ae43bd035ab', 'es-ES', 'Permite al usuario crear, controlar y transformar su cuerpo en varios tipos de gases químicos y mezclas de vapor a voluntad.', ARRAY['Agotamiento de Oxígeno y Asfixia: Una de las técnicas pasivas más peligrosas de la fruta es Karakuni (Mundo Vacío). Caesar puede eliminar por completo el oxígeno dentro de un radio específico a su alrededor, provocando que cualquiera dentro del perímetro se asfixie y pierda el conocimiento en cuestión de segundos, sin importar su fuerza física o sus defensas.','Gas Venenoso: Emite toxinas nerviosas letales y nubes venenosas (Gastanet) que corroen los pulmones y la piel.','Gas Inflamable y Explosivo: Llena una zona con gas volátil y combustible, para luego prenderlo y provocar enormes explosiones termobáricas (Gastille).','Alucinógenos y Anestésicos: Produce gases que inducen sueño, desorientación o parálisis.','Intangibilidad y Vuelo: Como Logia gaseosa, los ataques físicos que no usan Haki atraviesan sin daño el cuerpo de nube de Caesar. Puede comprimir o expandir su forma gaseosa para volar por el cielo o colarse por pequeñas grietas, tuberías y cerraduras.','Absorción y Fusión de Gas: El usuario puede absorber nubes de gas externas para aumentar drásticamente su tamaño, masa y potencia.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00092-627b-7a08-aec2-1ae43bd035ab' AND updated_at <= '2026-08-14T14:00:15.08003Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00092-627b-7a08-aec2-1ae43bd035ab' AND updated_at <= '2026-08-14T14:00:15.08003Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00092-627b-7a08-aec2-1ae43bd035ab', 'ca-ES', 'Permet a l''usuari crear, controlar i transformar el seu cos en diversos tipus de gasos químics i barreges de vapor a voluntat.', ARRAY['Esgotament d''Oxigen i Asfíxia: Una de les tècniques passives més perilloses de la fruita és Karakuni (Món Buit). En Caesar pot eliminar completament l''oxigen dins d''un radi específic al seu voltant, fent que qualsevol persona dins del perímetre s''asfixiï i perdi el coneixement en qüestió de segons, independentment de la seva força física o defenses.','Gas Verinós: Emet toxines nervioses letals i núvols verinosos (Gastanet) que corroeixen els pulmons i la pell.','Gas Inflamable i Explosiu: Omple una zona amb gas volàtil i combustible, per després encendre''l i provocar enormes explosions termobàriques (Gastille).','Al·lucinògens i Anestèsics: Produeix gasos que indueixen son, desorientació o paràlisi.','Intangibilitat i Vol: Com a Logia gasosa, els atacs físics que no fan servir Haki travessen sense dany el cos de núvol d''en Caesar. Pot comprimir o expandir la seva forma gasosa per volar pel cel o esmunyir-se per petites esquerdes, canonades i panys.','Absorció i Fusió de Gas: L''usuari pot absorbir núvols de gas externs per augmentar dràsticament la seva mida, massa i potència.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00092-627b-7a08-aec2-1ae43bd035ab' AND updated_at <= '2026-08-14T14:00:15.08003Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00092-627b-7a08-aec2-1ae43bd035ab' AND updated_at <= '2026-08-14T14:00:15.08003Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00023-d112-7806-bd0a-01b1a37e6986', 'en-GB', 'The fruit turns the user''s body permanently into rubber, allowing every part of their physical frame—muscles, bones, skin, and internal organs—to stretch and compress at will.', ARRAY['Blunt Force Immunity: Standard punches, kicks, falls, and non-sharp impacts deal virtually no damage, as the rubber body harmlessly absorbs and bounces off physical shockwaves.','Electrical Insulation: Because rubber is a natural insulator, the user is completely immune to electrical attacks and lightning strikes.','Kinetic Momentum (Gears 2–4): The user can stretch their limbs back to launch high-velocity ranged attacks (Gum-Gum Pistol), pump blood at high pressure to boost speed (Gear 2nd), inflate bones for massive crushing hits (Gear 3rd), or compress muscle tissue with Haki for explosive mobility and force (Gear 4th).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00023-d112-7806-bd0a-01b1a37e6986' AND updated_at <= '2026-08-14T11:59:15.611765Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00023-d112-7806-bd0a-01b1a37e6986' AND updated_at <= '2026-08-14T11:59:15.611765Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00023-d112-7806-bd0a-01b1a37e6986', 'es-ES', 'La fruta convierte permanentemente el cuerpo del usuario en goma, permitiendo que cada parte de su estructura física —músculos, huesos, piel y órganos internos— se estire y se comprima a voluntad.', ARRAY['Inmunidad a la Fuerza Contundente: Los puñetazos, patadas, caídas e impactos no cortantes convencionales apenas causan daño, ya que el cuerpo de goma absorbe sin sufrir las ondas de choque físicas y las hace rebotar.','Aislamiento Eléctrico: Como la goma es un aislante natural, el usuario es completamente inmune a los ataques eléctricos y a los rayos.','Impulso Cinético (Gears 2–4): El usuario puede estirar sus extremidades hacia atrás para lanzar ataques a distancia de gran velocidad (Gum-Gum Pistol), bombear sangre a alta presión para aumentar la velocidad (Gear 2nd), inflar los huesos para asestar golpes aplastantes (Gear 3rd), o comprimir el tejido muscular con Haki para lograr una movilidad y una fuerza explosivas (Gear 4th).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00023-d112-7806-bd0a-01b1a37e6986' AND updated_at <= '2026-08-14T11:59:15.611765Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00023-d112-7806-bd0a-01b1a37e6986' AND updated_at <= '2026-08-14T11:59:15.611765Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00023-d112-7806-bd0a-01b1a37e6986', 'ca-ES', 'La fruita converteix permanentment el cos de l''usuari en goma, permetent que cada part de la seva estructura física —músculs, ossos, pell i òrgans interns— s''estiri i es comprimeixi a voluntat.', ARRAY['Immunitat a la Força Contundent: Els cops de puny, puntades, caigudes i impactes no tallants convencionals amb prou feines causen dany, ja que el cos de goma absorbeix sense patir les ones de xoc físiques i les fa rebotar.','Aïllament Elèctric: Com que la goma és un aïllant natural, l''usuari és completament immune als atacs elèctrics i als llamps.','Impuls Cinètic (Gears 2–4): L''usuari pot estirar les seves extremitats cap enrere per llançar atacs a distància de gran velocitat (Gum-Gum Pistol), bombejar sang a alta pressió per augmentar la velocitat (Gear 2nd), inflar els ossos per assestar cops aixafadors (Gear 3rd), o comprimir el teixit muscular amb Haki per aconseguir una mobilitat i una força explosives (Gear 4th).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00023-d112-7806-bd0a-01b1a37e6986' AND updated_at <= '2026-08-14T11:59:15.611765Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00023-d112-7806-bd0a-01b1a37e6986' AND updated_at <= '2026-08-14T11:59:15.611765Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0007e-a4d7-7927-823c-5969e9b068d3', 'en-GB', 'Allows the user to create, control, and transform their body into electricity and lightning at will.', ARRAY['Targeted Strikes: Calling down massive lightning bolts from the sky (El Thor).','Beast Manifestations: Shaping electricity into giant hawks, dragons, or wolves (Hino, Vari, Mamu).','Mass Destruction: Combining his powers with floating storm clouds to obliterate an entire island (Raigo).','Electro-Radar: By combining his lightning powers with Kenbunshoku Haki (Observation Haki / Mantra), Enel can pick up electromagnetic waves traveling through the air. This allows him to overhear conversations and pinpoint locations across an entire island.','Defibrillation / Self-Resuscitation: If his heart stops beating due to fatal physical damage, the user can automatically restart their own heart by shocking themselves back to life.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0007e-a4d7-7927-823c-5969e9b068d3' AND updated_at <= '2026-08-14T13:38:15.490841Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0007e-a4d7-7927-823c-5969e9b068d3' AND updated_at <= '2026-08-14T13:38:15.490841Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0007e-a4d7-7927-823c-5969e9b068d3', 'ca-ES', 'Permet a l''usuari crear, controlar i transformar el seu cos en electricitat i llamps a voluntat.', ARRAY['Atacs Dirigits: Invocar enormes llamps des del cel (El Thor).','Manifestacions Bestials: Donar forma a l''electricitat per crear falcons, dracs o llops gegants (Hino, Vari, Mamu).','Destrucció Massiva: Combinar els seus poders amb núvols de tempesta flotants per arrasar una illa sencera (Raigo).','Electro-Radar: En combinar els seus poders elèctrics amb el Kenbunshoku Haki (Haki de l''Observació / Mantra), Enel pot captar ones electromagnètiques que viatgen per l''aire. Això li permet escoltar converses i localitzar posicions en tota una illa.','Desfibril·lació / Autoressurrecció: Si el seu cor deixa de bategar per un dany físic letal, l''usuari pot reiniciar-lo automàticament aplicant-se una descàrrega que el torna a la vida.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0007e-a4d7-7927-823c-5969e9b068d3' AND updated_at <= '2026-08-14T13:38:15.490841Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0007e-a4d7-7927-823c-5969e9b068d3' AND updated_at <= '2026-08-14T13:38:15.490841Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0007e-a4d7-7927-823c-5969e9b068d3', 'es-ES', 'Permite al usuario crear, controlar y transformar su cuerpo en electricidad y rayos a voluntad.', ARRAY['Ataques Dirigidos: Invocar enormes rayos desde el cielo (El Thor).','Manifestaciones Bestiales: Dar forma a la electricidad para crear halcones, dragones o lobos gigantes (Hino, Vari, Mamu).','Destrucción Masiva: Combinar sus poderes con nubes de tormenta flotantes para arrasar una isla entera (Raigo).','Electro-Radar: Al combinar sus poderes eléctricos con el Kenbunshoku Haki (Haki de la Observación / Mantra), Enel puede captar ondas electromagnéticas que viajan por el aire. Esto le permite escuchar conversaciones y localizar posiciones en toda una isla.','Desfibrilación / Autorresucitación: Si su corazón deja de latir por daño físico letal, el usuario puede reiniciarlo automáticamente aplicándose una descarga que lo devuelve a la vida.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0007e-a4d7-7927-823c-5969e9b068d3' AND updated_at <= '2026-08-14T13:38:15.490841Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0007e-a4d7-7927-823c-5969e9b068d3' AND updated_at <= '2026-08-14T13:38:15.490841Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00026-f1dc-7978-8188-7e818c47322b', 'en-GB', 'Its main power allows the user to generate powerful vibrations and shockwaves that can travel through any medium, including earth, water, and even the air itself.', ARRAY['Air Shattering & Earthquakes: The user can summon shockwaves so intense that they physically crack the air around them, sending massive seismic tremors through the ground to collapse entire landscapes, fortresses, and islands.','Tsunami Generation (Shima Yurashi): By unleashing seismic waves underwater or literally grabbing and tilting the sea/environment itself, the user can trigger colossal tsunamis capable of swallowing entire fleets and naval bases.','Vibrational Infusion (Kabuto Wari): The user can concentrate localized shockwave bubbles around their fists, feet, or weapons (such as Whitebeard''s Murakumogiri). These focused blasts deliver catastrophic point-blank blunt damage that shatters armor and bypasses external defenses to damage internal organs.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00026-f1dc-7978-8188-7e818c47322b' AND updated_at <= '2026-08-14T12:02:55.665055Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00026-f1dc-7978-8188-7e818c47322b' AND updated_at <= '2026-08-14T12:02:55.665055Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00026-f1dc-7978-8188-7e818c47322b', 'es-ES', 'Su poder principal permite al usuario generar potentes vibraciones y ondas de choque capaces de propagarse por cualquier medio, incluyendo la tierra, el agua e incluso el propio aire.', ARRAY['Fractura del Aire y Terremotos: El usuario puede invocar ondas de choque tan intensas que agrietan físicamente el aire a su alrededor, provocando enormes temblores sísmicos en el suelo capaces de derrumbar paisajes, fortalezas e islas enteras.','Generación de Tsunamis (Shima Yurashi): Liberando ondas sísmicas bajo el agua o literalmente agarrando e inclinando el mar/entorno, el usuario puede desencadenar tsunamis colosales capaces de engullir flotas enteras y bases navales.','Infusión Vibracional (Kabuto Wari): El usuario puede concentrar burbujas de onda de choque localizadas alrededor de sus puños, pies o armas (como el Murakumogiri de Barbablanca). Estos golpes concentrados infligen un daño contundente catastrófico a quemarropa que destroza armaduras y sortea las defensas externas para dañar los órganos internos.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00026-f1dc-7978-8188-7e818c47322b' AND updated_at <= '2026-08-14T12:02:55.665055Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00026-f1dc-7978-8188-7e818c47322b' AND updated_at <= '2026-08-14T12:02:55.665055Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00026-f1dc-7978-8188-7e818c47322b', 'ca-ES', 'El seu poder principal permet a l''usuari generar potents vibracions i ones de xoc capaces de propagar-se per qualsevol medi, incloent la terra, l''aigua i fins i tot el mateix aire.', ARRAY['Fractura de l''Aire i Terratrèmols: L''usuari pot invocar ones de xoc tan intenses que esquerden físicament l''aire al seu voltant, provocant enormes tremolors sísmiques al terra capaces d''ensorrar paisatges, fortaleses i illes senceres.','Generació de Tsunamis (Shima Yurashi): Alliberant ones sísmiques sota l''aigua o literalment agafant i inclinant el mar/entorn, l''usuari pot desencadenar tsunamis colossals capaços d''engolir flotes senceres i bases navals.','Infusió Vibracional (Kabuto Wari): L''usuari pot concentrar bombolles d''ona de xoc localitzades al voltant dels seus punys, peus o armes (com el Murakumogiri de Barbablanca). Aquests cops concentrats infligeixen un dany contundent catastròfic a boca de canó que destrossa armadures i esquiva les defenses externes per danyar els òrgans interns.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00026-f1dc-7978-8188-7e818c47322b' AND updated_at <= '2026-08-14T12:02:55.665055Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00026-f1dc-7978-8188-7e818c47322b' AND updated_at <= '2026-08-14T12:02:55.665055Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fffff-22ad-7279-a8dc-c2160559159a', 'es-ES', 'Su poder principal permite al usuario hacer brotar copias de cualquier parte del cuerpo —normalmente manos y ojos— desde cualquier superficie dentro de su campo de visión, incluyendo suelo firme, paredes, objetos e incluso los cuerpos de otras personas vivas.', ARRAY['Ensamblaje Multiextremidades: El usuario puede hacer brotar docenas, cientos o incluso miles de extremidades a la vez. Puede combinarlas para crear construcciones más grandes, como manos gigantes, piernas, alas para vuelos cortos o clones de cuerpo completo.','Agarre y Sometimiento a Larga Distancia: Destaca por incapacitar a los oponentes al instante desde la distancia, haciendo brotar brazos directamente sobre sus cuerpos para dislocarles las articulaciones, estrangularlos o desarmarlos.','Recopilación de Información: Al hacer brotar ojos u oídos en lugares lejanos u ocultos, el usuario puede espiar conversaciones y explorar zonas con seguridad.','Vuelo Temporal: Al hacer brotar cientos de manos en su espalda dispuestas como grandes alas, el usuario puede planear y volar durante unos 5 segundos. Ideal para escapar de caídas altas o cruzar huecos peligrosos.','Redes de Seguridad: Hace brotar brazos entrelazados para atrapar con seguridad a aliados que caen.','Escaleras y Cuerdas: Forma cadenas humanas o escaleras con extremidades para que los aliados puedan trepar.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019fffff-22ad-7279-a8dc-c2160559159a' AND updated_at <= '2026-08-14T11:22:45.774819Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019fffff-22ad-7279-a8dc-c2160559159a' AND updated_at <= '2026-08-14T11:22:45.774819Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fffff-22ad-7279-a8dc-c2160559159a', 'ca-ES', 'El seu poder principal permet a l''usuari fer brotar còpies de qualsevol part del cos —normalment mans i ulls— des de qualsevol superfície dins del seu camp de visió, incloent terra ferm, parets, objectes i fins i tot els cossos d''altres persones vives.', ARRAY['Muntatge Multiextremitats: L''usuari pot fer brotar dotzenes, centenars o fins i tot milers d''extremitats alhora. Pot combinar-les per crear construccions més grans, com mans gegants, cames, ales per a vols curts o clons de cos sencer.','Agafament i Submissió a Llarga Distància: Destaca per incapacitar els oponents a l''instant des de la distància, fent brotar braços directament sobre els seus cossos per dislocar-los les articulacions, escanyar-los o desarmar-los.','Recopilació d''Informació: En fer brotar ulls o orelles en llocs llunyans o amagats, l''usuari pot espiar converses i explorar zones amb seguretat.','Vol Temporal: En fer brotar centenars de mans a l''esquena disposades com grans ales, l''usuari pot planejar i volar durant uns 5 segons. Ideal per escapar de caigudes altes o creuar buits perillosos.','Xarxes de Seguretat: Fa brotar braços entrellaçats per atrapar amb seguretat aliats que cauen.','Escales i Cordes: Forma cadenes humanes o escales amb extremitats perquè els aliats hi puguin enfilar-se.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019fffff-22ad-7279-a8dc-c2160559159a' AND updated_at <= '2026-08-14T11:22:45.774819Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019fffff-22ad-7279-a8dc-c2160559159a' AND updated_at <= '2026-08-14T11:22:45.774819Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fffff-22ad-7279-a8dc-c2160559159a', 'en-GB', 'Its main power allows the user to sprout copies of any body part—most commonly hands and eyes—from any surface within their line of sight, including solid ground, walls, objects, and even other living people''s bodies.', ARRAY['Multi-Limb Assembly: The user can sprout dozens, hundreds, or even thousands of limbs at once. They can combine these limbs to create larger constructs, such as giant hands, legs, wings for short-distance flight, or full-body clones.','Long-Range Grappling & Subjugation: It excels at disabling opponents instantly from a distance by sprouting arms directly on their bodies to snap joints, choke, or disarm them.','Information Gathering: By sprouting eyes or ears in distant or hidden locations, the user can spy on conversations and scout areas safely.','Temporary Flight:  By sprouting hundreds of hands on their back structured like large wings, the user can glide and fly for about 5 seconds. This is ideal for escaping high falls or crossing dangerous gaps.','Safety Nets: Sprouts interlocking arms to catch falling allies safely.','Ladders & Ropes: Forms human chains or stairs out of limbs for allies to climb.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019fffff-22ad-7279-a8dc-c2160559159a' AND updated_at <= '2026-08-14T11:22:45.774819Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019fffff-22ad-7279-a8dc-c2160559159a' AND updated_at <= '2026-08-14T11:22:45.774819Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000cd-18ec-7238-9717-86f7be465a04', 'en-GB', 'Allows the user to transform into an anaconda hybrid or a full giant anaconda at will, gaining immense constriction power, flexibility, and serpentine physiology.', ARRAY['Crushing Constriction Strength: As an anaconda, the fruit emphasizes sheer muscle mass and binding force rather than venom. The user can coil her massive serpentine body around targets to crush their bones, armor, and internal organs.','Snake Hair Constructs (Hebidance): By combining her Zoan transformation with high-level physical technique, Sandersonia can manipulate her hair to turn into large, living snake heads (Hebidance / Snake Dance). These hair-snakes can strike targets, bite, or bind enemies independently.','Evasive Flexibility: Her tail and body can bend, twist, and slide rapidly across battle arenas to evade incoming strikes.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000cd-18ec-7238-9717-86f7be465a04' AND updated_at <= '2026-08-14T15:40:38.55498Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000cd-18ec-7238-9717-86f7be465a04' AND updated_at <= '2026-08-14T15:40:38.55498Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000cd-18ec-7238-9717-86f7be465a04', 'es-ES', 'Permite al usuario transformarse a voluntad en un híbrido de anaconda o en una anaconda gigante completa, obteniendo una inmensa fuerza de constricción, flexibilidad y fisiología serpentina.', ARRAY['Fuerza de Constricción Aplastante: Como anaconda, la fruta enfatiza la pura masa muscular y la fuerza de sujeción en lugar del veneno. La usuaria puede enroscar su enorme cuerpo serpentino alrededor de sus objetivos para triturarles los huesos, la armadura y los órganos internos.','Construcciones de Cabello Serpiente (Hebidance): Al combinar su transformación Zoan con una técnica física de alto nivel, Sandersonia puede convertir su cabello en grandes cabezas de serpiente vivas (Hebidance / Danza de la Serpiente). Estas serpientes de cabello pueden golpear objetivos, morder o inmovilizar enemigos de forma independiente.','Flexibilidad Evasiva: Su cola y su cuerpo pueden doblarse, retorcerse y deslizarse rápidamente por el campo de batalla para esquivar los golpes entrantes.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000cd-18ec-7238-9717-86f7be465a04' AND updated_at <= '2026-08-14T15:40:38.55498Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000cd-18ec-7238-9717-86f7be465a04' AND updated_at <= '2026-08-14T15:40:38.55498Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000cd-18ec-7238-9717-86f7be465a04', 'ca-ES', 'Permet a l''usuari transformar-se a voluntat en un híbrid d''anaconda o en una anaconda gegant completa, obtenint una immensa força de constricció, flexibilitat i fisiologia serpentina.', ARRAY['Força de Constricció Aixafadora: Com a anaconda, la fruita emfatitza la pura massa muscular i la força de subjecció en lloc del verí. L''usuària pot enroscar el seu enorme cos serpentí al voltant dels objectius per esmicolar-los els ossos, l''armadura i els òrgans interns.','Construccions de Cabell Serp (Hebidance): En combinar la seva transformació Zoan amb una tècnica física d''alt nivell, Sandersonia pot convertir els seus cabells en grans caps de serp vius (Hebidance / Dansa de la Serp). Aquestes serps de cabell poden colpejar objectius, mossegar o immobilitzar enemics de manera independent.','Flexibilitat Evasiva: La seva cua i el seu cos es poden doblegar, retòrcer i lliscar ràpidament pel camp de batalla per esquivar els cops entrants.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000cd-18ec-7238-9717-86f7be465a04' AND updated_at <= '2026-08-14T15:40:38.55498Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000cd-18ec-7238-9717-86f7be465a04' AND updated_at <= '2026-08-14T15:40:38.55498Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000cf-40da-71e7-8b9a-a2afab139e31', 'en-GB', 'It allows the user to transform into a full king cobra or a human-king cobra hybrid at will.', ARRAY['Corrosive Venom Spitting: She can spit large streams of deadly venom (Snake Spit / Heavy Venom). This venom is potent enough to melt stone, steel, and armor upon contact.','Thermal Sensing & Flexibility: Grants her snake-like heat perception to track targets and extreme body flexibility.','Fire Generation: By combining her bodily controls and snake techniques, the user can ignite her body or hair in flames (Salamander techniques).','Prehensile Tail: In her hybrid form, her tail functions as a powerful whip or constriction tool capable of crushing bones.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000cf-40da-71e7-8b9a-a2afab139e31' AND updated_at <= '2026-08-14T15:06:18.54438Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000cf-40da-71e7-8b9a-a2afab139e31' AND updated_at <= '2026-08-14T15:06:18.54438Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000cf-40da-71e7-8b9a-a2afab139e31', 'es-ES', 'Permite al usuario transformarse a voluntad en una cobra real completa o en un híbrido humano-cobra real.', ARRAY['Escupitajo de Veneno Corrosivo: Puede escupir grandes chorros de veneno mortal (Escupitajo de Serpiente / Veneno Pesado). Este veneno es lo bastante potente como para derretir piedra, acero y armadura al contacto.','Percepción Térmica y Flexibilidad: Le otorga una percepción del calor similar a la de las serpientes para rastrear objetivos, además de una flexibilidad corporal extrema.','Generación de Fuego: Al combinar el control de su cuerpo con técnicas de serpiente, la usuaria puede prender fuego a su cuerpo o cabello (técnicas Salamandra).','Cola Prensil: En su forma híbrida, su cola funciona como un poderoso látigo o herramienta de constricción capaz de triturar huesos.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000cf-40da-71e7-8b9a-a2afab139e31' AND updated_at <= '2026-08-14T15:06:18.54438Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000cf-40da-71e7-8b9a-a2afab139e31' AND updated_at <= '2026-08-14T15:06:18.54438Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000cf-40da-71e7-8b9a-a2afab139e31', 'ca-ES', 'Permet a l''usuari transformar-se a voluntat en una cobra reial completa o en un híbrid humà-cobra reial.', ARRAY['Escopinada de Verí Corrosiu: Pot escopir grans dolls de verí mortal (Escopinada de Serp / Verí Pesat). Aquest verí és prou potent com per fondre pedra, acer i armadura en contacte.','Percepció Tèrmica i Flexibilitat: Li atorga una percepció de la calor semblant a la de les serps per rastrejar objectius, a més d''una flexibilitat corporal extrema.','Generació de Foc: En combinar el control del seu cos amb tècniques de serp, l''usuària pot encendre el seu cos o cabell en flames (tècniques Salamandra).','Cua Prènsil: En la seva forma híbrida, la seva cua funciona com un potent làtig o eina de constricció capaç de triturar ossos.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000cf-40da-71e7-8b9a-a2afab139e31' AND updated_at <= '2026-08-14T15:06:18.54438Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000cf-40da-71e7-8b9a-a2afab139e31' AND updated_at <= '2026-08-14T15:06:18.54438Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0006d-7b93-7bd5-a5fe-6049f07d9198', 'en-GB', 'Based on the legendary eight-headed dragon-serpent of Japanese mythology, the fruit grants the user the ability to transform into a massive, eight-headed serpent or an eight-headed hybrid form.', ARRAY['Beast Form (Full Yamata no Orochi): Transforms into a towering, multi-headed serpent with eight long necks, sharp fangs, and dragon-like scales.','Hybrid Form: The user''s lower body or torso sprouts multiple long serpent necks and heads while retaining humanoid limbs for close combat.','Independent Head Sentience: Each of the eight heads can act, bite, and speak independently, allowing the user to view surrounding angles and attack multiple targets simultaneously.','Surviving Decapitation: Because the fruit grants eight distinct heads, the user can survive being decapitated. A single decapitation only severs one of the eight heads, leaving the remaining heads—and the user—alive.','Eight Extra Opportunities: To permanently kill the user, enemies must cut off all eight heads individually. During the Raid on Onigashima, Orochi survived multiple fatal decapitations (by Kaido and the Akazaya Nine) before his final head was eventually severed.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0006d-7b93-7bd5-a5fe-6049f07d9198' AND updated_at <= '2026-08-27T14:17:20.353298Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0006d-7b93-7bd5-a5fe-6049f07d9198' AND updated_at <= '2026-08-27T14:17:20.353298Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0006d-7b93-7bd5-a5fe-6049f07d9198', 'es-ES', 'Basada en la legendaria serpiente-dragón de ocho cabezas de la mitología japonesa, esta fruta otorga al usuario la capacidad de transformarse en una serpiente masiva de ocho cabezas o en una forma híbrida de ocho cabezas.', ARRAY['Forma Bestial (Yamata no Orochi Completo): Se transforma en una serpiente imponente y multicéfala con ocho largos cuellos, colmillos afilados y escamas de aspecto dracónico.','Forma Híbrida: La parte inferior del cuerpo o el torso del usuario hace brotar múltiples cuellos y cabezas de serpiente largas, mientras conserva extremidades humanoides para el combate cuerpo a cuerpo.','Conciencia Independiente de las Cabezas: Cada una de las ocho cabezas puede actuar, morder y hablar de forma independiente, permitiendo al usuario ver ángulos circundantes y atacar a varios objetivos simultáneamente.','Supervivencia a la Decapitación: Al tener ocho cabezas distintas, el usuario puede sobrevivir a una decapitación. Una sola decapitación solo corta una de las ocho cabezas, dejando con vida al resto de cabezas y al usuario.','Ocho Oportunidades Extra: Para matar permanentemente al usuario, los enemigos deben cortar las ocho cabezas una por una. Durante la Incursión en Onigashima, Orochi sobrevivió a múltiples decapitaciones fatales (a manos de Kaido y los Akazaya Nueve) antes de que finalmente le cortaran su última cabeza.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0006d-7b93-7bd5-a5fe-6049f07d9198' AND updated_at <= '2026-08-27T14:17:20.353298Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0006d-7b93-7bd5-a5fe-6049f07d9198' AND updated_at <= '2026-08-27T14:17:20.353298Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0006d-7b93-7bd5-a5fe-6049f07d9198', 'ca-ES', 'Basada en la llegendària serp-drac de vuit caps de la mitologia japonesa, aquesta fruita atorga a l''usuari la capacitat de transformar-se en una serp massiva de vuit caps o en una forma híbrida de vuit caps.', ARRAY['Forma Bestial (Yamata no Orochi Complet): Es transforma en una serp imponent i multicèfala amb vuit colls llargs, ullals esmolats i escates d''aspecte dracònic.','Forma Híbrida: La part inferior del cos o el tors de l''usuari fa brotar múltiples colls i caps de serp llargs, mentre conserva extremitats humanoides per al combat cos a cos.','Consciència Independent dels Caps: Cadascun dels vuit caps pot actuar, mossegar i parlar de manera independent, la qual cosa permet a l''usuari veure angles del voltant i atacar diversos objectius simultàniament.','Supervivència a la Decapitació: En tenir vuit caps diferenciats, l''usuari pot sobreviure a una decapitació. Una sola decapitació només talla un dels vuit caps, deixant amb vida la resta de caps i l''usuari.','Vuit Oportunitats Extra: Per matar permanentment l''usuari, els enemics han de tallar els vuit caps un per un. Durant la Incursió a Onigashima, Orochi va sobreviure a múltiples decapitacions fatals (a mans de Kaido i els Akazaya Nou) abans que finalment li tallessin l''últim cap.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0006d-7b93-7bd5-a5fe-6049f07d9198' AND updated_at <= '2026-08-27T14:17:20.353298Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0006d-7b93-7bd5-a5fe-6049f07d9198' AND updated_at <= '2026-08-27T14:17:20.353298Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a06c06-e3de-7dc0-8920-08b855728641', 'ca-ES', 'Usuari: Joseph Joestar

Enfiladisses porpres: Es manifesta com un conjunt de tiges o enfiladisses espinoses de color porpra que broten de les mans d''en Joseph.

Connexió amb l''Hamon: La seva forma de planta reflecteix l''energia vital de l''Hamon que en Joseph va dominar en la seva joventut.

Inspiració del tarot: Representa la carta del tarot L''Ermità (The Hermit), que simbolitza la introspecció i la meditació.', ARRAY['Psicografia (Endevinació Parcial)','Fuet d''espines','Induir hamon','Balancejar-se com Spiderman']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a06c06-e3de-7dc0-8920-08b855728641' AND updated_at <= '2026-09-27T14:32:05.171199Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a06c06-e3de-7dc0-8920-08b855728641' AND updated_at <= '2026-09-27T14:32:05.171199Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a06c06-e3de-7dc0-8920-08b855728641', 'en-GB', 'User: Joseph Joestar

Purple vines: Manifests as a cluster of thorny, purple-coloured stems or vines that sprout from Joseph''s hands.

Connection to Hamon: Its plant-like form reflects the vital Hamon energy Joseph mastered in his youth.

Tarot inspiration: Represents the tarot card The Hermit, symbolising introspection and meditation.', ARRAY['Psychography (Partial Divination)','Thorned whip','Induce Hamon','Swing like Spider-Man']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a06c06-e3de-7dc0-8920-08b855728641' AND updated_at <= '2026-09-27T14:32:05.171199Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a06c06-e3de-7dc0-8920-08b855728641' AND updated_at <= '2026-09-27T14:32:05.171199Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a06c06-e3de-7dc0-8920-08b855728641', 'es-ES', 'Usuario: Joseph Joestar

Enredaderas púrpuras: Se manifiesta como un conjunto de tallos o enredaderas espinosas de color morado que brotan de las manos de Joseph.

Conexión con el Hamon: Su forma de planta refleja la energía vital del Hamon que Joseph dominó en su juventud.

Inspiración del tarot: Representa la carta del tarot El Ermitaño (The Hermit), que simboliza la introspección y la meditación.', ARRAY['Psicografía (Adivinación Parcial)','Látigo de pinchos','Inducir hamon','Balancearse como Spiderman']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a06c06-e3de-7dc0-8920-08b855728641' AND updated_at <= '2026-09-27T14:32:05.171199Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a06c06-e3de-7dc0-8920-08b855728641' AND updated_at <= '2026-09-27T14:32:05.171199Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00085-4c7a-75e8-a9a4-6ba8bd8c6122', 'en-GB', 'Allows the user to create, control, and transform their body into ice, as well as freeze objects and living beings instantly.', ARRAY['Living Targets: Enemies frozen the user are suspended in animation; while fragile, they can survive if thawed carefully, but shattering them while frozen results in death.','Massive Scale: The user can instantly freeze vast expanses of open ocean for weeks at a time, allowing people to walk across or permitting him to ride his bicycle (Aokiji''s Chariot) directly over the sea.','Ice Constructs: The user can construct weapons out of pure ice, such as blades (Ice Saber), tridents (Ice Block: Pheasant Beak), or spears.','Prosthetic Replacement: After losing his left leg in his duel against Akainu on Punk Hazard, Kuzan continually uses his ice powers to create a fully functional prosthetic leg.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00085-4c7a-75e8-a9a4-6ba8bd8c6122' AND updated_at <= '2026-08-14T13:55:27.752705Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00085-4c7a-75e8-a9a4-6ba8bd8c6122' AND updated_at <= '2026-08-14T13:55:27.752705Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00085-4c7a-75e8-a9a4-6ba8bd8c6122', 'es-ES', 'Permite al usuario crear, controlar y transformar su cuerpo en hielo, además de congelar objetos y seres vivos al instante.', ARRAY['Objetivos Vivos: Los enemigos congelados por el usuario quedan suspendidos en animación; aunque frágiles, pueden sobrevivir si se los descongela con cuidado, pero destrozarlos mientras están congelados provoca la muerte.','Escala Masiva: El usuario puede congelar al instante enormes extensiones de mar abierto durante semanas, permitiendo que la gente camine sobre ellas o que él mismo circule directamente sobre el mar en su bicicleta (el Carro de Aokiji).','Construcciones de Hielo: El usuario puede fabricar armas de hielo puro, como espadas (Sable de Hielo), tridentes (Bloque de Hielo: Pico de Faisán) o lanzas.','Sustitución Protésica: Tras perder su pierna izquierda en su duelo contra Akainu en Punk Hazard, Kuzan usa constantemente sus poderes de hielo para crear una pierna protésica plenamente funcional.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00085-4c7a-75e8-a9a4-6ba8bd8c6122' AND updated_at <= '2026-08-14T13:55:27.752705Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00085-4c7a-75e8-a9a4-6ba8bd8c6122' AND updated_at <= '2026-08-14T13:55:27.752705Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00085-4c7a-75e8-a9a4-6ba8bd8c6122', 'ca-ES', 'Permet a l''usuari crear, controlar i transformar el seu cos en gel, a més de congelar objectes i éssers vius a l''instant.', ARRAY['Objectius Vius: Els enemics congelats per l''usuari queden suspesos en animació; encara que fràgils, poden sobreviure si es descongelen amb cura, però esmicolar-los mentre estan congelats provoca la mort.','Escala Massiva: L''usuari pot congelar a l''instant enormes extensions de mar obert durant setmanes, permetent que la gent hi camini a sobre o que ell mateix circuli directament sobre el mar amb la seva bicicleta (el Carro d''Aokiji).','Construccions de Gel: L''usuari pot fabricar armes de gel pur, com sabres (Sabre de Gel), tridents (Bloc de Gel: Bec de Faisà) o llances.','Substitució Protètica: Després de perdre la seva cama esquerra en el seu duel contra Akainu a Punk Hazard, Kuzan utilitza constantment els seus poders de gel per crear una cama protètica totalment funcional.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00085-4c7a-75e8-a9a4-6ba8bd8c6122' AND updated_at <= '2026-08-14T13:55:27.752705Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00085-4c7a-75e8-a9a4-6ba8bd8c6122' AND updated_at <= '2026-08-14T13:55:27.752705Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0003f-1da0-74bb-b69e-1d4029b80e72', 'en-GB', 'Its main power grants an animal or non-human entity the traits, physical form, and high-level intellect of a human. If a human were to eat this fruit he would become more "human".', ARRAY['Heavy Point (Human Form): A large, gorilla-like humanoid form with massive muscular build, suitable for heavy lifting and close-quarters combat.','Brain Point (Hybrid Form): A small, mascot-like tanuki/reindeer form that maximizes cognitive skills, medical focus, and battle strategy (Scope).','Walk Point (Beast Form): Chopper''s original reindeer form, ideal for high-speed travel and tracking by scent.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0003f-1da0-74bb-b69e-1d4029b80e72' AND updated_at <= '2026-08-14T15:40:26.248236Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0003f-1da0-74bb-b69e-1d4029b80e72' AND updated_at <= '2026-08-14T15:40:26.248236Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0003f-1da0-74bb-b69e-1d4029b80e72', 'es-ES', 'Su poder principal otorga a un animal o entidad no humana los rasgos, la forma física y la inteligencia de alto nivel de un ser humano. Si un humano comiera esta fruta, se volvería más «humano».', ARRAY['Heavy Point (Forma Humana): Una forma humanoide grande, de aspecto gorilesco, con una musculatura enorme, apta para levantar grandes pesos y para el combate cuerpo a cuerpo.','Brain Point (Forma Híbrida): Una forma pequeña, similar a una mascota, entre tanuki y reno, que maximiza las capacidades cognitivas, el enfoque médico y la estrategia de combate (Scope).','Walk Point (Forma Bestial): La forma original de reno de Chopper, ideal para desplazarse a alta velocidad y para rastrear por el olfato.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0003f-1da0-74bb-b69e-1d4029b80e72' AND updated_at <= '2026-08-14T15:40:26.248236Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0003f-1da0-74bb-b69e-1d4029b80e72' AND updated_at <= '2026-08-14T15:40:26.248236Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0003f-1da0-74bb-b69e-1d4029b80e72', 'ca-ES', 'El seu poder principal atorga a un animal o entitat no humana els trets, la forma física i la intel·ligència d''alt nivell d''un ésser humà. Si un humà mengés aquesta fruita, es tornaria més «humà».', ARRAY['Heavy Point (Forma Humana): Una forma humanoide gran, d''aspecte goril·lesc, amb una musculatura enorme, apta per aixecar grans pesos i per al combat cos a cos.','Brain Point (Forma Híbrida): Una forma petita, semblant a una mascota, entre tanuki i ren, que maximitza les capacitats cognitives, l''enfocament mèdic i l''estratègia de combat (Scope).','Walk Point (Forma Bestial): La forma original de ren d''en Chopper, ideal per desplaçar-se a alta velocitat i per rastrejar per l''olfacte.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0003f-1da0-74bb-b69e-1d4029b80e72' AND updated_at <= '2026-08-14T15:40:26.248236Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0003f-1da0-74bb-b69e-1d4029b80e72' AND updated_at <= '2026-08-14T15:40:26.248236Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000a0-ce8f-7047-a6de-ea57f71f44ca', 'ca-ES', 'Permet a l''usuari transformar-se en un imponent Daibutsu (Gran Buda) daurat, amb un immens poder físic i capacitat de generar ones de xoc.', ARRAY['Transformació Col·lossal Daurada: En transformar-se, l''usuari es converteix en una entitat gegantina amb forma d''estàtua d''or resplendent. En aquesta forma, la mida, la massa muscular i la resistència de l''usuari augmenten exponencialment, permetent-li suportar artilleria pesada i cops físics directes de lluitadors de primer nivell sense immutar-se.','Dany Massiu en Àrea: Un sol cop de palmell allibera una ona expansiva comprimida capaç de rivalitzar fàcilment amb el poder destructiu dels tremolors de la Gura Gura no Mi de Barbablanca.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000a0-ce8f-7047-a6de-ea57f71f44ca' AND updated_at <= '2026-08-14T14:15:34.359361Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000a0-ce8f-7047-a6de-ea57f71f44ca' AND updated_at <= '2026-08-14T14:15:34.359361Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000a0-ce8f-7047-a6de-ea57f71f44ca', 'en-GB', 'Allows the user to transform into a towering, golden Daibutsu (Giant Buddha) with immense physical power and shockwave generation.', ARRAY['Colossal Golden Transformation: Upon transformation, the user turns into a gigantic, gleaming gold statue-like entity. In this form, the user''s size, muscle mass, and durability increase exponentially, allowing them to withstand heavy artillery and direct physical strikes from high-tier fighters without flinching.','Massive AoE Damage: A single palm thrust releases a compressed blast wave capable of easily rivaling or matching the destructive power of Whitebeard''s Gura Gura no Mi tremors.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000a0-ce8f-7047-a6de-ea57f71f44ca' AND updated_at <= '2026-08-14T14:15:34.359361Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000a0-ce8f-7047-a6de-ea57f71f44ca' AND updated_at <= '2026-08-14T14:15:34.359361Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000a0-ce8f-7047-a6de-ea57f71f44ca', 'es-ES', 'Permite al usuario transformarse en un imponente Daibutsu (Gran Buda) dorado, con un inmenso poder físico y capacidad de generar ondas de choque.', ARRAY['Transformación Colosal Dorada: Al transformarse, el usuario se convierte en una entidad gigantesca con forma de estatua de oro reluciente. En esta forma, el tamaño, la masa muscular y la resistencia del usuario aumentan exponencialmente, permitiéndole soportar artillería pesada y golpes físicos directos de luchadores de primer nivel sin inmutarse.','Daño Masivo en Área: Un solo empujón con la palma libera una onda expansiva comprimida capaz de rivalizar fácilmente con el poder destructivo de los temblores de la Gura Gura no Mi de Barbablanca.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000a0-ce8f-7047-a6de-ea57f71f44ca' AND updated_at <= '2026-08-14T14:15:34.359361Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000a0-ce8f-7047-a6de-ea57f71f44ca' AND updated_at <= '2026-08-14T14:15:34.359361Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00036-b77d-79e6-84ad-b0fc8bc06b73', 'en-GB', 'The fruit embodies the legendary "Sun God" Nika, a figure worshipped in ancient times as a warrior of liberation who brought smiles, joy, and freedom to slaves and captives.', ARRAY['Mythical Zoan Classification: Unlike standard Zoan fruits that turn users into real-world animals, this fruit allows the user to transform into a legendary, deity-like figure with a rubber-like physical body.','Rubber Physiology: Standard punches, bullets, and falls bounce off harmlessly.','Kinetic Compressibility: By stretching and snapping back limbs, the user generates immense speed and power.','"Ridiculous" Freedom: Described as the most ridiculous power in the world, it allows the user to stretch, manipulate, and shape their body in surreal, cartoon-like ways limited only by their imagination.','Environmental Rubberization: The user can turn non-living surroundings—such as solid earth, concrete walls, floor tiles, and even lightning bolts—into springy rubber.','Organic Distortion: The user can apply rubber properties to living opponents upon contact, causing enemies'' eyes, faces, or bodies to stretch absurdly when hit.','Drums of Liberation: The user''s heartbeat shifts into a powerful, rhythmic beat known as the Drums of Liberation, which restores their energy, boosts physical power, and turns their hair and clothes pure white surrounded by a cloud-like hagoromo steam sash.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00036-b77d-79e6-84ad-b0fc8bc06b73' AND updated_at <= '2026-08-14T12:19:41.727275Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00036-b77d-79e6-84ad-b0fc8bc06b73' AND updated_at <= '2026-08-14T12:19:41.727275Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00036-b77d-79e6-84ad-b0fc8bc06b73', 'es-ES', 'La fruta encarna al legendario «Dios Sol» Nika, una figura venerada en la antigüedad como un guerrero de la liberación que trajo sonrisas, alegría y libertad a esclavos y cautivos.', ARRAY['Clasificación Zoan Mítica: A diferencia de las frutas Zoan estándar, que convierten al usuario en un animal real, esta fruta le permite transformarse en una figura legendaria de aspecto divino con un cuerpo físico similar al de la goma.','Fisiología de Goma: Los puñetazos, balas y caídas comunes rebotan sin causar daño.','Compresibilidad Cinética: Al estirar y contraer bruscamente sus extremidades, el usuario genera una velocidad y una fuerza inmensas.','Libertad «Ridícula»: Descrita como el poder más ridículo del mundo, permite al usuario estirar, manipular y moldear su cuerpo de formas surrealistas y caricaturescas, limitadas únicamente por su imaginación.','Engomado del Entorno: El usuario puede convertir el entorno no vivo —como tierra firme, paredes de hormigón, baldosas o incluso rayos— en goma elástica.','Distorsión Orgánica: El usuario puede aplicar propiedades de goma a oponentes vivos al contactar con ellos, haciendo que los ojos, las caras o los cuerpos de los enemigos se estiren de forma absurda al recibir un golpe.','Tambores de la Liberación: El latido del corazón del usuario cambia a un ritmo poderoso conocido como los Tambores de la Liberación, que restaura su energía, potencia su fuerza física y vuelve su cabello y su ropa completamente blancos, rodeados por una especie de faja de vapor parecida a un hagoromo de nubes.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00036-b77d-79e6-84ad-b0fc8bc06b73' AND updated_at <= '2026-08-14T12:19:41.727275Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00036-b77d-79e6-84ad-b0fc8bc06b73' AND updated_at <= '2026-08-14T12:19:41.727275Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00036-b77d-79e6-84ad-b0fc8bc06b73', 'ca-ES', 'La fruita encarna el llegendari «Déu Sol» Nika, una figura venerada en l''antiguitat com un guerrer de l''alliberament que va portar somriures, alegria i llibertat a esclaus i captius.', ARRAY['Classificació Zoan Mítica: A diferència de les fruites Zoan estàndard, que converteixen l''usuari en un animal real, aquesta fruita li permet transformar-se en una figura llegendària d''aspecte diví amb un cos físic semblant al del cautxú.','Fisiologia de Cautxú: Els cops de puny, les bales i les caigudes habituals reboten sense causar mal.','Compressibilitat Cinètica: En estirar i contreure bruscament les seves extremitats, l''usuari genera una velocitat i una força immenses.','Llibertat «Ridícula»: Descrita com el poder més ridícul del món, permet a l''usuari estirar, manipular i modelar el seu cos de formes surrealistes i caricaturesques, limitades únicament per la seva imaginació.','Engomament de l''Entorn: L''usuari pot convertir l''entorn no viu —com terra ferma, parets de formigó, rajoles o fins i tot llamps— en cautxú elàstic.','Distorsió Orgànica: L''usuari pot aplicar propietats de cautxú a oponents vius en contactar-hi, fent que els ulls, les cares o els cossos dels enemics s''estirin de manera absurda en rebre un cop.','Tambors de l''Alliberament: El batec del cor de l''usuari canvia a un ritme poderós conegut com els Tambors de l''Alliberament, que li restaura l''energia, li potencia la força física i li torna els cabells i la roba completament blancs, envoltats per una mena de faixa de vapor semblant a un hagoromo de núvols.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00036-b77d-79e6-84ad-b0fc8bc06b73' AND updated_at <= '2026-08-14T12:19:41.727275Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00036-b77d-79e6-84ad-b0fc8bc06b73' AND updated_at <= '2026-08-14T12:19:41.727275Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00028-ee04-79b5-a8bb-8ec511694063', 'en-GB', 'Its main power grants the user the ability to turn living people into toys with a single physical touch, while simultaneously erasing all public memory of that person''s existence.', ARRAY['Toy Transformation: Upon physical contact with the user''s hand, a living target is instantly transformed into a living toy (such as a nutcracker, tin soldier, or teddy bear).','Contract Enslavement: The user can form a binding verbal contract with the newly transformed toy, forcing them to obey every command without hesitation, even against their own will.','Perpetual Youth: Eating the fruit immediately halts the user''s physical aging process permanently, keeping them frozen at the physical age they were when they consumed it (Sugar stopped aging at 10 years old).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00028-ee04-79b5-a8bb-8ec511694063' AND updated_at <= '2026-08-14T12:04:38.157756Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00028-ee04-79b5-a8bb-8ec511694063' AND updated_at <= '2026-08-14T12:04:38.157756Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00028-ee04-79b5-a8bb-8ec511694063', 'es-ES', 'Su poder principal otorga al usuario la capacidad de convertir a personas vivas en juguetes con un simple contacto físico, borrando al mismo tiempo todo recuerdo público de la existencia de esa persona.', ARRAY['Transformación en Juguete: Al entrar en contacto físico con la mano del usuario, un objetivo vivo se transforma instantáneamente en un juguete viviente (como un cascanueces, un soldadito de plomo o un osito de peluche).','Esclavitud por Contrato: El usuario puede formar un contrato verbal vinculante con el juguete recién transformado, obligándolo a obedecer cualquier orden sin dudar, incluso en contra de su propia voluntad.','Juventud Perpetua: Comer la fruta detiene de inmediato y para siempre el envejecimiento físico del usuario, dejándolo congelado en la edad física que tenía al consumirla (Sugar dejó de envejecer a los 10 años).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00028-ee04-79b5-a8bb-8ec511694063' AND updated_at <= '2026-08-14T12:04:38.157756Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00028-ee04-79b5-a8bb-8ec511694063' AND updated_at <= '2026-08-14T12:04:38.157756Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00028-ee04-79b5-a8bb-8ec511694063', 'ca-ES', 'El seu poder principal atorga a l''usuari la capacitat de convertir persones vives en joguines amb un simple contacte físic, alhora que esborra tot record públic de l''existència d''aquesta persona.', ARRAY['Transformació en Joguina: En entrar en contacte físic amb la mà de l''usuari, un objectiu viu es transforma instantàniament en una joguina vivent (com un trencanous, un soldadet de plom o un osset de peluix).','Esclavitud per Contracte: L''usuari pot formar un contracte verbal vinculant amb la joguina acabada de transformar, obligant-la a obeir qualsevol ordre sense dubtar, fins i tot contra la seva pròpia voluntat.','Joventut Perpètua: Menjar la fruita atura de seguida i per sempre l''envelliment físic de l''usuari, deixant-lo congelat en l''edat física que tenia en consumir-la (Sugar va deixar d''envellir als 10 anys).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00028-ee04-79b5-a8bb-8ec511694063' AND updated_at <= '2026-08-14T12:04:38.157756Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00028-ee04-79b5-a8bb-8ec511694063' AND updated_at <= '2026-08-14T12:04:38.157756Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00016-3bb4-7b40-ac38-bbb683fef9eb', 'en-GB', 'Its main power allows the user to create and control ghosts (hollows) with a variety of unique status-altering and destructive effects.', ARRAY['Negative Hollows (Willpower Drain): The user can send ghostly figures passing directly through opponents'' bodies. Anyone touched by these ghosts is instantly overwhelmed by severe depression, self-loathing, and loss of morale, dropping to their knees and losing all will to fight.','Explosive Hollows (Mini-Hollows & Special Hollows): The user can spawn tiny or massive ghosts that attach to enemies or objects and detonate on command, causing high-impact concussive explosions.','Astral Projection: The user can detach their soul from their physical body to form an intangible spectral copy. In this form, they can fly through walls, change their size, communicate, and remain immune to physical attacks.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00016-3bb4-7b40-ac38-bbb683fef9eb' AND updated_at <= '2026-08-14T11:59:21.414041Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00016-3bb4-7b40-ac38-bbb683fef9eb' AND updated_at <= '2026-08-14T11:59:21.414041Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00016-3bb4-7b40-ac38-bbb683fef9eb', 'es-ES', 'Su poder principal permite al usuario crear y controlar fantasmas (hollows) con una variedad de efectos únicos, tanto destructivos como alteradores del estado de ánimo.', ARRAY['Hollows Negativos (Drenaje de Voluntad): El usuario puede enviar figuras fantasmales que atraviesan directamente los cuerpos de los oponentes. Cualquiera que sea tocado por estos fantasmas se ve abrumado al instante por una depresión severa, autodesprecio y pérdida de la moral, cayendo de rodillas y perdiendo todas las ganas de luchar.','Hollows Explosivos (Mini-Hollows y Hollows Especiales): El usuario puede generar fantasmas diminutos o enormes que se adhieren a enemigos u objetos y detonan a su orden, causando explosiones conmocionadoras de gran impacto.','Proyección Astral: El usuario puede separar su alma de su cuerpo físico para formar una copia espectral e intangible. En esta forma, puede volar a través de paredes, cambiar de tamaño, comunicarse y permanecer inmune a los ataques físicos.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00016-3bb4-7b40-ac38-bbb683fef9eb' AND updated_at <= '2026-08-14T11:59:21.414041Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00016-3bb4-7b40-ac38-bbb683fef9eb' AND updated_at <= '2026-08-14T11:59:21.414041Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00016-3bb4-7b40-ac38-bbb683fef9eb', 'ca-ES', 'El seu poder principal permet a l''usuari crear i controlar fantasmes (hollows) amb una varietat d''efectes únics, tant destructius com alteradors de l''estat d''ànim.', ARRAY['Hollows Negatius (Drenatge de Voluntat): L''usuari pot enviar figures fantasmals que travessen directament els cossos dels oponents. Qualsevol que sigui tocat per aquests fantasmes queda aclaparat a l''instant per una depressió severa, autodespreci i pèrdua de la moral, caient de genolls i perdent totes les ganes de lluitar.','Hollows Explosius (Mini-Hollows i Hollows Especials): L''usuari pot generar fantasmes minúsculs o enormes que s''enganxen a enemics o objectes i detonen a la seva ordre, causant explosions commocionants de gran impacte.','Projecció Astral: L''usuari pot separar la seva ànima del seu cos físic per formar una còpia espectral i intangible. En aquesta forma, pot volar a través de parets, canviar de mida, comunicar-se i romandre immune als atacs físics.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00016-3bb4-7b40-ac38-bbb683fef9eb' AND updated_at <= '2026-08-14T11:59:21.414041Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00016-3bb4-7b40-ac38-bbb683fef9eb' AND updated_at <= '2026-08-14T11:59:21.414041Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000a7-6d1a-7dc0-96e7-48682de828b0', 'ca-ES', 'Permet que un objecte o ésser viu es transformi en un dachshund complet o en un estat híbrid de dachshund.', ARRAY['Bombes Esternudades: Com que Lassoo és un híbrid vivent de gos i arma de foc que pateix constipats constants, cada vegada que esternuda dispara pel morro una pesada bomba de beisbol explosiva amb temporitzador.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000a7-6d1a-7dc0-96e7-48682de828b0' AND updated_at <= '2026-08-14T14:22:48.262496Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000a7-6d1a-7dc0-96e7-48682de828b0' AND updated_at <= '2026-08-14T14:22:48.262496Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000a7-6d1a-7dc0-96e7-48682de828b0', 'en-GB', 'Allows an object or living being to transform into a full dachshund or a dachshund-hybrid state.', ARRAY['Sneezing Bombs: Because Lassoo is a living dog-gun hybrid that suffers from constant sniffles, every time he sneezes, he fires a heavy, timed explosive baseball bomb out of his snout.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000a7-6d1a-7dc0-96e7-48682de828b0' AND updated_at <= '2026-08-14T14:22:48.262496Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000a7-6d1a-7dc0-96e7-48682de828b0' AND updated_at <= '2026-08-14T14:22:48.262496Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000a7-6d1a-7dc0-96e7-48682de828b0', 'es-ES', 'Permite que un objeto o ser vivo se transforme en un dachshund completo o en un estado híbrido de dachshund.', ARRAY['Bombas Estornudadas: Como Lassoo es un híbrido viviente de perro y arma de fuego que sufre resfriados constantes, cada vez que estornuda dispara por el hocico una pesada bomba de béisbol explosiva con temporizador.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000a7-6d1a-7dc0-96e7-48682de828b0' AND updated_at <= '2026-08-14T14:22:48.262496Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000a7-6d1a-7dc0-96e7-48682de828b0' AND updated_at <= '2026-08-14T14:22:48.262496Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000a9-f472-75e4-9a50-c2ba8a5eeef7', 'ca-ES', 'Permet a l''usuari transformar-se a voluntat en un híbrid humà-xacal o en un xacal complet, atorgant-li velocitat canina, agilitat i instints de combat predadors.', ARRAY['Agilitat i velocitat millorades: En la seva forma híbrida, l''usuari adquireix extremitats llargues i esveltes i una fisiologia canina lleugera, cosa que li permet saltar grans distàncies, esquivar cops ràpids i moure''s amb gran agilitat.','Agressivitat Zoan carnívora: En ser una Zoan carnívora, aquesta fruita proporciona un augment més gran de la força física i dels instints de combat en comparació amb els tipus Zoan herbívors.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000a9-f472-75e4-9a50-c2ba8a5eeef7' AND updated_at <= '2026-08-14T14:25:33.918197Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000a9-f472-75e4-9a50-c2ba8a5eeef7' AND updated_at <= '2026-08-14T14:25:33.918197Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000a9-f472-75e4-9a50-c2ba8a5eeef7', 'en-GB', 'Allows the user to transform into a jackal-human hybrid or a full jackal at will, granting canine speed, agility, and predatory combat instincts.', ARRAY['Enhanced Agility & Speed: In his hybrid form, the user gains long, slender limbs and lightweight canine physiology, allowing him to leap great distances, dodge rapid strikes, and move with swift agility.','Carnivorous Zoan Aggression: As a carnivorous Zoan, this fruit provides a larger boost to physical strength and combat instincts compared to herbivorous Zoan types.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000a9-f472-75e4-9a50-c2ba8a5eeef7' AND updated_at <= '2026-08-14T14:25:33.918197Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000a9-f472-75e4-9a50-c2ba8a5eeef7' AND updated_at <= '2026-08-14T14:25:33.918197Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000a9-f472-75e4-9a50-c2ba8a5eeef7', 'es-ES', 'Permite al usuario transformarse a voluntad en un híbrido humano-chacal o en un chacal completo, otorgándole velocidad canina, agilidad e instintos de combate predatorios.', ARRAY['Agilidad y velocidad mejoradas: En su forma híbrida, el usuario adquiere extremidades largas y esbeltas y una fisiología canina ligera, lo que le permite saltar grandes distancias, esquivar golpes rápidos y moverse con gran agilidad.','Agresividad Zoan carnívora: Al ser una Zoan carnívora, esta fruta proporciona un mayor aumento de la fuerza física y de los instintos de combate en comparación con los tipos Zoan herbívoros.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000a9-f472-75e4-9a50-c2ba8a5eeef7' AND updated_at <= '2026-08-14T14:25:33.918197Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000a9-f472-75e4-9a50-c2ba8a5eeef7' AND updated_at <= '2026-08-14T14:25:33.918197Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000af-3d08-78d7-9b27-3afde9473ddc', 'es-ES', 'Permite al usuario transformarse en un mítico zorro de nueve colas o en un híbrido humano-zorro, otorgándole mejoras físicas junto con una capacidad de metamorfosis impecable.', ARRAY['Disfraz completo: A diferencia de las ilusiones ópticas estándar, la transformación imita al objetivo hasta en su ropa y presencia física, engañando sin esfuerzo a sus allegados.','Copia por contacto: Al tocar físicamente a un objetivo, el usuario puede almacenar permanentemente su apariencia para transformarse en él más tarde a voluntad.','Forma colosal de nueve colas: En su forma bestial completa, el usuario se convierte en un zorro gigantesco con nueve colas tupidas y esponjosas, capaces de aplastar a sus oponentes o de arrasar grandes áreas.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000af-3d08-78d7-9b27-3afde9473ddc' AND updated_at <= '2026-08-14T14:31:30.692065Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000af-3d08-78d7-9b27-3afde9473ddc' AND updated_at <= '2026-08-14T14:31:30.692065Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000af-3d08-78d7-9b27-3afde9473ddc', 'ca-ES', 'Permet a l''usuari transformar-se en un mític guineu de nou cues o en un híbrid humà-guineu, atorgant-li millores físiques juntament amb una capacitat de metamorfosi impecable.', ARRAY['Disfressa completa: A diferència de les il·lusions òptiques estàndard, la transformació imita l''objectiu fins i tot en la seva roba i presència física, enganyant sense esforç els seus coneguts propers.','Còpia per contacte: En tocar físicament un objectiu, l''usuari pot emmagatzemar permanentment la seva aparença per transformar-s''hi més endavant a voluntat.','Forma colossal de nou cues: En la seva forma bestial completa, l''usuari es converteix en un guineu gegantí amb nou cues espesses i esponjoses, capaces d''aixafar els oponents o d''escombrar grans àrees.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000af-3d08-78d7-9b27-3afde9473ddc' AND updated_at <= '2026-08-14T14:31:30.692065Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000af-3d08-78d7-9b27-3afde9473ddc' AND updated_at <= '2026-08-14T14:31:30.692065Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000af-3d08-78d7-9b27-3afde9473ddc', 'en-GB', 'Allows the user to transform into a mythical nine-tailed fox or a fox-human hybrid, granting physical enhancements along with flawless shapeshifting capabilities.', ARRAY['Complete Disguise: Unlike standard optical illusions, the transformation mimics the target down to their clothing and physical presence, effortlessly fooling close acquaintances.','Touch-Based Copying: By physically touching a target, the user can permanently store their likeness to transform into them later at will.','Colossal Nine-Tailed Form: In full beast form, the user turns into a gigantic fox with nine bushy, fluffy tails capable of crushing opponents or sweeping across large areas.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000af-3d08-78d7-9b27-3afde9473ddc' AND updated_at <= '2026-08-14T14:31:30.692065Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000af-3d08-78d7-9b27-3afde9473ddc' AND updated_at <= '2026-08-14T14:31:30.692065Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0006f-a6be-7367-acc7-fd370f368826', 'en-GB', 'Based on the O-Kuchi no Makami, a sacred wolf spirit in Japanese mythology praised as a divine guardian deity. In the story, Kaidou notes that this wolf is considered the protector spirit of Wano Country.', ARRAY['Beast Form: Full transformation into a sleek, majestic, white mythical wolf with incredible physical capabilities.','Hybrid Form: Merges wolf features (fur, sharp teeth, ears, tail, and claws) with the user''s humanoid frame, optimizing both weapon skill and animalistic power. In this state, a sacred flame-like cloud trail drapes over the user''s shoulders.','Glacial Breath (Namuji Hyoho): Fires intense streams of sub-zero frost directly from the mouth, powerful enough to clash evenly with Kaidou’s Boro Breath (Blast Breath).','Ice Armor (Kagami Mountain): Enables the user to coat their body in a thick layer of ice, acting as armor to absorb heavy physical and elemental damage.','Frost Attacks: Infuses weapons and physical attacks with freezing energy to immobilize or freeze opponents upon contact.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0006f-a6be-7367-acc7-fd370f368826' AND updated_at <= '2026-08-14T13:22:09.979733Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0006f-a6be-7367-acc7-fd370f368826' AND updated_at <= '2026-08-14T13:22:09.979733Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0006f-a6be-7367-acc7-fd370f368826', 'es-ES', 'Basada en el O-Kuchi no Makami, un espíritu lobuno sagrado de la mitología japonesa venerado como una deidad guardiana divina. En la historia, Kaidou señala que este lobo es considerado el espíritu protector del País de Wano.', ARRAY['Forma bestial: Transformación completa en un mítico lobo blanco, esbelto y majestuoso, con capacidades físicas increíbles.','Forma híbrida: Fusiona rasgos de lobo (pelaje, dientes afilados, orejas, cola y garras) con el cuerpo humanoide del usuario, optimizando tanto la destreza con armas como el poder animal. En este estado, una estela sagrada en forma de nube llameante cubre los hombros del usuario.','Aliento glacial (Namuji Hyoho): Dispara intensas corrientes de escarcha bajo cero directamente desde la boca, con la potencia suficiente para enfrentarse en igualdad de condiciones al Boro Breath (Aliento Explosivo) de Kaidou.','Armadura de hielo (Kagami Mountain): Permite al usuario recubrir su cuerpo con una gruesa capa de hielo, que actúa como armadura para absorber daño físico y elemental de gran intensidad.','Ataques de escarcha: Impregna armas y ataques físicos con energía congelante para inmovilizar o congelar a los oponentes al contacto.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0006f-a6be-7367-acc7-fd370f368826' AND updated_at <= '2026-08-14T13:22:09.979733Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0006f-a6be-7367-acc7-fd370f368826' AND updated_at <= '2026-08-14T13:22:09.979733Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0006f-a6be-7367-acc7-fd370f368826', 'ca-ES', 'Basada en l''O-Kuchi no Makami, un esperit llop sagrat de la mitologia japonesa venerat com una deïtat guardiana divina. A la història, Kaidou assenyala que aquest llop és considerat l''esperit protector del País de Wano.', ARRAY['Forma bestial: Transformació completa en un mític llop blanc, esvelt i majestuós, amb capacitats físiques increïbles.','Forma híbrida: Fusiona trets de llop (pelatge, dents afilades, orelles, cua i urpes) amb el cos humanoide de l''usuari, optimitzant tant la destresa amb armes com el poder animal. En aquest estat, una estela sagrada en forma de núvol flamejant cobreix les espatlles de l''usuari.','Alè glacial (Namuji Hyoho): Dispara intenses corrents de gebre sota zero directament des de la boca, amb la potència suficient per enfrontar-se en igualtat de condicions al Boro Breath (Alè Explosiu) de Kaidou.','Armadura de gel (Kagami Mountain): Permet a l''usuari recobrir el seu cos amb una gruixuda capa de gel, que actua com a armadura per absorbir dany físic i elemental d''alta intensitat.','Atacs de gebre: Impregna armes i atacs físics amb energia congelant per immobilitzar o congelar els oponents en contacte.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0006f-a6be-7367-acc7-fd370f368826' AND updated_at <= '2026-08-14T13:22:09.979733Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0006f-a6be-7367-acc7-fd370f368826' AND updated_at <= '2026-08-14T13:22:09.979733Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000ab-b3a2-74cb-b9dd-ef7409473959', 'en-GB', 'Allows the user to transform into a wolf-human hybrid or a full wolf at will, gaining sharp fangs, predatory instincts, and enhanced physical speed and strength.', ARRAY['Razor-Sharp Claws & Fangs: Allows for lethal slashing and biting attacks.','Predatory Speed & Reflexes: Boosts agility, leap distance, and acceleration.','Enhanced Shigan (Finger Gun): His lengthened wolf claws turn his Shigan thrusts into sharp, piercing talon strikes (Gekkou).','Enhanced Rankyaku (Tempest Kick): His longer legs in hybrid form increase the range and cutting power of air-slash kicks.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000ab-b3a2-74cb-b9dd-ef7409473959' AND updated_at <= '2026-08-14T14:27:28.52797Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000ab-b3a2-74cb-b9dd-ef7409473959' AND updated_at <= '2026-08-14T14:27:28.52797Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000ab-b3a2-74cb-b9dd-ef7409473959', 'es-ES', 'Permite al usuario transformarse a voluntad en un híbrido humano-lobo o en un lobo completo, obteniendo colmillos afilados, instintos predatorios y velocidad y fuerza físicas mejoradas.', ARRAY['Garras y colmillos afiladísimos: Permiten ataques letales de corte y mordisco.','Velocidad y reflejos predatorios: Aumentan la agilidad, la distancia de salto y la aceleración.','Shigan (Pistola de Dedo) mejorado: Sus garras de lobo alargadas convierten sus embestidas de Shigan en golpes afilados y penetrantes de garra (Gekkou).','Rankyaku (Patada Tempestad) mejorado: Sus piernas más largas en forma híbrida aumentan el alcance y el poder de corte de las patadas que cortan el aire.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000ab-b3a2-74cb-b9dd-ef7409473959' AND updated_at <= '2026-08-14T14:27:28.52797Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000ab-b3a2-74cb-b9dd-ef7409473959' AND updated_at <= '2026-08-14T14:27:28.52797Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000ab-b3a2-74cb-b9dd-ef7409473959', 'ca-ES', 'Permet a l''usuari transformar-se a voluntat en un híbrid humà-llop o en un llop complet, obtenint ullals afilats, instints predadors i velocitat i força físiques millorades.', ARRAY['Urpes i ullals esmolats com navalles: Permeten atacs letals de tall i mossegada.','Velocitat i reflexos predadors: Augmenten l''agilitat, la distància de salt i l''acceleració.','Shigan (Pistola de Dit) millorat: Les seves urpes de llop allargades converteixen les seves envestides de Shigan en cops afilats i penetrants de garra (Gekkou).','Rankyaku (Puntada de Tempesta) millorat: Les seves cames més llargues en forma híbrida augmenten l''abast i el poder de tall de les puntades que tallen l''aire.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000ab-b3a2-74cb-b9dd-ef7409473959' AND updated_at <= '2026-08-14T14:27:28.52797Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000ab-b3a2-74cb-b9dd-ef7409473959' AND updated_at <= '2026-08-14T14:27:28.52797Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00010-8421-7b44-a104-ba099c9ff4f1', 'en-GB', 'Its main power allows the user to create and manipulate razor-sharp, extremely durable strings from their body, primarily from their hands and fingertips.', ARRAY['Puppeteering (Parasite): The user can attach invisible strings to people''s bodies, controlling their movements like marionettes against their will.','Sharp Cutting Power: The strings can be as fine as thread yet sharp enough to slice through solid stone, steel, and even meteorites effortlessly.','Aerial Traversal (Sky Knight): By attaching strings to clouds in the sky, the user can swing through the air at high speeds, effectively flying across open ocean stretches.','Internal First Aid: The user can use strings internally to stitch together damaged organs and blood vessels, acting as an emergency medical repair system to survive fatal injuries.','Overheat & Clones: The user can shoot high-density string whips that generate intense heat (Overheat) or weave autonomous string clones (Black Knight) that can fight independently.','Environmental Transmutation: He can extend his power outward, instantly transforming non-living surroundings—such as ground, buildings, and streets—into massive streams of controllable strings.','Birdcage: The user can cast an immense dome of indestructible, razor-sharp string walls across an entire island. The cage slowly contracts over time, cutting through everything in its path and blocking all communication signals outside the perimeter.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00010-8421-7b44-a104-ba099c9ff4f1' AND updated_at <= '2026-08-14T11:56:28.190736Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00010-8421-7b44-a104-ba099c9ff4f1' AND updated_at <= '2026-08-14T11:56:28.190736Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00010-8421-7b44-a104-ba099c9ff4f1', 'es-ES', 'Su poder principal permite al usuario crear y manipular hilos extremadamente resistentes y afilados como cuchillas desde su cuerpo, principalmente desde sus manos y yemas de los dedos.', ARRAY['Titiritero (Parásito): El usuario puede sujetar hilos invisibles a los cuerpos de las personas, controlando sus movimientos como marionetas en contra de su voluntad.','Poder de corte afilado: Los hilos pueden ser tan finos como un hilo de coser, pero lo bastante afilados como para cortar piedra sólida, acero e incluso meteoritos sin esfuerzo.','Desplazamiento aéreo (Sky Knight): Sujetando hilos a las nubes del cielo, el usuario puede balancearse por el aire a gran velocidad, volando en la práctica sobre grandes extensiones de océano abierto.','Primeros auxilios internos: El usuario puede usar hilos internamente para suturar órganos y vasos sanguíneos dañados, actuando como un sistema de reparación médica de emergencia para sobrevivir a heridas mortales.','Sobrecalentamiento y clones: El usuario puede disparar látigos de hilo de alta densidad que generan un calor intenso (Overheat) o tejer clones autónomos de hilo (Black Knight) que pueden luchar de forma independiente.','Transmutación del entorno: Puede extender su poder hacia el exterior, transformando instantáneamente el entorno no vivo —como el suelo, los edificios y las calles— en enormes corrientes de hilos controlables.','Jaula de pájaros: El usuario puede desplegar una inmensa cúpula de muros de hilo indestructibles y afilados como cuchillas sobre toda una isla. La jaula se contrae lentamente con el tiempo, cortando todo a su paso y bloqueando cualquier señal de comunicación fuera del perímetro.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00010-8421-7b44-a104-ba099c9ff4f1' AND updated_at <= '2026-08-14T11:56:28.190736Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00010-8421-7b44-a104-ba099c9ff4f1' AND updated_at <= '2026-08-14T11:56:28.190736Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00010-8421-7b44-a104-ba099c9ff4f1', 'ca-ES', 'El seu poder principal permet a l''usuari crear i manipular fils extremadament resistents i esmolats com fulles des del seu cos, principalment des de les seves mans i les puntes dels dits.', ARRAY['Titellaire (Paràsit): L''usuari pot subjectar fils invisibles als cossos de les persones, controlant els seus moviments com a titelles en contra de la seva voluntat.','Poder de tall esmolat: Els fils poden ser tan fins com un fil de cosir, però prou esmolats per tallar pedra sòlida, acer i fins i tot meteorits sense esforç.','Desplaçament aeri (Sky Knight): En subjectar fils als núvols del cel, l''usuari pot gronxar-se per l''aire a gran velocitat, volant a la pràctica sobre grans extensions d''oceà obert.','Primers auxilis interns: L''usuari pot fer servir fils internament per suturar òrgans i vasos sanguinis danyats, actuant com un sistema de reparació mèdica d''emergència per sobreviure a ferides mortals.','Sobreescalfament i clons: L''usuari pot disparar fuets de fil d''alta densitat que generen una calor intensa (Overheat) o teixir clons autònoms de fil (Black Knight) que poden lluitar de manera independent.','Transmutació de l''entorn: Pot estendre el seu poder cap a l''exterior, transformant instantàniament l''entorn no viu —com el terra, els edificis i els carrers— en enormes corrents de fils controlables.','Gàbia d''ocells: L''usuari pot desplegar una immensa cúpula de murs de fil indestructibles i esmolats com fulles sobre tota una illa. La gàbia es contrau lentament amb el temps, tallant-ho tot al seu pas i bloquejant qualsevol senyal de comunicació fora del perímetre.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00010-8421-7b44-a104-ba099c9ff4f1' AND updated_at <= '2026-08-14T11:56:28.190736Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00010-8421-7b44-a104-ba099c9ff4f1' AND updated_at <= '2026-08-14T11:56:28.190736Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00020-b688-73b7-84d1-4b401d7b8f3c', 'en-GB', 'Its main power grants the user the ability to create and manipulate magnetic forces, turning their body into a living human electromagnet capable of attracting and repelling metals.', ARRAY['Metal Attraction & Repulsion: The user can instantly pull vast quantities of metal, weapons, scrap iron, and heavy artillery toward themselves or repel incoming metallic projectiles at high speed.','Construct Assembly: By assembling scrap metal onto their body, the user can form colossal limbs, giant robotic armor, multi-jointed mechanical monsters (Punk Gibson), or massive scrap-built weapons like a electromagnetic railgun (Damned Punk).','Defensive Scrap Shielding: The user can gather dense walls of iron and steel around themselves to absorb incoming high-impact physical attacks or cannonballs.','Assign: The user can assign magnetic polarity (North or South) to living beings or non-metallic objects by touching them.','Magnetic Attraction Traps (Punk Crash): Once magnetic polarity is assigned to an opponent or surface, surrounding scrap metal and iron structures violently rush toward the target, trapping or crushing them under tons of crushing metal weight.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00020-b688-73b7-84d1-4b401d7b8f3c' AND updated_at <= '2026-08-14T11:55:39.604465Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00020-b688-73b7-84d1-4b401d7b8f3c' AND updated_at <= '2026-08-14T11:55:39.604465Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00020-b688-73b7-84d1-4b401d7b8f3c', 'es-ES', 'Su poder principal otorga al usuario la capacidad de crear y manipular fuerzas magnéticas, convirtiendo su cuerpo en un electroimán humano viviente capaz de atraer y repeler metales.', ARRAY['Atracción y repulsión de metal: El usuario puede atraer instantáneamente hacia sí grandes cantidades de metal, armas, chatarra de hierro y artillería pesada, o repeler a gran velocidad los proyectiles metálicos entrantes.','Ensamblaje de construcciones: Al ensamblar chatarra sobre su cuerpo, el usuario puede formar extremidades colosales, una armadura robótica gigante, monstruos mecánicos multiarticulados (Punk Gibson) o armas masivas construidas con chatarra, como un cañón electromagnético de riel (Damned Punk).','Blindaje defensivo de chatarra: El usuario puede reunir densos muros de hierro y acero a su alrededor para absorber ataques físicos de gran impacto o balas de cañón.','Asignar: El usuario puede asignar polaridad magnética (Norte o Sur) a seres vivos u objetos no metálicos con solo tocarlos.','Trampas de atracción magnética (Punk Crash): Una vez asignada la polaridad magnética a un oponente o superficie, la chatarra y las estructuras de hierro circundantes se precipitan violentamente hacia el objetivo, atrapándolo o aplastándolo bajo toneladas de metal.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00020-b688-73b7-84d1-4b401d7b8f3c' AND updated_at <= '2026-08-14T11:55:39.604465Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00020-b688-73b7-84d1-4b401d7b8f3c' AND updated_at <= '2026-08-14T11:55:39.604465Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00020-b688-73b7-84d1-4b401d7b8f3c', 'ca-ES', 'El seu poder principal atorga a l''usuari la capacitat de crear i manipular forces magnètiques, convertint el seu cos en un electroimant humà vivent capaç d''atreure i repel·lir metalls.', ARRAY['Atracció i repulsió de metall: L''usuari pot atreure instantàniament cap a si mateix grans quantitats de metall, armes, ferralla de ferro i artilleria pesant, o repel·lir a gran velocitat els projectils metàl·lics entrants.','Muntatge de construccions: En muntar ferralla sobre el seu cos, l''usuari pot formar extremitats colossals, una armadura robòtica gegant, monstres mecànics multiarticulats (Punk Gibson) o armes massives construïdes amb ferralla, com un canó electromagnètic de rail (Damned Punk).','Blindatge defensiu de ferralla: L''usuari pot reunir murs densos de ferro i acer al seu voltant per absorbir atacs físics de gran impacte o bales de canó.','Assignar: L''usuari pot assignar polaritat magnètica (Nord o Sud) a éssers vius o objectes no metàl·lics tan sols tocant-los.','Trampes d''atracció magnètica (Punk Crash): Un cop assignada la polaritat magnètica a un oponent o superfície, la ferralla i les estructures de ferro del voltant es precipiten violentament cap a l''objectiu, atrapant-lo o aixafant-lo sota tones de metall.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00020-b688-73b7-84d1-4b401d7b8f3c' AND updated_at <= '2026-08-14T11:55:39.604465Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00020-b688-73b7-84d1-4b401d7b8f3c' AND updated_at <= '2026-08-14T11:55:39.604465Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0001c-1599-7334-95ba-e730218a2e73', 'en-GB', 'Its main power grants the user the ability to manifest, manipulate, and sever shadows as physical, tangible entities.', ARRAY['Doppelman (Autonomous Shadow): The user can manifest their own shadow into a semi-liquid, indestructible entity that fights on their behalf. The shadow can shape-shift into weapon blades, swarms of bats, or shields.','Shadow Swap (Doppelman Switch): The user can instantly swap physical locations with their shadow at any time, making direct hits against them extremely difficult to land.','Shadow Extraction: Using special shears, the user can physically cut a person''s shadow away from their body. The stolen shadow retains the original owner''s personality traits, combat skills, and techniques.','Zombie Creation: By inserting a stolen shadow into a corpse, the user creates an obedient zombie soldier possessing the physical traits of the corpse and the fighting skills of the shadow''s owner.','Shadow Consumption (Shadow''s Asgard): The user can absorb stolen shadows directly into their own physical body to gain massive increases in physical size, brute strength, and power.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0001c-1599-7334-95ba-e730218a2e73' AND updated_at <= '2026-08-14T11:50:36.332103Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0001c-1599-7334-95ba-e730218a2e73' AND updated_at <= '2026-08-14T11:50:36.332103Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0001c-1599-7334-95ba-e730218a2e73', 'ca-ES', 'El seu poder principal atorga a l''usuari la capacitat de manifestar, manipular i separar ombres com a entitats físiques i tangibles.', ARRAY['Doppelman (Ombra autònoma): L''usuari pot manifestar la seva pròpia ombra en una entitat semilíquida i indestructible que lluita en el seu nom. L''ombra pot transformar-se en fulles d''arma, eixams de ratpenats o escuts.','Intercanvi d''ombra (Doppelman Switch): L''usuari pot intercanviar instantàniament la seva posició física amb la de la seva ombra en qualsevol moment, cosa que fa extremadament difícil encertar-lo amb cops directes.','Extracció d''ombra: Fent servir unes tisores especials, l''usuari pot tallar físicament l''ombra d''una persona i separar-la del seu cos. L''ombra robada conserva els trets de personalitat, les habilitats de combat i les tècniques del seu propietari original.','Creació de zombis: En inserir una ombra robada en un cadàver, l''usuari crea un soldat zombi obedient que posseeix els trets físics del cadàver i les habilitats de combat del propietari de l''ombra.','Consum d''ombres (Shadow''s Asgard): L''usuari pot absorbir ombres robades directament dins el seu propi cos físic per obtenir augments massius de mida física, força bruta i poder.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0001c-1599-7334-95ba-e730218a2e73' AND updated_at <= '2026-08-14T11:50:36.332103Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0001c-1599-7334-95ba-e730218a2e73' AND updated_at <= '2026-08-14T11:50:36.332103Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0001c-1599-7334-95ba-e730218a2e73', 'es-ES', 'Su poder principal otorga al usuario la capacidad de manifestar, manipular y separar sombras como entidades físicas y tangibles.', ARRAY['Doppelman (Sombra autónoma): El usuario puede manifestar su propia sombra en una entidad semilíquida e indestructible que lucha en su nombre. La sombra puede transformarse en hojas de arma, enjambres de murciélagos o escudos.','Intercambio de sombra (Doppelman Switch): El usuario puede intercambiar instantáneamente su posición física con la de su sombra en cualquier momento, lo que hace extremadamente difícil acertarle con golpes directos.','Extracción de sombra: Usando unas tijeras especiales, el usuario puede cortar físicamente la sombra de una persona y separarla de su cuerpo. La sombra robada conserva los rasgos de personalidad, las habilidades de combate y las técnicas de su propietario original.','Creación de zombis: Al insertar una sombra robada en un cadáver, el usuario crea un soldado zombi obediente que posee los rasgos físicos del cadáver y las habilidades de combate del propietario de la sombra.','Consumo de sombras (Shadow''s Asgard): El usuario puede absorber sombras robadas directamente en su propio cuerpo físico para obtener aumentos masivos de tamaño físico, fuerza bruta y poder.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0001c-1599-7334-95ba-e730218a2e73' AND updated_at <= '2026-08-14T11:50:36.332103Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0001c-1599-7334-95ba-e730218a2e73' AND updated_at <= '2026-08-14T11:50:36.332103Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000f0-b035-7ede-b203-d6f0bf8d24fa', 'en-GB', 'Allows the user to transform into a turtle or a turtle hybrid, granting an exceptionally hard shell that provides near-impenetrable defensive coverage.', ARRAY['Bullet & Explosive Deflection: The user can retract his head, arms, and legs inside his shell to completely negate incoming damage, effortlessly deflecting heavy automatic gunfire, cannonballs, and machine-gun strikes.','Hardness Beyond Diamond: According to Pekoms, his turtle shell is harder than steel or diamond, making standard physical attacks ineffective without advanced Haki or specialized armor-piercing techniques.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000f0-b035-7ede-b203-d6f0bf8d24fa' AND updated_at <= '2026-08-14T15:42:49.513852Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000f0-b035-7ede-b203-d6f0bf8d24fa' AND updated_at <= '2026-08-14T15:42:49.513852Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000f0-b035-7ede-b203-d6f0bf8d24fa', 'es-ES', 'Permite al usuario transformarse en una tortuga o en un híbrido de tortuga, otorgándole un caparazón excepcionalmente duro que proporciona una cobertura defensiva casi impenetrable.', ARRAY['Desviación de balas y explosivos: El usuario puede retraer la cabeza, los brazos y las piernas dentro de su caparazón para anular por completo el daño entrante, desviando sin esfuerzo fuego automático pesado, balas de cañón y ráfagas de ametralladora.','Dureza superior al diamante: Según Pekoms, su caparazón de tortuga es más duro que el acero o el diamante, lo que hace que los ataques físicos estándar sean ineficaces sin Haki avanzado o técnicas especializadas perforantes de armadura.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000f0-b035-7ede-b203-d6f0bf8d24fa' AND updated_at <= '2026-08-14T15:42:49.513852Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000f0-b035-7ede-b203-d6f0bf8d24fa' AND updated_at <= '2026-08-14T15:42:49.513852Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000f0-b035-7ede-b203-d6f0bf8d24fa', 'ca-ES', 'Permet a l''usuari transformar-se en una tortuga o en un híbrid de tortuga, atorgant-li una closca excepcionalment dura que proporciona una cobertura defensiva gairebé impenetrable.', ARRAY['Desviació de bales i explosius: L''usuari pot retreure el cap, els braços i les cames dins la seva closca per anul·lar completament el dany entrant, desviant sense esforç foc automàtic pesant, bales de canó i ràfegues de metralladora.','Duresa superior al diamant: Segons Pekoms, la seva closca de tortuga és més dura que l''acer o el diamant, cosa que fa que els atacs físics estàndard siguin ineficaços sense Haki avançat o tècniques especialitzades perforants d''armadura.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000f0-b035-7ede-b203-d6f0bf8d24fa' AND updated_at <= '2026-08-14T15:42:49.513852Z'::timestamptz)
