  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000f0-b035-7ede-b203-d6f0bf8d24fa' AND updated_at <= '2026-08-14T15:42:49.513852Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019ffffc-745d-708f-a68b-25e67ba43213', 'en-GB', 'Its main power allows the user to drastically alter their weight at will, anywhere from 1 kilogram to 10,000 kilograms (approx. 2.2 lbs to 22,000 lbs / 11 tons), without changing their physical size or body shape.', ARRAY['Feather-Light Floating: By dropping their weight down to 1 kg, the user becomes light enough to float through the air on wind currents (often using an umbrella for steering).','Crushing Body-Slam: By jumping above a target and instantly increasing their weight up to 10,000 kg, the user can crush opponents under massive gravitational force.','Instant Weight Reset: The user can freely toggle their weight mid-attack to maneuver quickly before landing a heavy hit.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019ffffc-745d-708f-a68b-25e67ba43213' AND updated_at <= '2026-08-14T11:33:41.473898Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019ffffc-745d-708f-a68b-25e67ba43213' AND updated_at <= '2026-08-14T11:33:41.473898Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019ffffc-745d-708f-a68b-25e67ba43213', 'es-ES', 'Su poder principal permite al usuario alterar drásticamente su peso a voluntad, entre 1 kilogramo y 10.000 kilogramos (aprox. entre 2,2 y 22.000 libras / 11 toneladas), sin cambiar su tamaño físico ni la forma de su cuerpo.', ARRAY['Flotación ligera como una pluma: Al reducir su peso hasta 1 kg, el usuario se vuelve lo bastante ligero como para flotar por el aire sobre corrientes de viento (a menudo usando un paraguas para dirigirse).','Aplastamiento corporal: Saltando por encima de un objetivo y aumentando instantáneamente su peso hasta 10.000 kg, el usuario puede aplastar a sus oponentes bajo una fuerza gravitatoria masiva.','Restablecimiento instantáneo de peso: El usuario puede alternar libremente su peso en pleno ataque para maniobrar con rapidez antes de asestar un golpe contundente.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019ffffc-745d-708f-a68b-25e67ba43213' AND updated_at <= '2026-08-14T11:33:41.473898Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019ffffc-745d-708f-a68b-25e67ba43213' AND updated_at <= '2026-08-14T11:33:41.473898Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019ffffc-745d-708f-a68b-25e67ba43213', 'ca-ES', 'El seu poder principal permet a l''usuari alterar dràsticament el seu pes a voluntat, entre 1 quilogram i 10.000 quilograms (aprox. entre 2,2 i 22.000 lliures / 11 tones), sense canviar la seva mida física ni la forma del seu cos.', ARRAY['Flotació lleugera com una ploma: En reduir el seu pes fins a 1 kg, l''usuari esdevé prou lleuger per flotar per l''aire sobre corrents de vent (sovint fent servir un paraigua per dirigir-se).','Aixafament corporal: Saltant per sobre d''un objectiu i augmentant instantàniament el seu pes fins a 10.000 kg, l''usuari pot aixafar els oponents sota una força gravitatòria massiva.','Restabliment instantani de pes: L''usuari pot alternar lliurement el seu pes en ple atac per maniobrar amb rapidesa abans d''assestar un cop contundent.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019ffffc-745d-708f-a68b-25e67ba43213' AND updated_at <= '2026-08-14T11:33:41.473898Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019ffffc-745d-708f-a68b-25e67ba43213' AND updated_at <= '2026-08-14T11:33:41.473898Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000ea-9d2f-7d1f-b685-62bd492ec342', 'en-GB', 'Allows the user to transform into a prehistoric, ancient mygalomorph spider (Rosamygale grauvogeli) or a spider hybrid at will, granting venomous attacks, sticky web manipulation, and ceiling locomotion.', ARRAY['Entrapment: Her webs are strong enough to bind powerful fighters like Sanji and Nico Robin, preventing physical movement and disabling escape routes.','Fire Traps: She can set her sticky webs ablaze using her flaming weapon (Wanyudo) or incendiary attacks to turn battlefields into infernos (Maria Net / Oiran Dori).','Venomous Stings & Poison Fangs: Her spider form features sharp, venomous fangs and leg tips that secrete neurotoxic venom, causing severe pain and organ damage to targets caught in her webs.','Centaur-Like Form: Her human torso emerges fully intact out of the spider''s head/cephalothorax. This allows her to maintain her beautiful human appearance while using all eight giant spider legs below for locomotion, trapping, and combat.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000ea-9d2f-7d1f-b685-62bd492ec342' AND updated_at <= '2026-08-14T15:36:11.6427Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000ea-9d2f-7d1f-b685-62bd492ec342' AND updated_at <= '2026-08-14T15:36:11.6427Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000ea-9d2f-7d1f-b685-62bd492ec342', 'es-ES', 'Permite al usuario transformarse a voluntad en una araña migalomorfa prehistórica y ancestral (Rosamygale grauvogeli) o en un híbrido de araña, otorgándole ataques venenosos, manipulación de telarañas pegajosas y locomoción por techos.', ARRAY['Atrapamiento: Sus telarañas son lo bastante fuertes como para inmovilizar a luchadores poderosos como Sanji y Nico Robin, impidiendo el movimiento físico y anulando las vías de escape.','Trampas de fuego: Puede prender fuego a sus telarañas pegajosas usando su arma llameante (Wanyudo) o ataques incendiarios para convertir los campos de batalla en infiernos (Maria Net / Oiran Dori).','Aguijones venenosos y colmillos ponzoñosos: Su forma de araña presenta colmillos afilados y venenosos, y puntas de patas que segregan veneno neurotóxico, causando dolor severo y daño a los órganos de quienes quedan atrapados en sus telarañas.','Forma similar a un centauro: Su torso humano emerge completamente intacto de la cabeza/cefalotórax de la araña. Esto le permite conservar su hermosa apariencia humana mientras utiliza las ocho patas gigantes de araña para desplazarse, atrapar y combatir.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000ea-9d2f-7d1f-b685-62bd492ec342' AND updated_at <= '2026-08-14T15:36:11.6427Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000ea-9d2f-7d1f-b685-62bd492ec342' AND updated_at <= '2026-08-14T15:36:11.6427Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000ea-9d2f-7d1f-b685-62bd492ec342', 'ca-ES', 'Permet a l''usuari transformar-se a voluntat en una aranya migalomorfa prehistòrica i ancestral (Rosamygale grauvogeli) o en un híbrid d''aranya, atorgant-li atacs verinosos, manipulació de teranyines enganxoses i locomoció per sostres.', ARRAY['Atrapament: Les seves teranyines són prou fortes per immobilitzar lluitadors poderosos com Sanji i Nico Robin, impedint el moviment físic i anul·lant les vies d''escapament.','Trampes de foc: Pot calar foc a les seves teranyines enganxoses fent servir la seva arma flamejant (Wanyudo) o atacs incendiaris per convertir els camps de batalla en inferns (Maria Net / Oiran Dori).','Fibló verinós i ullals metzinosos: La seva forma d''aranya presenta ullals afilats i verinosos, i puntes de potes que segreguen verí neurotòxic, causant dolor sever i dany als òrgans de qui queda atrapat en les seves teranyines.','Forma semblant a un centaure: El seu tors humà emergeix completament intacte del cap/cefalotòrax de l''aranya. Això li permet conservar la seva bella aparença humana mentre fa servir les vuit potes gegants d''aranya per desplaçar-se, atrapar i combatre.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000ea-9d2f-7d1f-b685-62bd492ec342' AND updated_at <= '2026-08-14T15:36:11.6427Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000ea-9d2f-7d1f-b685-62bd492ec342' AND updated_at <= '2026-08-14T15:36:11.6427Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a06c25-6762-7309-b240-8a28dc8f31b6', 'en-GB', 'User: Mohammed Avdol

Main power: Generates and manipulates extremely powerful fire that obeys Avdol''s will completely.

Appearance: A humanoid spirit with a bird''s head.

Reference: Represents the tarot card "The Magician"', ARRAY['Crossfire Hurricane','Crossfire Special (surround enemy)','Redirect fire trajectory','Red Bind (whip)']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a06c25-6762-7309-b240-8a28dc8f31b6' AND updated_at <= '2026-09-27T14:51:30.015904Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a06c25-6762-7309-b240-8a28dc8f31b6' AND updated_at <= '2026-09-27T14:51:30.015904Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a06c25-6762-7309-b240-8a28dc8f31b6', 'es-ES', 'Usuario: Mohammed Avdol 

Poder principal: Genera y manipula fuego muy potente que obedece por completo la voluntad de Avdol.

Apariencia: Es un espíritu humanoide con cabeza de ave.

Referencia: Representa la carta de tarot "El Mago"', ARRAY['Crossfire Hurricane','Crossfire Special (rodear enemigo)','Cambiar trayectoria fuego','Red Bind (látigo)']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a06c25-6762-7309-b240-8a28dc8f31b6' AND updated_at <= '2026-09-27T14:51:30.015904Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
