  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a06c25-6762-7309-b240-8a28dc8f31b6' AND updated_at <= '2026-09-27T14:51:30.015904Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a06c25-6762-7309-b240-8a28dc8f31b6', 'ca-ES', 'Usuari: Mohammed Avdol

Poder principal: Genera i manipula un foc molt potent que obeeix completament la voluntat d''Avdol.

Aparença: És un esperit humanoide amb cap d''au.

Referència: Representa la carta de tarot "El Mag"', ARRAY['Crossfire Hurricane','Crossfire Special (envoltar l''enemic)','Canviar la trajectòria del foc','Red Bind (fuet)']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a06c25-6762-7309-b240-8a28dc8f31b6' AND updated_at <= '2026-09-27T14:51:30.015904Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a06c25-6762-7309-b240-8a28dc8f31b6' AND updated_at <= '2026-09-27T14:51:30.015904Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0008a-9edf-79ce-9e59-d398ee24e0c7', 'en-GB', 'Allows the user to create, control, and transform their body into magma at will, boasting an offense officially stated to be among the highest tier in the entire world.', ARRAY['Lethal Melting Power: Unlike many attacks that knock opponents back, magma pierces straight through flesh and bone, causing fatal internal damage.','Volcanic Constructs: The user can shape magma into giant hound heads (Inugami Guren) or fire massive magma fists into the sky to drop down like meteor showers (Ryusei Kazan).','The Magu Magu no Mi is canonically a natural superior to the Mera Mera no Mi (Flame-Flame Fruit). Because magma burns significantly hotter and denser than fire, it can smother flames and inflict physical harm on a fire-type Logia user without needing Haki.','Terrain Alteration: Prolonged use of the fruit can permanently rewrite an island''s climate and geography.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0008a-9edf-79ce-9e59-d398ee24e0c7' AND updated_at <= '2026-08-14T13:57:13.771098Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0008a-9edf-79ce-9e59-d398ee24e0c7' AND updated_at <= '2026-08-14T13:57:13.771098Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0008a-9edf-79ce-9e59-d398ee24e0c7', 'es-ES', 'Permite al usuario crear, controlar y transformar su cuerpo en magma a voluntad, con un poder ofensivo declarado oficialmente entre los más altos de todo el mundo.', ARRAY['Poder de fusión letal: A diferencia de muchos ataques que hacen retroceder a los oponentes, el magma atraviesa directamente carne y hueso, causando daño interno mortal.','Construcciones volcánicas: El usuario puede moldear el magma en forma de cabezas de sabueso gigantes (Inugami Guren) o disparar puños gigantes de magma hacia el cielo para que caigan como una lluvia de meteoritos (Ryusei Kazan).','La Magu Magu no Mi es canónicamente superior por naturaleza a la Mera Mera no Mi (la Fruta Llama-Llama). Como el magma arde de forma significativamente más caliente y densa que el fuego, puede sofocar las llamas e infligir daño físico a un usuario Logia de tipo fuego sin necesidad de Haki.','Alteración del terreno: El uso prolongado de la fruta puede reescribir permanentemente el clima y la geografía de una isla.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0008a-9edf-79ce-9e59-d398ee24e0c7' AND updated_at <= '2026-08-14T13:57:13.771098Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0008a-9edf-79ce-9e59-d398ee24e0c7' AND updated_at <= '2026-08-14T13:57:13.771098Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0008a-9edf-79ce-9e59-d398ee24e0c7', 'ca-ES', 'Permet a l''usuari crear, controlar i transformar el seu cos en magma a voluntat, amb un poder ofensiu declarat oficialment entre els més alts de tot el món.', ARRAY['Poder de fusió letal: A diferència de molts atacs que fan recular els oponents, el magma travessa directament carn i os, causant dany intern mortal.','Construccions volcàniques: L''usuari pot modelar el magma en forma de caps de gos gegants (Inugami Guren) o disparar punys gegants de magma cap al cel perquè caiguin com una pluja de meteorits (Ryusei Kazan).','La Magu Magu no Mi és canònicament superior per naturalesa a la Mera Mera no Mi (la Fruita Flama-Flama). Com que el magma crema d''una manera significativament més calenta i densa que el foc, pot sufocar les flames i infligir dany físic a un usuari Logia de tipus foc sense necessitat de Haki.','Alteració del terreny: L''ús prolongat de la fruita pot reescriure permanentment el clima i la geografia d''una illa.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0008a-9edf-79ce-9e59-d398ee24e0c7' AND updated_at <= '2026-08-14T13:57:13.771098Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0008a-9edf-79ce-9e59-d398ee24e0c7' AND updated_at <= '2026-08-14T13:57:13.771098Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00009-2a3d-7c2a-a0a9-8c2324dae210', 'en-GB', 'Its main power allows the user to transform into a physical clone of anyone whose face they have touched with their right hand.', ARRAY['Exact Physical Replica: The transformation is an absolute match, copying the target''s face, body shape, height, age, voice, and even physical flaws (such as scars or bad eyesight).','Face Memory Storage: Once the user touches a person''s face with their right hand, that person''s physical appearance is permanently recorded in their memory. They can switch between saved physical forms instantly at any time.','Reversion: Touching their own face with their left hand instantly cancels the transformation, returning the user to their original appearance.','Infiltration & Espionage: It is one of the most effective stealth tools in the series, allowing the user to impersonate high-ranking officials, guards, or kings.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00009-2a3d-7c2a-a0a9-8c2324dae210' AND updated_at <= '2026-08-14T11:29:56.344282Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00009-2a3d-7c2a-a0a9-8c2324dae210' AND updated_at <= '2026-08-14T11:29:56.344282Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00009-2a3d-7c2a-a0a9-8c2324dae210', 'es-ES', 'Su poder principal permite al usuario transformarse en un clon físico de cualquier persona cuyo rostro haya tocado con su mano derecha.', ARRAY['Réplica física exacta: La transformación es una coincidencia absoluta, copiando el rostro, la forma corporal, la altura, la edad, la voz e incluso los defectos físicos (como cicatrices o mala vista) del objetivo.','Almacenamiento de rostros en la memoria: En cuanto el usuario toca el rostro de una persona con su mano derecha, la apariencia física de esa persona queda registrada permanentemente en su memoria. Puede cambiar entre las formas físicas guardadas de forma instantánea en cualquier momento.','Reversión: Tocarse el propio rostro con la mano izquierda cancela instantáneamente la transformación, devolviendo al usuario a su apariencia original.','Infiltración y espionaje: Es una de las herramientas de sigilo más eficaces de la serie, ya que permite al usuario hacerse pasar por funcionarios de alto rango, guardias o reyes.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00009-2a3d-7c2a-a0a9-8c2324dae210' AND updated_at <= '2026-08-14T11:29:56.344282Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00009-2a3d-7c2a-a0a9-8c2324dae210' AND updated_at <= '2026-08-14T11:29:56.344282Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00009-2a3d-7c2a-a0a9-8c2324dae210', 'ca-ES', 'El seu poder principal permet a l''usuari transformar-se en un clon físic de qualsevol persona el rostre de la qual hagi tocat amb la seva mà dreta.', ARRAY['Rèplica física exacta: La transformació és una coincidència absoluta, copiant el rostre, la forma corporal, l''alçada, l''edat, la veu i fins i tot els defectes físics (com cicatrius o mala vista) de l''objectiu.','Emmagatzematge de rostres a la memòria: Tan aviat com l''usuari toca el rostre d''una persona amb la seva mà dreta, l''aparença física d''aquesta persona queda enregistrada permanentment a la seva memòria. Pot canviar entre les formes físiques desades de manera instantània en qualsevol moment.','Reversió: Tocar-se el propi rostre amb la mà esquerra cancel·la instantàniament la transformació, retornant l''usuari a la seva aparença original.','Infiltració i espionatge: És una de les eines de sigil més eficaces de la sèrie, ja que permet a l''usuari fer-se passar per funcionaris d''alt rang, guardes o reis.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00009-2a3d-7c2a-a0a9-8c2324dae210' AND updated_at <= '2026-08-14T11:29:56.344282Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00009-2a3d-7c2a-a0a9-8c2324dae210' AND updated_at <= '2026-08-14T11:29:56.344282Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0007c-20d0-7d97-a6bc-2a8c6b237339', 'en-GB', 'Allows the user to create, control, and transform their entire body into fire at will.', ARRAY['Fire Cannons & Bullets: The user can shoot concentrated fireballs or rapid-fire flame pellets (Hiken / Higan).','Massive Collumns of Flame: The user can summon giant sun-like fireballs (Dai Enkai: Entei) or create walls of fire to trap enemies.','Mobility & Propulsion: By blasting fire from their feet or lower body, the user can fly through the air, move at rapid speeds, or propel vehicles (such as Ace''s Striker raft).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0007c-20d0-7d97-a6bc-2a8c6b237339' AND updated_at <= '2026-08-14T13:48:57.829713Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0007c-20d0-7d97-a6bc-2a8c6b237339' AND updated_at <= '2026-08-14T13:48:57.829713Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0007c-20d0-7d97-a6bc-2a8c6b237339', 'ca-ES', 'Permet a l''usuari crear, controlar i transformar tot el seu cos en foc a voluntat.', ARRAY['Canons i bales de foc: L''usuari pot disparar boles de foc concentrades o projectils de flama de foc ràpid (Hiken / Higan).','Columnes massives de flames: L''usuari pot invocar gegantines boles de foc semblants a un sol (Dai Enkai: Entei) o crear murs de foc per atrapar els seus enemics.','Mobilitat i propulsió: En expulsar foc des dels peus o la part inferior del cos, l''usuari pot volar per l''aire, moure''s a gran velocitat o propulsar vehicles (com la barca Striker d''Ace).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0007c-20d0-7d97-a6bc-2a8c6b237339' AND updated_at <= '2026-08-14T13:48:57.829713Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0007c-20d0-7d97-a6bc-2a8c6b237339' AND updated_at <= '2026-08-14T13:48:57.829713Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0007c-20d0-7d97-a6bc-2a8c6b237339', 'es-ES', 'Permite al usuario crear, controlar y transformar todo su cuerpo en fuego a voluntad.', ARRAY['Cañones y balas de fuego: El usuario puede disparar bolas de fuego concentradas o proyectiles de llama de fuego rápido (Hiken / Higan).','Columnas masivas de llamas: El usuario puede invocar gigantescas bolas de fuego similares a un sol (Dai Enkai: Entei) o crear muros de fuego para atrapar a sus enemigos.','Movilidad y propulsión: Al expulsar fuego desde los pies o la parte inferior del cuerpo, el usuario puede volar por el aire, moverse a gran velocidad o propulsar vehículos (como la balsa Striker de Ace).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0007c-20d0-7d97-a6bc-2a8c6b237339' AND updated_at <= '2026-08-14T13:48:57.829713Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0007c-20d0-7d97-a6bc-2a8c6b237339' AND updated_at <= '2026-08-14T13:48:57.829713Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00025-b5b2-7b16-93f5-a19607b33e22', 'ca-ES', 'El seu poder principal permet a l''usuari petrificar els seus objectius convertint-los en pedra sòlida, transformant en arma els sentiments d''atracció, desig o afecte que senten cap a l''usuari.', ARRAY['Raig de Petrificació (Mero Mero Mellow): L''usuari forma un cor amb les mans i dispara un raig amb forma de cor. Qualsevol que albergui el més mínim pensament d''atracció o desig cap a l''usuari queda a l''instant convertit en pedra sòlida.','Petrificació per Contacte Físic (Perfume Femur): L''usuari pot bombardejar els seus oponents amb puntades per petrificar el punt exacte de contacte en l''impacte, fent que les zones petrificades es facin miques com el vidre, sense importar si l''oponent sent atracció o no.','Projectils a Distància (Pistol Kiss i Slave Arrow): L''usuari pot llançar petons amb forma de cor com a projectils o construir un arc d''energia gegant per abocar una pluja de fletxes petrificants, convertint en pedra tant éssers vius com objectes inanimats (com els ciborgs Pacifista o les bales de canó).','Reversió Absoluta: Només l''usuari actual de la fruita pot revertir l''efecte de petrificació. Si l''usuari mor o la fruita passa a un nou propietari, les víctimes petrificades romanen convertides en pedra per sempre.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00025-b5b2-7b16-93f5-a19607b33e22' AND updated_at <= '2026-08-14T12:01:07.156425Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00025-b5b2-7b16-93f5-a19607b33e22' AND updated_at <= '2026-08-14T12:01:07.156425Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00025-b5b2-7b16-93f5-a19607b33e22', 'en-GB', 'Its main power allows the user to petrify targets into solid stone by weaponizing feelings of attraction, lust, or affection toward the user.', ARRAY['Petrification Beam (Mero Mero Mellow): The user forms a heart with their hands and fires a heart-shaped beam. Anyone who harbors even a slight thought of attraction or lust toward the user is instantly transformed into solid stone.','Physical Contact Petrification (Perfume Femur): The user can kick opponents to petrify the specific point of contact on impact, causing the petrified areas to shatter like glass regardless of whether the opponent feels attraction.','Ranged Projectiles (Pistol Kiss & Slave Arrow): The user can blow heart-shaped kiss projectiles or construct a giant energy bow to shower targets with petrifying arrows, turning both living beings and inanimate objects (like Pacifista cyborgs or cannonballs) into stone.','Absolute Reversal: Only the current user of the fruit can reverse the petrification effect. If the user dies or the fruit is passed to a new owner, the petrified victims remain stone forever.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00025-b5b2-7b16-93f5-a19607b33e22' AND updated_at <= '2026-08-14T12:01:07.156425Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00025-b5b2-7b16-93f5-a19607b33e22' AND updated_at <= '2026-08-14T12:01:07.156425Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00025-b5b2-7b16-93f5-a19607b33e22', 'es-ES', 'Su poder principal permite al usuario petrificar a sus objetivos convirtiéndolos en piedra sólida, transformando en arma los sentimientos de atracción, deseo o afecto que sienten hacia el usuario.', ARRAY['Rayo de Petrificación (Mero Mero Mellow): El usuario forma un corazón con las manos y dispara un rayo con forma de corazón. Cualquiera que albergue el más mínimo pensamiento de atracción o deseo hacia el usuario queda al instante convertido en piedra sólida.','Petrificación por Contacto Físico (Perfume Femur): El usuario puede patear a sus oponentes para petrificar el punto exacto de contacto en el impacto, haciendo que las zonas petrificadas se hagan añicos como el cristal, sin importar si el oponente siente atracción o no.','Proyectiles a Distancia (Pistol Kiss y Slave Arrow): El usuario puede lanzar besos con forma de corazón como proyectiles o construir un arco de energía gigante para lanzar una lluvia de flechas petrificantes, convirtiendo en piedra tanto a seres vivos como a objetos inanimados (como los cyborgs Pacifista o las balas de cañón).','Reversión Absoluta: Solo el usuario actual de la fruta puede revertir el efecto de petrificación. Si el usuario muere o la fruta pasa a un nuevo propietario, las víctimas petrificadas permanecen convertidas en piedra para siempre.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00025-b5b2-7b16-93f5-a19607b33e22' AND updated_at <= '2026-08-14T12:01:07.156425Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00025-b5b2-7b16-93f5-a19607b33e22' AND updated_at <= '2026-08-14T12:01:07.156425Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0002e-3c55-7e49-8735-e3f5f67e8093', 'en-GB', 'Its main power grants the user the ability to create, control, and transform their entire body into mochi (a sticky Japanese rice cake).', ARRAY['Logia-like Intangibility (Special Paramecia): Unlike standard Paramecia fruits, the Mochi Mochi no Mi allows the user''s body to behave like an elemental Logia. Physical strikes, slashes, and bullets pass directly through or absorb into the user''s mochi body without causing harm.','Adhesive Trapping: The mochi produced is extremely dense, soft, and sticky. Enemies or weapons that strike the user can become permanently stuck in the dough, immobilizing them completely.','Shapeshifting & Extension: The user can stretch, expand, or reshape their body parts into massive dough fists, tendrils, spiked weapons, or multi-limb constructs.','Compressed Density (Unstoppable Donut): By spinning and hardening the mochi with Busoshoku Haki, the user can deliver crushing bludgeoning force that rivals or surpasses rubber-based strikes.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0002e-3c55-7e49-8735-e3f5f67e8093' AND updated_at <= '2026-08-14T12:20:31.577997Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0002e-3c55-7e49-8735-e3f5f67e8093' AND updated_at <= '2026-08-14T12:20:31.577997Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0002e-3c55-7e49-8735-e3f5f67e8093', 'es-ES', 'Su poder principal concede al usuario la capacidad de crear, controlar y transformar todo su cuerpo en mochi (un pastel de arroz japonés pegajoso).', ARRAY['Intangibilidad tipo Logia (Paramecia Especial): A diferencia de las frutas Paramecia normales, la Mochi Mochi no Mi permite que el cuerpo del usuario se comporte como una Logia elemental. Los golpes físicos, cortes y balas atraviesan directamente el cuerpo de mochi del usuario o son absorbidos por él sin causarle daño.','Atrapamiento Adhesivo: El mochi que se produce es extremadamente denso, blando y pegajoso. Los enemigos o armas que golpean al usuario pueden quedar permanentemente atascados en la masa, inmovilizándolos por completo.','Cambio de Forma y Extensión: El usuario puede estirar, expandir o remodelar partes de su cuerpo en enormes puños de masa, tentáculos, armas con pinchos o construcciones de múltiples extremidades.','Densidad Comprimida (Unstoppable Donut): Al hacer girar y endurecer el mochi con el Busoshoku Haki, el usuario puede asestar una fuerza contundente aplastante que rivaliza o supera a los golpes de tipo goma.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0002e-3c55-7e49-8735-e3f5f67e8093' AND updated_at <= '2026-08-14T12:20:31.577997Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0002e-3c55-7e49-8735-e3f5f67e8093' AND updated_at <= '2026-08-14T12:20:31.577997Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0002e-3c55-7e49-8735-e3f5f67e8093', 'ca-ES', 'El seu poder principal concedeix a l''usuari la capacitat de crear, controlar i transformar tot el seu cos en mochi (un pastís d''arròs japonès enganxós).', ARRAY['Intangibilitat tipus Logia (Paramecia Especial): A diferència de les fruites Paramecia normals, la Mochi Mochi no Mi permet que el cos de l''usuari es comporti com una Logia elemental. Els cops físics, talls i bales travessen directament el cos de mochi de l''usuari o hi són absorbits sense causar-li mal.','Atrapament Adhesiu: El mochi que es produeix és extremadament dens, tou i enganxós. Els enemics o armes que colpegen l''usuari poden quedar permanentment enganxats a la massa, immobilitzant-los completament.','Canvi de Forma i Extensió: L''usuari pot estirar, expandir o remodelar parts del seu cos en enormes punys de massa, tentacles, armes amb pues o construccions de múltiples extremitats.','Densitat Comprimida (Unstoppable Donut): En fer girar i endurir el mochi amb el Busoshoku Haki, l''usuari pot assestar una força contundent aclaparadora que rivalitza o supera els cops de tipus goma.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0002e-3c55-7e49-8735-e3f5f67e8093' AND updated_at <= '2026-08-14T12:20:31.577997Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0002e-3c55-7e49-8735-e3f5f67e8093' AND updated_at <= '2026-08-14T12:20:31.577997Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000ee-5f9e-7ce2-a700-704ebc12edc9', 'es-ES', 'Permite al usuario transformarse en un topo o en un híbrido de topo, otorgándole el poder de excavar a través de tierra sólida, roca y suelo a una velocidad increíble.', ARRAY['Redes de Túneles Subterráneos: Puede crear enormes redes subterráneas para moverse completamente indetectado bajo los pies de los enemigos.','Emboscadas y Trampas: Permite al usuario arrastrar a los oponentes bajo tierra agarrándolos por los tobillos, llevándolos a trampas de fosos o dejándolos inmovilizados.','Garras de Excavación Letales: Tanto en forma completa de topo como en forma híbrida, las manos del usuario se convierten en garras densas y alargadas capaces de atravesar muros de piedra y asestar potentes ataques cortantes en el combate cuerpo a cuerpo (Mogu Mogu Claw).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000ee-5f9e-7ce2-a700-704ebc12edc9' AND updated_at <= '2026-08-14T15:40:17.847927Z'::timestamptz)
