  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000ee-5f9e-7ce2-a700-704ebc12edc9' AND updated_at <= '2026-08-14T15:40:17.847927Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000ee-5f9e-7ce2-a700-704ebc12edc9', 'ca-ES', 'Permet a l''usuari transformar-se en un talp o en un híbrid de talp, atorgant-li el poder de excavar a través de terra sòlida, roca i sòl a una velocitat increïble.', ARRAY['Xarxes de Túnels Subterranis: Pot crear enormes xarxes subterrànies per moure''s completament indetectat sota els peus dels enemics.','Emboscades i Trampes: Permet a l''usuari arrossegar els oponents sota terra agafant-los pels turmells, portant-los a trampes de fossos o deixant-los immobilitzats.','Urpes d''Excavació Letals: Tant en forma completa de talp com en forma híbrida, les mans de l''usuari es converteixen en urpes denses i allargades capaces de travessar murs de pedra i assestar potents atacs tallants en el combat cos a cos (Mogu Mogu Claw).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000ee-5f9e-7ce2-a700-704ebc12edc9' AND updated_at <= '2026-08-14T15:40:17.847927Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000ee-5f9e-7ce2-a700-704ebc12edc9' AND updated_at <= '2026-08-14T15:40:17.847927Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000ee-5f9e-7ce2-a700-704ebc12edc9', 'en-GB', 'Allows the user to transform into a mole or a mole hybrid, granting the power to burrow through solid ground, rock, and earth at incredible speeds.', ARRAY['Underground Tunnel Networks: Can create massive subterranean networks to move completely undetected beneath enemies'' feet.','Ambushes & Traps: Allows the user to pull opponents underground by their ankles, dragging them into pitfall traps or leaving them immobilized.','Lethal Digging Claws: In both full mole and hybrid forms, the user''s hands turn into dense, elongated claws capable of tearing through stone walls and delivering heavy slashing attacks in close-quarters combat (Mogu Mogu Claw).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000ee-5f9e-7ce2-a700-704ebc12edc9' AND updated_at <= '2026-08-14T15:40:17.847927Z'::timestamptz)
