INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00078-52f4-7267-8690-8e4ee285a4ac', 'en-GB', 'Allows the user to create, control, and transform their entire body into smoke at will.', ARRAY['Capture and Trapping: The user can alter the density and thickness of his smoke to grab, bind, or suffocate multiple enemies simultaneously.','Flight and Propulsion: The user can convert their lower body into smoke to levitate, fly, or propel themselves at high speeds across land and sky.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00078-52f4-7267-8690-8e4ee285a4ac' AND updated_at <= '2026-08-14T13:31:21.424495Z'::timestamptz)
