  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00078-52f4-7267-8690-8e4ee285a4ac' AND updated_at <= '2026-08-14T13:31:21.424495Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00078-52f4-7267-8690-8e4ee285a4ac', 'ca-ES', 'Permet a l''usuari crear, controlar i transformar tot el seu cos en fum a voluntat.', ARRAY['Captura i Atrapament: L''usuari pot alterar la densitat i el gruix del seu fum per agafar, lligar o asfixiar diversos enemics simultàniament.','Vol i Propulsió: L''usuari pot convertir la part inferior del seu cos en fum per levitar, volar o impulsar-se a gran velocitat tant per terra com pel cel.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00078-52f4-7267-8690-8e4ee285a4ac' AND updated_at <= '2026-08-14T13:31:21.424495Z'::timestamptz)
