  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00078-52f4-7267-8690-8e4ee285a4ac' AND updated_at <= '2026-08-14T13:31:21.424495Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00078-52f4-7267-8690-8e4ee285a4ac', 'es-ES', 'Permite al usuario crear, controlar y transformar todo su cuerpo en humo a voluntad.', ARRAY['Captura y Atrapamiento: El usuario puede alterar la densidad y el espesor de su humo para agarrar, atar o asfixiar a varios enemigos simultáneamente.','Vuelo y Propulsión: El usuario puede convertir la parte inferior de su cuerpo en humo para levitar, volar o impulsarse a gran velocidad tanto por tierra como por el cielo.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00078-52f4-7267-8690-8e4ee285a4ac' AND updated_at <= '2026-08-14T13:31:21.424495Z'::timestamptz)
