  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00078-52f4-7267-8690-8e4ee285a4ac' AND updated_at <= '2026-08-14T13:31:21.424495Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00098-7ed4-7271-a842-a418f84f29be', 'en-GB', 'Allows the user to create, control, and transform their body into plant life and forest vegetation at will, acting as the literal source of life itself.', ARRAY['Organic Intangibility & Regrowth: As a Logia user, non-Haki physical attacks pass through Ryokugyu''s plant body. Even if his wooden shell or treant forms are burned down or completely shattered, he can instantly sprout a new body out of a small sapling or seed grown from the ground.','Nutrient Absorption & Dehydration: The user can extend sharp roots and vines from his fingers and limbs to pierce targets. Upon contact, these roots act as liquid pumps that drain all fluids, nutrients, and stamina directly out of opponents—leaving them utterly emaciated while restoring the user''s energy','Instant Reforestation: Wherever Ryokugyu walks, lush grass, flowers, giant roots, and trees spontaneously bloom behind him, turning barren topographies or ruined battlefields into dense forests.','Giant Treant Transformation: He can merge with vegetation to transform into a massive, multi-story treant wood monster (Kyōrai Zō).','Flight: By growing a rapidly spinning flower out of his back, Ryokugyu can use it like a helicopter propeller to fly across vast oceans.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00098-7ed4-7271-a842-a418f84f29be' AND updated_at <= '2026-08-14T14:06:29.709935Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00098-7ed4-7271-a842-a418f84f29be' AND updated_at <= '2026-08-14T14:06:29.709935Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00098-7ed4-7271-a842-a418f84f29be', 'es-ES', 'Permite al usuario crear, controlar y transformar su cuerpo en vegetación vegetal y forestal a voluntad, actuando como la fuente literal de la vida misma.', ARRAY['Intangibilidad Orgánica y Regeneración: Como usuario de una Logia, los ataques físicos no reforzados con Haki atraviesan el cuerpo vegetal de Ryokugyu. Incluso si su caparazón de madera o sus formas de árbol-monstruo son quemados o completamente destrozados, puede hacer brotar al instante un nuevo cuerpo a partir de un pequeño brote o semilla nacida del suelo.','Absorción de Nutrientes y Deshidratación: El usuario puede extender raíces y enredaderas afiladas desde sus dedos y extremidades para atravesar a sus objetivos. Al hacer contacto, estas raíces actúan como bombas líquidas que extraen todos los fluidos, nutrientes y energía directamente de los oponentes, dejándolos completamente demacrados mientras restauran la energía del usuario.','Reforestación Instantánea: Allá por donde camina Ryokugyu, brotan espontáneamente a su paso hierba exuberante, flores, raíces gigantes y árboles, convirtiendo terrenos áridos o campos de batalla arrasados en densos bosques.','Transformación en Árbol-Monstruo Gigante: Puede fusionarse con la vegetación para transformarse en un monstruo de madera gigantesco, de varios pisos de altura, similar a un ent (Kyōrai Zō).','Vuelo: Al hacer crecer una flor que gira rápidamente en su espalda, Ryokugyu puede usarla como la hélice de un helicóptero para volar a través de vastos océanos.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00098-7ed4-7271-a842-a418f84f29be' AND updated_at <= '2026-08-14T14:06:29.709935Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00098-7ed4-7271-a842-a418f84f29be' AND updated_at <= '2026-08-14T14:06:29.709935Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00098-7ed4-7271-a842-a418f84f29be', 'ca-ES', 'Permet a l''usuari crear, controlar i transformar el seu cos en vegetació vegetal i forestal a voluntat, actuant com la font literal de la vida mateixa.', ARRAY['Intangibilitat Orgànica i Regeneració: Com a usuari d''una Logia, els atacs físics no reforçats amb Haki travessen el cos vegetal de Ryokugyu. Fins i tot si la seva closca de fusta o les seves formes d''arbre-monstre són cremades o completament destrossades, pot fer brotar a l''instant un nou cos a partir d''un petit brot o llavor nascuda del terra.','Absorció de Nutrients i Deshidratació: L''usuari pot estendre arrels i enfiladisses esmolades des dels seus dits i extremitats per travessar els seus objectius. En fer contacte, aquestes arrels actuen com a bombes líquides que extreuen tots els fluids, nutrients i energia directament dels oponents, deixant-los completament demacrats mentre restauren l''energia de l''usuari.','Reforestació Instantània: Allà on camina Ryokugyu, broten espontàniament al seu pas herba exuberant, flors, arrels gegants i arbres, convertint terrenys àrids o camps de batalla arrasats en boscos densos.','Transformació en Arbre-Monstre Gegant: Pot fusionar-se amb la vegetació per transformar-se en un monstre de fusta gegantí, de diversos pisos d''alçada, similar a un ent (Kyōrai Zō).','Vol: En fer créixer una flor que gira ràpidament a la seva esquena, Ryokugyu pot usar-la com l''hèlix d''un helicòpter per volar a través de vastos oceans.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00098-7ed4-7271-a842-a418f84f29be' AND updated_at <= '2026-08-14T14:06:29.709935Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00098-7ed4-7271-a842-a418f84f29be' AND updated_at <= '2026-08-14T14:06:29.709935Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000d3-e078-7221-ab12-36040aa7934e', 'en-GB', 'Allows the user to transform into a rhinoceros beetle hybrid or a full rhinoceros beetle at will, granting flight, armored exoskeleton plating, and immense horn-based thrusting power.', ARRAY['Devastating Headbutts: The user can utilize his massive beetle horn (Kabuto Head) to charge targets, flipping, tossing, or crashing through heavy opponents and fortified defenses with ease.','Proportional Strength Boost: Enhances the user''s base lifting and pushing power far beyond normal Zoan standards relative to size.','Armored Exoskeleton Defense: The transformation equips the user with a dark, hardened chitin shell. This insect carapace acts as natural body armor, effortlessly deflecting basic sword slashes, gunfire, and blunt physical impacts.','Flight & Aerial Maneuverability: Behind the hard wing covers (elytra), the fruit provides functional membranous wings that allow high-speed flight, enabling rapid aerial tackles and sudden diving charges.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000d3-e078-7221-ab12-36040aa7934e' AND updated_at <= '2026-08-14T15:11:21.589116Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000d3-e078-7221-ab12-36040aa7934e' AND updated_at <= '2026-08-14T15:11:21.589116Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000d3-e078-7221-ab12-36040aa7934e', 'es-ES', 'Permite al usuario transformarse a voluntad en un híbrido de escarabajo rinoceronte o en un escarabajo rinoceronte completo, otorgándole vuelo, un caparazón exoesquelético acorazado y una inmensa fuerza de empuje basada en su cuerno.', ARRAY['Cabezazos Devastadores: El usuario puede utilizar su enorme cuerno de escarabajo (Kabuto Head) para embestir a sus objetivos, volteando, lanzando o arrasando con oponentes pesados y defensas fortificadas con facilidad.','Aumento de Fuerza Proporcional: Potencia la capacidad base de levantar peso y empujar del usuario mucho más allá de los estándares habituales de un Zoan en relación con su tamaño.','Defensa de Exoesqueleto Acorazado: La transformación equipa al usuario con un caparazón de quitina oscuro y endurecido. Este caparazón de insecto actúa como una armadura corporal natural, desviando sin esfuerzo cortes básicos de espada, disparos de arma de fuego e impactos físicos contundentes.','Vuelo y Maniobrabilidad Aérea: Tras las duras cubiertas de las alas (élitros), la fruta proporciona alas membranosas funcionales que permiten un vuelo a gran velocidad, posibilitando embestidas aéreas rápidas y súbitas cargas en picado.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000d3-e078-7221-ab12-36040aa7934e' AND updated_at <= '2026-08-14T15:11:21.589116Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000d3-e078-7221-ab12-36040aa7934e' AND updated_at <= '2026-08-14T15:11:21.589116Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000d3-e078-7221-ab12-36040aa7934e', 'ca-ES', 'Permet a l''usuari transformar-se a voluntat en un híbrid d''escarabat rinoceront o en un escarabat rinoceront complet, atorgant-li vol, una closca exoesquelètica blindada i una immensa força d''embestida basada en la seva banya.', ARRAY['Cops de Cap Devastadors: L''usuari pot utilitzar la seva enorme banya d''escarabat (Kabuto Head) per envestir els seus objectius, capgirant, llançant o arrasant oponents pesants i defenses fortificades amb facilitat.','Augment de Força Proporcional: Potencia la capacitat base d''aixecar pes i empènyer de l''usuari molt més enllà dels estàndards habituals d''un Zoan en relació amb la seva mida.','Defensa d''Exosquelet Blindat: La transformació equipa l''usuari amb una closca de quitina fosca i endurida. Aquesta closca d''insecte actua com una armadura corporal natural, desviant sense esforç talls bàsics d''espasa, trets d''arma de foc i impactes físics contundents.','Vol i Maniobrabilitat Aèria: Rere les dures cobertes de les ales (èlitres), la fruita proporciona ales membranoses funcionals que permeten un vol a gran velocitat, possibilitant envestides aèries ràpides i sobtades càrregues en picat.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000d3-e078-7221-ab12-36040aa7934e' AND updated_at <= '2026-08-14T15:11:21.589116Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000d3-e078-7221-ab12-36040aa7934e' AND updated_at <= '2026-08-14T15:11:21.589116Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000d1-37a5-75fd-93ef-86dfaf4ca7cb', 'es-ES', 'Permite al usuario transformarse a voluntad en un híbrido de avispón o en un avispón gigante completo, otorgándole vuelo a gran velocidad, un aguijón venenoso y rasgos insectoides.', ARRAY['Vuelo a Gran Velocidad y Maniobrabilidad Aérea: La fruta otorga cuatro alas membranosas de insecto, permitiendo patrones de vuelo extremadamente rápidos, bruscos y erráticos. Esto hace que resulte difícil apuntar o seguir al usuario en pleno combate.','Daño Perforante: Capaz de asestar rápidos ataques de puñalada en el combate cuerpo a cuerpo.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000d1-37a5-75fd-93ef-86dfaf4ca7cb' AND updated_at <= '2026-08-14T15:08:27.189412Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000d1-37a5-75fd-93ef-86dfaf4ca7cb' AND updated_at <= '2026-08-14T15:08:27.189412Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000d1-37a5-75fd-93ef-86dfaf4ca7cb', 'ca-ES', 'Permet a l''usuari transformar-se a voluntat en un híbrid de vespa o en una vespa gegant completa, atorgant-li vol a gran velocitat, un fibló verinós i trets insectoides.', ARRAY['Vol a Gran Velocitat i Maniobrabilitat Aèria: La fruita atorga quatre ales membranoses d''insecte, permetent patrons de vol extremadament ràpids, bruscos i erràtics. Això fa que sigui difícil apuntar o seguir l''usuari en ple combat.','Dany Perforant: Capaç d''assestar ràpids atacs de punyalada en el combat cos a cos.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000d1-37a5-75fd-93ef-86dfaf4ca7cb' AND updated_at <= '2026-08-14T15:08:27.189412Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000d1-37a5-75fd-93ef-86dfaf4ca7cb' AND updated_at <= '2026-08-14T15:08:27.189412Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000d1-37a5-75fd-93ef-86dfaf4ca7cb', 'en-GB', 'Allows the user to transform into a hornet hybrid or a full giant hornet at will, granting high-speed flight, a venomous stinger, and insectoid traits.', ARRAY['High-Speed Flight & Aerial Maneuverability: The fruit grants four membranous insect wings, enabling extremely fast, sharp, and erratic flight patterns. This makes the user difficult to target or track mid-combat.','Piercing Damage: Capable of delivering rapid stabbing attacks in close-quarters combat.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000d1-37a5-75fd-93ef-86dfaf4ca7cb' AND updated_at <= '2026-08-14T15:08:27.189412Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000d1-37a5-75fd-93ef-86dfaf4ca7cb' AND updated_at <= '2026-08-14T15:08:27.189412Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0005f-f013-763e-88f9-e3debef24cd1', 'en-GB', 'Its main power grants the user the ability to transform into a full leopard or a human-leopard hybrid, dramatically boosting physical combat stats, agility, reflexes, and predatory instincts.', ARRAY['Beast Form (Full Leopard): Turns the user into a massive four-legged leopard, maximizing sprint speed, flexibility, and stealth tracking.','Hybrid Form (Human-Beast): Combines human build with leopard traits, creating a tall, heavily muscled bipedal predator with claws, fangs, spotted fur, and a tail.','Carnivorous Zoan Edge: As noted by Chopper, carnivorous Zoan fruits are inherently more fierce and predatory in battle compared to herbivorous ones, granting aggressive instincts and sharp physical tools (claws, biting power) tailored specifically for close-quarters killing.','Life Return Compression (Seimei Kikan): Using martial arts techniques, Lucci can manipulate his body structure in hybrid form to create a smaller, leaner form (Kami-e Bushin) that sacrifices raw muscular power for extreme, high-speed movement.','Awakened Vastly Boosted Stats: Grants immense boosts to physical strength, movement speed, reaction time, and exceptionally fast recovery/regeneration rates from physical damage.','Finger Pistol (Shigan): Sharp leopard claws transform standard piercing strikes into lethal, razor-like gouges.','Tempest Kick (Rankyaku): Enhanced leg strength generates slicing air blades capable of cutting through solid iron and stone ships.','Rokuogan: Combined with the massive physical muscle of the hybrid or awakened form, the ultimate shockwave attack delivers destructive point-blank internal organ damage.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0005f-f013-763e-88f9-e3debef24cd1' AND updated_at <= '2026-08-14T13:05:30.7606Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0005f-f013-763e-88f9-e3debef24cd1' AND updated_at <= '2026-08-14T13:05:30.7606Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0005f-f013-763e-88f9-e3debef24cd1', 'es-ES', 'Su poder principal concede al usuario la capacidad de transformarse en un leopardo completo o en un híbrido humano-leopardo, potenciando drásticamente sus estadísticas de combate físico, agilidad, reflejos e instintos depredadores.', ARRAY['Forma Bestia (Leopardo Completo): Convierte al usuario en un enorme leopardo cuadrúpedo, maximizando su velocidad de esprint, flexibilidad y capacidad de rastreo sigiloso.','Forma Híbrida (Humano-Bestia): Combina la constitución humana con rasgos de leopardo, creando un depredador bípedo alto y muy musculoso, con garras, colmillos, pelaje moteado y cola.','Ventaja de los Zoan Carnívoros: Como señala Chopper, las frutas Zoan carnívoras son inherentemente más feroces y depredadoras en batalla comparadas con las herbívoras, otorgando instintos agresivos y herramientas físicas afiladas (garras, poder de mordisco) diseñadas específicamente para matar en combate cuerpo a cuerpo.','Compresión de Retorno Vital (Seimei Kikan): Usando técnicas de artes marciales, Lucci puede manipular la estructura de su cuerpo en forma híbrida para crear una forma más pequeña y esbelta (Kami-e Bushin) que sacrifica potencia muscular en bruto a cambio de un movimiento extremo y a gran velocidad.','Estadísticas Enormemente Potenciadas por el Despertar: Otorga inmensas mejoras en la fuerza física, la velocidad de movimiento, el tiempo de reacción y una recuperación/regeneración excepcionalmente rápida del daño físico.','Pistola de Dedo (Shigan): Las afiladas garras de leopardo transforman los golpes perforantes habituales en cortes letales y afilados como cuchillas.','Patada Tempestad (Rankyaku): La fuerza incrementada de las piernas genera cuchillas de aire cortantes capaces de atravesar barcos de hierro y piedra sólidos.','Rokuogan: Combinado con la enorme musculatura física de la forma híbrida o despertada, este ataque de onda de choque definitivo inflige destructivo daño interno a quemarropa.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0005f-f013-763e-88f9-e3debef24cd1' AND updated_at <= '2026-08-14T13:05:30.7606Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0005f-f013-763e-88f9-e3debef24cd1' AND updated_at <= '2026-08-14T13:05:30.7606Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0005f-f013-763e-88f9-e3debef24cd1', 'ca-ES', 'El seu poder principal concedeix a l''usuari la capacitat de transformar-se en un lleopard complet o en un híbrid humà-lleopard, potenciant dràsticament les seves estadístiques de combat físic, agilitat, reflexos i instints depredadors.', ARRAY['Forma Bèstia (Lleopard Complet): Converteix l''usuari en un enorme lleopard quadrúpede, maximitzant la seva velocitat d''esprint, flexibilitat i capacitat de rastreig sigil·lós.','Forma Híbrida (Humà-Bèstia): Combina la constitució humana amb trets de lleopard, creant un depredador bípede alt i molt musculós, amb urpes, ullals, pelatge tacat i cua.','Avantatge dels Zoan Carnívors: Com assenyala Chopper, les fruites Zoan carnívores són inherentment més ferotges i depredadores en batalla comparades amb les herbívores, atorgant instints agressius i eines físiques esmolades (urpes, poder de mossegada) dissenyades específicament per matar en combat cos a cos.','Compressió de Retorn Vital (Seimei Kikan): Fent servir tècniques d''arts marcials, Lucci pot manipular l''estructura del seu cos en forma híbrida per crear una forma més petita i esvelta (Kami-e Bushin) que sacrifica potència muscular bruta a canvi d''un moviment extrem i a gran velocitat.','Estadístiques Enormement Potenciades pel Despertar: Atorga immenses millores en la força física, la velocitat de moviment, el temps de reacció i una recuperació/regeneració excepcionalment ràpida del mal físic.','Pistola de Dit (Shigan): Les esmolades urpes de lleopard transformen els cops perforants habituals en talls letals i afilats com fulles.','Puntada de Tempesta (Rankyaku): La força incrementada de les cames genera fulles d''aire tallants capaces de travessar vaixells de ferro i pedra sòlids.','Rokuogan: Combinat amb l''enorme musculatura física de la forma híbrida o despertada, aquest atac d''ona de xoc definitiu infligeix destructiu mal intern a boca de canó.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0005f-f013-763e-88f9-e3debef24cd1' AND updated_at <= '2026-08-14T13:05:30.7606Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0005f-f013-763e-88f9-e3debef24cd1' AND updated_at <= '2026-08-14T13:05:30.7606Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000b4-e437-733a-8bc5-2ff32cfe1b0e', 'en-GB', 'Allows the user to transform into a saber-toothed tiger hybrid or a full prehistoric saber-toothed tiger, granting immense ancient physical strength and predatory lethality.', ARRAY['Enormous Size & Reach: In full beast and hybrid forms, the user grows to a colossal size with massive paws, thick hide, and devastating bite force.','Giant Saber Fangs: Long, sword-like canine teeth capable of easily piercing steel armor, dragon scales, and dense bone.','Fang Shigan (Tooth Finger Gun): Utilizes his giant saber fangs or claws to fire piercing shockwaves (Gara Sugi / Fang Flash) at range.','Enhanced Tobobu (Flying Fang): Fires blade-like air slashes directly from his jaws using his heavy neck muscles and long fangs.','Tekkai & Rankyaku: His dense Ancient Zoan hide turns Tekkai into an almost impenetrable defense, while his long feline legs amplify the cutting arc of Rankyaku slashes.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000b4-e437-733a-8bc5-2ff32cfe1b0e' AND updated_at <= '2026-08-14T14:37:30.917685Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000b4-e437-733a-8bc5-2ff32cfe1b0e' AND updated_at <= '2026-08-14T14:37:30.917685Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000b4-e437-733a-8bc5-2ff32cfe1b0e', 'es-ES', 'Permite al usuario transformarse en un híbrido de tigre dientes de sable o en un tigre dientes de sable prehistórico completo, otorgándole una inmensa fuerza física ancestral y una letalidad depredadora.', ARRAY['Tamaño y Alcance Enormes: En sus formas de bestia completa e híbrida, el usuario crece hasta un tamaño colosal, con enormes zarpas, un pellejo grueso y una mordida devastadora.','Colmillos de Sable Gigantes: Largos caninos en forma de espada capaces de atravesar con facilidad armaduras de acero, escamas de dragón y hueso denso.','Shigan de Colmillo (Cañón de Dedo Diente): Utiliza sus colmillos de sable gigantes o sus garras para disparar ondas de choque perforantes (Gara Sugi / Fang Flash) a distancia.','Tobobu Mejorado (Colmillo Volador): Dispara cortes de aire con forma de cuchilla directamente desde sus fauces, usando sus poderosos músculos del cuello y sus largos colmillos.','Tekkai y Rankyaku: Su denso pellejo de Zoan Antiguo convierte el Tekkai en una defensa casi impenetrable, mientras que sus largas patas felinas amplifican el arco cortante de los ataques Rankyaku.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000b4-e437-733a-8bc5-2ff32cfe1b0e' AND updated_at <= '2026-08-14T14:37:30.917685Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000b4-e437-733a-8bc5-2ff32cfe1b0e' AND updated_at <= '2026-08-14T14:37:30.917685Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000b4-e437-733a-8bc5-2ff32cfe1b0e', 'ca-ES', 'Permet a l''usuari transformar-se en un híbrid de tigre dents de sabre o en un tigre dents de sabre prehistòric complet, atorgant-li una immensa força física ancestral i una letalitat depredadora.', ARRAY['Mida i Abast Enormes: En les seves formes de bèstia completa i híbrida, l''usuari creix fins a una mida colossal, amb enormes potes, una pell gruixuda i una mossegada devastadora.','Ullals de Sabre Gegants: Llargs canins en forma d''espasa capaços de travessar amb facilitat armadures d''acer, escates de drac i os dens.','Shigan d''Ullal (Canó de Dit Dent): Utilitza els seus ullals de sabre gegants o les seves urpes per disparar ones de xoc perforants (Gara Sugi / Fang Flash) a distància.','Tobobu Millorat (Ullal Volador): Dispara talls d''aire amb forma de fulla directament des de les seves fauces, fent servir els seus poderosos músculs del coll i els seus llargs ullals.','Tekkai i Rankyaku: La seva densa pell de Zoan Antic converteix el Tekkai en una defensa gairebé impenetrable, mentre que les seves llargues potes felines amplifiquen l''arc tallant dels atacs Rankyaku.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000b4-e437-733a-8bc5-2ff32cfe1b0e' AND updated_at <= '2026-08-14T14:37:30.917685Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000b4-e437-733a-8bc5-2ff32cfe1b0e' AND updated_at <= '2026-08-14T14:37:30.917685Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0001d-c679-729c-9b26-d5f2033f7e14', 'en-GB', 'Its main power gives the user permanent bear-like paw pads on the palms of their hands, which grant the absolute ability to repel anything they touch at extremely high speeds.', ARRAY['Absolute Deflection: The user can instantly deflect physical attacks, melee strikes, weapon slashes, elemental projectiles, laser beams, and even intangible concepts like air pressure.','Ultra-Fast Travel / Deflection Sending: By repelling a target (or themselves) into the air at near-light speeds, the user can instantly launch people across vast ocean distances to specific destinations. The flight takes exactly three days and three nights, surrounded by a protective paw-shaped bubble.','Compressed Air Shockwaves (Pad Ho & Ursus Shock): The user can repel air itself to fire high-velocity, armor-piercing pressure shockwaves. By compressing massive volumes of air into a small paw-shaped bubble and releasing it, they create a colossal point-blank shockwave explosion (Ursus Shock).','Pain & Fatigue Extraction: The user can physically push all accumulated pain, fatigue, and damage out of a person''s body, materializing it into a red, paw-shaped bubble. Transferred pain can be inflicted onto someone else or absorbed by another individual.','Memories & Emotions: The user can physically repel and separate their own memories or thoughts out of their brain, storing them in a tangible, floating bubble.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0001d-c679-729c-9b26-d5f2033f7e14' AND updated_at <= '2026-08-14T11:52:55.581695Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0001d-c679-729c-9b26-d5f2033f7e14' AND updated_at <= '2026-08-14T11:52:55.581695Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0001d-c679-729c-9b26-d5f2033f7e14', 'es-ES', 'Su poder principal otorga al usuario almohadillas permanentes similares a las de un oso en las palmas de las manos, que conceden la capacidad absoluta de repeler todo lo que tocan a velocidades extremadamente altas.', ARRAY['Desviación Absoluta: El usuario puede desviar al instante ataques físicos, golpes cuerpo a cuerpo, tajos de armas, proyectiles elementales, rayos láser e incluso conceptos intangibles como la presión del aire.','Viaje Ultrarrápido / Envío por Desviación: Repeliendo a un objetivo (o a sí mismo) hacia el aire a velocidades cercanas a la de la luz, el usuario puede lanzar al instante a las personas a través de vastas distancias oceánicas hasta destinos específicos. El vuelo dura exactamente tres días y tres noches, envuelto en una burbuja protectora con forma de zarpa.','Ondas de Choque de Aire Comprimido (Pad Ho y Ursus Shock): El usuario puede repeler el propio aire para disparar ondas de choque de presión de alta velocidad capaces de perforar armaduras. Comprimiendo enormes volúmenes de aire en una pequeña burbuja con forma de zarpa y liberándolo después, crea una colosal explosión de onda de choque a quemarropa (Ursus Shock).','Extracción de Dolor y Fatiga: El usuario puede empujar físicamente todo el dolor, la fatiga y el daño acumulados fuera del cuerpo de una persona, materializándolos en una burbuja roja con forma de zarpa. El dolor transferido puede infligirse a otra persona o ser absorbido por otro individuo.','Recuerdos y Emociones: El usuario puede repeler y separar físicamente sus propios recuerdos o pensamientos de su cerebro, almacenándolos en una burbuja tangible y flotante.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0001d-c679-729c-9b26-d5f2033f7e14' AND updated_at <= '2026-08-14T11:52:55.581695Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0001d-c679-729c-9b26-d5f2033f7e14' AND updated_at <= '2026-08-14T11:52:55.581695Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0001d-c679-729c-9b26-d5f2033f7e14', 'ca-ES', 'El seu poder principal atorga a l''usuari coixinets permanents similars als d''un ós als palmells de les mans, que concedeixen la capacitat absoluta de repel·lir tot allò que toquen a velocitats extremadament altes.', ARRAY['Desviació Absoluta: L''usuari pot desviar a l''instant atacs físics, cops cos a cos, talls d''armes, projectils elementals, raigs làser i fins i tot conceptes intangibles com la pressió de l''aire.','Viatge Ultraràpid / Enviament per Desviació: Repel·lint un objectiu (o a si mateix) cap a l''aire a velocitats properes a la de la llum, l''usuari pot llançar a l''instant persones a través de vastes distàncies oceàniques fins a destinacions específiques. El vol dura exactament tres dies i tres nits, envoltat d''una bombolla protectora amb forma de zarpa.','Ones de Xoc d''Aire Comprimit (Pad Ho i Ursus Shock): L''usuari pot repel·lir el mateix aire per disparar ones de xoc de pressió d''alta velocitat capaces de perforar armadures. En comprimir enormes volums d''aire en una petita bombolla amb forma de zarpa i alliberar-lo després, crea una colossal explosió d''ona de xoc a boca de canó (Ursus Shock).','Extracció de Dolor i Fatiga: L''usuari pot empènyer físicament tot el dolor, la fatiga i el mal acumulats fora del cos d''una persona, materialitzant-los en una bombolla vermella amb forma de zarpa. El dolor transferit pot infligir-se a una altra persona o ser absorbit per un altre individu.','Records i Emocions: L''usuari pot repel·lir i separar físicament els seus propis records o pensaments del seu cervell, emmagatzemant-los en una bombolla tangible i flotant.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0001d-c679-729c-9b26-d5f2033f7e14' AND updated_at <= '2026-08-14T11:52:55.581695Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0001d-c679-729c-9b26-d5f2033f7e14' AND updated_at <= '2026-08-14T11:52:55.581695Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0002a-6f01-70a2-abff-cf41c63e7f00', 'en-GB', 'Its main power allows the user to stitch anything and everything together using a needle and invisible, unbreakable thread that the fruit generates.', ARRAY['Matter Stitching: The user can seamlessly stitch living beings, objects, or surfaces together. They can pin opponents down by stitching their clothes or bodies to solid ground, walls, or even to other people.','Painless Piercing: The needle and thread penetrate living tissue instantly without causing physical pain or drawing blood, allowing the user to immobilize enemies before they even realize they''ve been captured.','Unstitching (Release): The user can undo their stitches at any time, instantly freeing whatever was bound together without leaving permanent scars or damage behind.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0002a-6f01-70a2-abff-cf41c63e7f00' AND updated_at <= '2026-08-14T12:06:16.687596Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0002a-6f01-70a2-abff-cf41c63e7f00' AND updated_at <= '2026-08-14T12:06:16.687596Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0002a-6f01-70a2-abff-cf41c63e7f00', 'es-ES', 'Su poder principal permite al usuario coser cualquier cosa entre sí usando una aguja y un hilo invisible e irrompible que la fruta genera.', ARRAY['Costura de Materia: El usuario puede coser sin costuras seres vivos, objetos o superficies entre sí. Puede inmovilizar a sus oponentes cosiendo su ropa o sus cuerpos al suelo sólido, a paredes o incluso a otras personas.','Perforación Indolora: La aguja y el hilo penetran el tejido vivo al instante sin causar dolor físico ni derramar sangre, permitiendo al usuario inmovilizar a los enemigos antes de que siquiera se den cuenta de que han sido capturados.','Descosido (Liberación): El usuario puede deshacer sus puntadas en cualquier momento, liberando al instante todo aquello que estuviera unido sin dejar cicatrices ni daños permanentes.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0002a-6f01-70a2-abff-cf41c63e7f00' AND updated_at <= '2026-08-14T12:06:16.687596Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0002a-6f01-70a2-abff-cf41c63e7f00' AND updated_at <= '2026-08-14T12:06:16.687596Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0002a-6f01-70a2-abff-cf41c63e7f00', 'ca-ES', 'El seu poder principal permet a l''usuari cosir qualsevol cosa entre si fent servir una agulla i un fil invisible i irrompible que la fruita genera.', ARRAY['Costura de Matèria: L''usuari pot cosir sense costures éssers vius, objectes o superfícies entre si. Pot immobilitzar els seus oponents cosint la seva roba o els seus cossos al terra sòlid, a parets o fins i tot a altres persones.','Perforació Indolora: L''agulla i el fil penetren el teixit viu a l''instant sense causar dolor físic ni vessar sang, permetent a l''usuari immobilitzar els enemics abans fins i tot que se n''adonin que han estat capturats.','Descosit (Alliberament): L''usuari pot desfer les seves puntades en qualsevol moment, alliberant a l''instant tot allò que estigués unit sense deixar cicatrius ni danys permanents.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0002a-6f01-70a2-abff-cf41c63e7f00' AND updated_at <= '2026-08-14T12:06:16.687596Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0002a-6f01-70a2-abff-cf41c63e7f00' AND updated_at <= '2026-08-14T12:06:16.687596Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0008c-a8fb-7ccf-8756-a490bc99fe70', 'en-GB', 'Allows the user to create, control, and transform their body into mud and quagmire, functioning as a bottomless liquid swamp.', ARRAY['Bottomless Quagmire: Any person or object that falls into the user''s mud sinks helplessly into a literal "bottomless swamp" and cannot escape on their own.','Suffocation: Enemy fighters swallowed by the mud are deprived of oxygen and can easily be suffocated into submission.','Arsenal Concealment: He can pull out hidden weapons—such as Gatling guns, scythes, cannons, or dynamite—directly from his body at a moment''s notice.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0008c-a8fb-7ccf-8756-a490bc99fe70' AND updated_at <= '2026-08-14T13:56:49.246289Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0008c-a8fb-7ccf-8756-a490bc99fe70' AND updated_at <= '2026-08-14T13:56:49.246289Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0008c-a8fb-7ccf-8756-a490bc99fe70', 'es-ES', 'Permite al usuario crear, controlar y transformar su cuerpo en barro y cenagal, funcionando como un pantano líquido sin fondo.', ARRAY['Cenagal Sin Fondo: Cualquier persona u objeto que caiga en el barro del usuario se hunde sin remedio en un literal "pantano sin fondo" y no puede escapar por sí mismo.','Asfixia: Los combatientes enemigos engullidos por el barro se ven privados de oxígeno y pueden ser fácilmente asfixiados hasta la sumisión.','Ocultación de Arsenal: Puede sacar armas ocultas —como ametralladoras Gatling, guadañas, cañones o dinamita— directamente de su cuerpo en cualquier momento.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0008c-a8fb-7ccf-8756-a490bc99fe70' AND updated_at <= '2026-08-14T13:56:49.246289Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0008c-a8fb-7ccf-8756-a490bc99fe70' AND updated_at <= '2026-08-14T13:56:49.246289Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0008c-a8fb-7ccf-8756-a490bc99fe70', 'ca-ES', 'Permet a l''usuari crear, controlar i transformar el seu cos en fang i sorral, funcionant com un pantà líquid sense fons.', ARRAY['Sorral Sense Fons: Qualsevol persona o objecte que caigui al fang de l''usuari s''enfonsa sense remei en un literal "pantà sense fons" i no pot escapar-ne per si mateix.','Asfíxia: Els combatents enemics engolits pel fang es veuen privats d''oxigen i poden ser fàcilment asfixiats fins a la submissió.','Ocultació d''Arsenal: Pot treure armes amagades —com metralladores Gatling, dalles, canons o dinamita— directament del seu cos en qualsevol moment.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0008c-a8fb-7ccf-8756-a490bc99fe70' AND updated_at <= '2026-08-14T13:56:49.246289Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0008c-a8fb-7ccf-8756-a490bc99fe70' AND updated_at <= '2026-08-14T13:56:49.246289Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fea87-7974-7584-b8eb-bd588adf6372', 'ca-ES', 'Coneguda com el "Fruit del Diable Suprem", atorga la capacitat de crear un espai esfèric delimitat ("Room") dins del qual l''usuari pot manipular lliurement la posició, l''orientació i la composició física de qualsevol cosa, com si fos un quiròfan.', ARRAY['Room: Crea la sala d''operacions esfèrica on s''apliquen totes les tècniques.','Ampute: Tallar objectes o persones sense causar ni ferides, ni sang, ni dolor físic.','Shambles: Intercanvia la posició d''objectes o persones dins de la Room, així com les seves personalitats o ànimes.','Takt: Permet moure o fer levitar objectes pesats o masses de terra mitjançant telequinesi.','Scan: Escaneja l''interior de la Room per trobar objectes o armes específiques.','Counter Shock: Genera una descàrrega elèctrica molt potent sobre l''objectiu, similar a un desfibril·lador.','Mes: Extreu el cor d''un individu contingut en un cub de carn, deixant la víctima incapaç de lluitar.','Gamma Knife: Genera un ganivet d''energia que destrueix els òrgans interns de l''enemic sense deixar marques exteriors.','Despertar (K-ROOM / R-ROOM): Permet impregnar les propietats de la Room directament en objectes (com la seva espasa) o anul·lar completament el so d''una zona.','Operació de la Joventut Perpetua: Atorga la joventut eterna a una altra persona a canvi de la vida del mateix usuari.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019fea87-7974-7584-b8eb-bd588adf6372' AND updated_at <= '2026-08-10T07:23:15.768356Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019fea87-7974-7584-b8eb-bd588adf6372' AND updated_at <= '2026-08-10T07:23:15.768356Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fea87-7974-7584-b8eb-bd588adf6372', 'en-GB', 'Known as the "Ultimate Devil Fruit", it grants the user the ability to create a spherical territory ("Room") where they can freely manipulate the position, orientation, and physical composition of anything inside, acting as a surgeon in an operating room.', ARRAY['Room: Creates the spherical operating space where all other techniques take place.','Ampute: Cleanly slices through targets without causing harm, bleeding, or actual pain.','Shambles: Teleports and swaps the physical positions of objects or people, as well as swapping personalities/souls.','Takt: Levitates and moves heavy objects or terrain within the Room via telekinesis.','Scan: Scans everything inside the Room to locate specific items or weapons.','Counter Shock: Delivers a powerful electrical surge directly to the target''s body, functioning like a defibrillator.','Mes: Strikes the chest to pop out a person''s heart enclosed in a fleshy cube, leaving them incapacitated.','Gamma Knife: Creates a blade of energy that destroys the victim''s internal organs without leaving external physical marks.','Awakening (K-ROOM / R-ROOM): Allows applying Room properties directly onto weapons or creating silent zones without expanding a full spatial sphere around the user.','Perpetual Youth Operation: Grants another individual eternal youth at the cost of the fruit user''s own life.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019fea87-7974-7584-b8eb-bd588adf6372' AND updated_at <= '2026-08-10T07:23:15.768356Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019fea87-7974-7584-b8eb-bd588adf6372' AND updated_at <= '2026-08-10T07:23:15.768356Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fea87-7974-7584-b8eb-bd588adf6372', 'es-ES', 'Conocida como la "Fruta del Diablo Suprema", otorga la capacidad de crear un espacio esférico delimitado ("Room") en el que el usuario puede manipular libremente la ubicación, orientación y constitución física de todo lo que se encuentre en su interior, como si de un quirófano se tratase.', ARRAY['Room: Crea la sala de operaciones esférica dentro de la cual se aplican todas las técnicas.','Ampute: Corta objetos o personas sin causar heridas ni dolor físico.','Shambles: Intercambia la posición de objetos o personas dentro de la Room, o incluso intercambia sus personalidades/almas.','Takt: Otorga telequinesis para mover objetos grandes o masas de tierra dentro del espacio.','Scan: Escanea el interior de la Room para localizar objetos o personas concretas.','Counter Shock: Libera una fuerte descarga eléctrica similar a la de un desfibrilador sobre el objetivo.','Mes: Extrae el corazón de un individuo intacto en un cubo de carne, dejando a la víctima debilitada.','Gamma Knife: Crea una cuchilla de energía que destruye los órganos internos del enemigo sin dejar heridas externas.','Kage Kioku / Kage Subete (Despertar): Permite recubrir objetos externos (como su espada) con las propiedades de la Room (K-ROOM) o silenciar sonidos (R-ROOM).','Operación de Juventud Perpetua: Concede la juventud eterna a otra persona a cambio de la propia vida del usuario.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019fea87-7974-7584-b8eb-bd588adf6372' AND updated_at <= '2026-08-10T07:23:15.768356Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019fea87-7974-7584-b8eb-bd588adf6372' AND updated_at <= '2026-08-10T07:23:15.768356Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000fb-1a84-77eb-b86c-64b19fa68caa', 'en-GB', 'Gives the user the ability to generate unbreakable steel bars directly from their body, instantly binding or caging anyone who passes through or makes physical contact with them.', ARRAY['Instant Contact Binding: When the user swipes her arms or limbs through an opponent, her body materializes solid iron shackles around them upon contact.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000fb-1a84-77eb-b86c-64b19fa68caa' AND updated_at <= '2026-08-14T15:54:12.153585Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000fb-1a84-77eb-b86c-64b19fa68caa' AND updated_at <= '2026-08-14T15:54:12.153585Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000fb-1a84-77eb-b86c-64b19fa68caa', 'ca-ES', 'Atorga a l''usuari la capacitat de generar barrots d''acer irrompibles directament des del seu cos, immobilitzant o engabiant a l''instant qualsevol que passi a través seu o entri en contacte físic amb ella.', ARRAY['Immobilització Instantània per Contacte: Quan la usuària llisca els braços o les extremitats a través d''un oponent, el seu cos materialitza grillons de ferro sòlid al seu voltant en el moment del contacte.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000fb-1a84-77eb-b86c-64b19fa68caa' AND updated_at <= '2026-08-14T15:54:12.153585Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000fb-1a84-77eb-b86c-64b19fa68caa' AND updated_at <= '2026-08-14T15:54:12.153585Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000fb-1a84-77eb-b86c-64b19fa68caa', 'es-ES', 'Otorga al usuario la capacidad de generar barrotes de acero irrompibles directamente desde su cuerpo, inmovilizando o enjaulando al instante a cualquiera que pase a través de ellos o entre en contacto físico con ella.', ARRAY['Inmovilización Instantánea por Contacto: Cuando la usuaria desliza sus brazos o extremidades a través de un oponente, su cuerpo materializa grilletes de hierro sólido a su alrededor en el momento del contacto.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000fb-1a84-77eb-b86c-64b19fa68caa' AND updated_at <= '2026-08-14T15:54:12.153585Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000fb-1a84-77eb-b86c-64b19fa68caa' AND updated_at <= '2026-08-14T15:54:12.153585Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00087-4b60-7b92-bc95-97003ae10f00', 'en-GB', 'Allows the user to create, control, and transform their body into light at will, granting near-unmatchable speed and extreme energy output.', ARRAY['Light-Speed Kicks: Kizaru converts his legs into light to deliver kinetic strikes infused with mass and light speed.','Mirror Reflection: By emitting beams that bounce off reflective surfaces, the user can instantly teleport along light paths to flank enemies (Yata no Kagami).','Intangibility: As a Logia user, physical strikes, sword slashes, and artillery rounds pass through Kizaru''s light form harmlessly, leaving glowing yellow gaps that immediately reform.','Laser Charges: The user can fire piercing light beams from their fingertips or feet that cause massive thermal explosions upon contact.','Light Constructs: Kizaru can solidify light into weapons, such as a long, razor-sharp sword of pure light (Ame no Murakumo).','Barrage Attacks: The user can ascend into the air and shower an immense area with thousands of destructive light particles (Yasakani no Magatama).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00087-4b60-7b92-bc95-97003ae10f00' AND updated_at <= '2026-08-14T13:55:58.718336Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00087-4b60-7b92-bc95-97003ae10f00' AND updated_at <= '2026-08-14T13:55:58.718336Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00087-4b60-7b92-bc95-97003ae10f00', 'es-ES', 'Permite al usuario crear, controlar y transformar su cuerpo en luz a voluntad, otorgándole una velocidad casi inigualable y una capacidad energética extrema.', ARRAY['Patadas a la Velocidad de la Luz: Kizaru convierte sus piernas en luz para asestar golpes cinéticos cargados de masa y velocidad lumínica.','Reflejo de Espejo: Emitiendo rayos que rebotan en superficies reflectantes, el usuario puede teletransportarse al instante a lo largo de trayectorias de luz para flanquear a sus enemigos (Yata no Kagami).','Intangibilidad: Como usuario Logia, los golpes físicos, los tajos de espada y los proyectiles de artillería atraviesan inofensivamente la forma de luz de Kizaru, dejando huecos amarillos brillantes que se recomponen de inmediato.','Cargas Láser: El usuario puede disparar rayos de luz perforantes desde las yemas de los dedos o los pies que provocan enormes explosiones térmicas al impactar.','Constructos de Luz: Kizaru puede solidificar la luz en armas, como una espada larga y afilada de luz pura (Ame no Murakumo).','Ataques en Andanada: El usuario puede ascender por los aires y bombardear un área inmensa con miles de partículas de luz destructivas (Yasakani no Magatama).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00087-4b60-7b92-bc95-97003ae10f00' AND updated_at <= '2026-08-14T13:55:58.718336Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00087-4b60-7b92-bc95-97003ae10f00' AND updated_at <= '2026-08-14T13:55:58.718336Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00087-4b60-7b92-bc95-97003ae10f00', 'ca-ES', 'Permet a l''usuari crear, controlar i transformar el seu cos en llum a voluntat, atorgant-li una velocitat gairebé inigualable i una capacitat energètica extrema.', ARRAY['Puntades a la Velocitat de la Llum: Kizaru converteix les seves cames en llum per assestar cops cinètics carregats de massa i velocitat lumínica.','Reflex de Mirall: Emetent raigs que reboten en superfícies reflectants, l''usuari pot teletransportar-se a l''instant al llarg de trajectòries de llum per flanquejar els enemics (Yata no Kagami).','Intangibilitat: Com a usuari Logia, els cops físics, les ganivetades d''espasa i els projectils d''artilleria travessen inofensivament la forma de llum de Kizaru, deixant buits grocs brillants que es recomponen immediatament.','Càrregues Làser: L''usuari pot disparar raigs de llum perforants des de les puntes dels dits o els peus que provoquen enormes explosions tèrmiques en impactar.','Constructes de Llum: Kizaru pot solidificar la llum en armes, com una espasa llarga i esmolada de llum pura (Ame no Murakumo).','Atacs en Ràfega: L''usuari pot ascendir pels aires i bombardejar una àrea immensa amb milers de partícules de llum destructives (Yasakani no Magatama).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00087-4b60-7b92-bc95-97003ae10f00' AND updated_at <= '2026-08-14T13:55:58.718336Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00087-4b60-7b92-bc95-97003ae10f00' AND updated_at <= '2026-08-14T13:55:58.718336Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000dc-e2eb-78d8-af19-32beb979ede2', 'en-GB', 'Allows the user to transform into an allosaurus hybrid or a full prehistoric allosaurus, granting devastating biting power, thick armor plating, and immense ancient physical strength.', ARRAY['Prehistoric Bite & Jaw Strength: In full beast form, the user transforms into a gigantic theropod dinosaur. His massive jaw structure delivers crushing bite force capable of ripping through steel, breaking bone, and biting through military armor with ease.','Enhanced Recovery: Allows the user to recover rapidly from blunt physical trauma and heavy elemental strikes during drawn-out battles.','Heavyweight Trampling: His heavy tail and thick legs can deliver bone-shattering tail whips and stomps that clear out groups of infantry.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000dc-e2eb-78d8-af19-32beb979ede2' AND updated_at <= '2026-08-14T15:21:11.899998Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000dc-e2eb-78d8-af19-32beb979ede2' AND updated_at <= '2026-08-14T15:21:11.899998Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000dc-e2eb-78d8-af19-32beb979ede2', 'es-ES', 'Permite al usuario transformarse en un híbrido de alosaurio o en un alosaurio prehistórico completo, otorgándole un poder de mordida devastador, una gruesa placa de blindaje y una inmensa fuerza física ancestral.', ARRAY['Mordida y Fuerza de Mandíbula Prehistóricas: En su forma bestial completa, el usuario se transforma en un dinosaurio terópodo gigantesco. Su enorme estructura mandibular ejerce una fuerza de mordida aplastante capaz de desgarrar el acero, romper huesos y atravesar blindaje militar con facilidad.','Recuperación Mejorada: Permite al usuario recuperarse rápidamente de traumatismos físicos contundentes y golpes elementales intensos durante batallas prolongadas.','Pisoteo de Peso Pesado: Su pesada cola y sus gruesas patas pueden asestar coletazos y pisotones capaces de romper huesos, arrasando con grupos enteros de infantería.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000dc-e2eb-78d8-af19-32beb979ede2' AND updated_at <= '2026-08-14T15:21:11.899998Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000dc-e2eb-78d8-af19-32beb979ede2' AND updated_at <= '2026-08-14T15:21:11.899998Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000dc-e2eb-78d8-af19-32beb979ede2', 'ca-ES', 'Permet a l''usuari transformar-se en un híbrid d''al·losaure o en un al·losaure prehistòric complet, atorgant-li un poder de mossegada devastador, una gruixuda placa de blindatge i una immensa força física ancestral.', ARRAY['Mossegada i Força de Mandíbula Prehistòriques: En la seva forma bestial completa, l''usuari es transforma en un dinosaure teròpode gegantí. La seva enorme estructura mandibular exerceix una força de mossegada aixafadora capaç d''esquinçar l''acer, trencar ossos i travessar blindatge militar amb facilitat.','Recuperació Millorada: Permet a l''usuari recuperar-se ràpidament de traumatismes físics contundents i cops elementals intensos durant batalles prolongades.','Trepitjada de Pes Pesant: La seva pesada cua i les seves gruixudes potes poden assestar cop de cua i trepitjades capaces de trencar ossos, escombrant grups sencers d''infanteria.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000dc-e2eb-78d8-af19-32beb979ede2' AND updated_at <= '2026-08-14T15:21:11.899998Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000dc-e2eb-78d8-af19-32beb979ede2' AND updated_at <= '2026-08-14T15:21:11.899998Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000e4-5d18-7669-80db-77b1076b3adc', 'en-GB', 'Allows the user to transform into a brachiosaurus hybrid or a full prehistoric brachiosaurus, granting colossal physical size, extreme weight, crushing power, and intense Ancient Zoan durability.', ARRAY['Brachio Bombs & Heavy Stomps: Jumping from great heights in his beast form allows the user to crush targets under thousands of tons of body weight—a maneuver strong enough to knock out an amnesiac Big Mom temporarily (Brachio Bomber).','Bone-Crushing Constriction: The user can wrap his elongated neck and tail around enemies to crush their bodies, claiming the pressure is immense enough to break even advanced Armament Haki masters.','High Endurance: The user easily tanks heavy physical strikes, slashes, and elemental blasts, shaking off blunt trauma that would instantly defeat standard fighters.','Brachio-Snake-us: The user completely ejects his head, long neck, and tail directly out of his main body, turning into a giant, living "brachiosaurus snake."','Constriction Lock: The snake-torso coils tightly around the enemy to crush their ribs and internal organs.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000e4-5d18-7669-80db-77b1076b3adc' AND updated_at <= '2026-08-14T15:29:21.897713Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000e4-5d18-7669-80db-77b1076b3adc' AND updated_at <= '2026-08-14T15:29:21.897713Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000e4-5d18-7669-80db-77b1076b3adc', 'es-ES', 'Permite al usuario transformarse en un híbrido de braquiosaurio o en un braquiosaurio prehistórico completo, otorgándole un tamaño físico colosal, un peso extremo, un poder aplastante y una intensa resistencia de Zoan Ancestral.', ARRAY['Bombas Braquio y Pisotones Pesados: Saltando desde grandes alturas en su forma bestial, el usuario puede aplastar a sus objetivos bajo miles de toneladas de peso corporal, una maniobra lo bastante potente como para dejar fuera de combate temporalmente a una Big Mom amnésica (Brachio Bomber).','Constricción Rompehuesos: El usuario puede enrollar su cuello y cola alargados alrededor de los enemigos para aplastar sus cuerpos, alegando que la presión es lo bastante inmensa como para quebrar incluso a maestros avanzados del Haki de Armadura.','Alta Resistencia: El usuario encaja con facilidad golpes físicos pesados, tajos y ráfagas elementales, sacudiéndose traumatismos contundentes que derrotarían al instante a luchadores normales.','Braquio-Serpiente-us: El usuario expulsa por completo su cabeza, su largo cuello y su cola directamente fuera de su cuerpo principal, convirtiéndose en una gigantesca ''serpiente braquiosaurio'' viviente.','Bloqueo de Constricción: El torso-serpiente se enrosca con fuerza alrededor del enemigo para aplastarle las costillas y los órganos internos.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000e4-5d18-7669-80db-77b1076b3adc' AND updated_at <= '2026-08-14T15:29:21.897713Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000e4-5d18-7669-80db-77b1076b3adc' AND updated_at <= '2026-08-14T15:29:21.897713Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000e4-5d18-7669-80db-77b1076b3adc', 'ca-ES', 'Permet a l''usuari transformar-se en un híbrid de braquiosaure o en un braquiosaure prehistòric complet, atorgant-li una mida física colossal, un pes extrem, un poder aixafador i una intensa resistència de Zoan Ancestral.', ARRAY['Bombes Braquio i Trepitjades Pesants: Saltant des de grans alçades en la seva forma bestial, l''usuari pot aixafar els seus objectius sota milers de tones de pes corporal, una maniobra prou potent com per deixar fora de combat temporalment una Big Mom amnèsica (Brachio Bomber).','Constricció Trencaossos: L''usuari pot enrotllar el seu coll i cua allargats al voltant dels enemics per aixafar-los el cos, afirmant que la pressió és prou immensa com per trencar fins i tot mestres avançats del Haki d''Armadura.','Alta Resistència: L''usuari encaixa amb facilitat cops físics pesants, ganivetades i ràfegues elementals, sacsejant-se traumatismes contundents que derrotarien a l''instant lluitadors normals.','Braquio-Serp-us: L''usuari expulsa completament el seu cap, el seu coll llarg i la seva cua directament fora del seu cos principal, convertint-se en una gegantina ''serp braquiosaure'' vivent.','Bloqueig de Constricció: El tors-serp s''enrosca amb força al voltant de l''enemic per aixafar-li les costelles i els òrgans interns.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000e4-5d18-7669-80db-77b1076b3adc' AND updated_at <= '2026-08-14T15:29:21.897713Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000e4-5d18-7669-80db-77b1076b3adc' AND updated_at <= '2026-08-14T15:29:21.897713Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00072-8c69-741b-9f29-30e0cf902994', 'ca-ES', 'Originàriament devorada pel llegendari "Déu Guerrer", aquesta fruita es considera un tresor nacional a Elbaph i va ser protegida durant segles per Ragnir. Finalment va ser consumida per Loki fa 14 anys, després d''aconseguir domar Ragnir.', ARRAY['Forma Bestial: Transforma completament l''usuari en un drac fosc massiu i esfereïdor, amb escates fosques, ales immenses, urpes esmolades i una cua serpentina feta per a la destrucció.','Forma Híbrida: Fusiona la mobilitat humana amb trets de drac —fent brotar ales de drac fosc, urpes esmoladíssimes, una armadura d''escates, ullals i una cua—, maximitzant el poder en combat cos a cos.','Alè de Verí i Corrosió: Inspirat en l''associació de Níðhöggr amb el verí i els cadàvers, l''usuari pot emetre un alè de drac letal i corrosiu capaç de fondre armadures, erosionar defenses i enverinar els objectius en contacte.','Arrels de la Decadència i Manipulació de la Terra: Reflectint Níðhöggr rosegant les arrels de l''Arbre del Món, la fruita permet a l''usuari canalitzar energia fosca a través del terra per debilitar estructures, descompondre matèria viva o provocar tremolors de terra.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00072-8c69-741b-9f29-30e0cf902994' AND updated_at <= '2026-08-14T13:26:28.717779Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00072-8c69-741b-9f29-30e0cf902994' AND updated_at <= '2026-08-14T13:26:28.717779Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00072-8c69-741b-9f29-30e0cf902994', 'en-GB', 'Originally eaten by the legendary "Warrior God", this fruit is considered a national treasure in Elbaph and was protected for centuries by Ragnir. It was ultimately consumed by Loki 14 years ago after he managed to tame Ragnir.', ARRAY['Beast Form: Transforms the user completely into a massive, terrifying dark dragon with dark scales, immense wings, sharp talons, and a serpentine tail built for destruction.','Hybrid Form: Merges human mobility with dragon features—sprouting dark dragon wings, razor-sharp claws, scale armor, fangs, and a tail, maximizing close-quarters combat power.','Venom & Corrosion Breath: Inspired by Níðhöggr’s association with venom and corpses, the user can emit lethal, corrosive dragon breath capable of melting armor, eroding defenses, and poisoning targets upon contact.','Roots of Decay & Earth Manipulation: Reflecting Níðhöggr gnawing at the roots of the World Tree, the fruit allows the user to channel dark energy through the ground to weaken structures, decay living matter, or cause earth tremors.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00072-8c69-741b-9f29-30e0cf902994' AND updated_at <= '2026-08-14T13:26:28.717779Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00072-8c69-741b-9f29-30e0cf902994' AND updated_at <= '2026-08-14T13:26:28.717779Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00072-8c69-741b-9f29-30e0cf902994', 'es-ES', 'Originalmente devorada por el legendario "Dios Guerrero", esta fruta se considera un tesoro nacional en Elbaph y fue protegida durante siglos por Ragnir. Finalmente fue consumida por Loki hace 14 años, tras conseguir domar a Ragnir.', ARRAY['Forma Bestial: Transforma por completo al usuario en un dragón oscuro masivo y aterrador, con escamas oscuras, alas inmensas, garras afiladas y una cola serpentina hecha para la destrucción.','Forma Híbrida: Fusiona la movilidad humana con rasgos de dragón —haciendo brotar alas de dragón oscuro, garras afiladísimas, una armadura de escamas, colmillos y una cola—, maximizando el poder en combate cuerpo a cuerpo.','Aliento de Veneno y Corrosión: Inspirado en la asociación de Níðhöggr con el veneno y los cadáveres, el usuario puede emitir un aliento de dragón letal y corrosivo capaz de fundir armaduras, erosionar defensas y envenenar a los objetivos al contacto.','Raíces de la Decadencia y Manipulación de la Tierra: Reflejando a Níðhöggr royendo las raíces del Árbol del Mundo, la fruta permite al usuario canalizar energía oscura a través del suelo para debilitar estructuras, descomponer materia viva o provocar temblores de tierra.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00072-8c69-741b-9f29-30e0cf902994' AND updated_at <= '2026-08-14T13:26:28.717779Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00072-8c69-741b-9f29-30e0cf902994' AND updated_at <= '2026-08-14T13:26:28.717779Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000e6-cbf6-76d4-b464-0203c66690b2', 'en-GB', 'Allows the user to transform into a pachycephalosaurus hybrid or a full prehistoric pachycephalosaurus, granting an extraordinarily thick dome skull, extreme headbutting power, and Ancient Zoan endurance.', ARRAY['Ulti-Meteo (Ulti Meteor): Ulti grabs a target with her hands to pin them in place, leaps into the air, and slams her domed head directly into theirs. The sheer kinetic impact creates localized shockwaves capable of shattering stone, cracking armor, and breaking an opponent''s skull.','Haki Synergy: Stacking Busoshoku Haki (Armament Haki) onto her dense dinosaur skull elevates her headbutt into a lethal cannon-like strike, capable of staggering even high-level fighters like Monkey D. Luffy.','Relentless Tenacity: Ulti took point-blank hits from Luffy, a surprise lightning bolt strike from Nami, a combination attack from Yamato, and a full-powered combined attack from Big Mom (Maser Cannon), yet continuously got back up to fight.','Aggressive Hybrid Brawling: In her hybrid form, Ulti retains her fast human locomotion while gaining dinosaur claws, a muscular tail, and her reinforced head structure, making her an extremely aggressive, short-range melee brawler.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000e6-cbf6-76d4-b464-0203c66690b2' AND updated_at <= '2026-08-14T15:32:01.500175Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000e6-cbf6-76d4-b464-0203c66690b2' AND updated_at <= '2026-08-14T15:32:01.500175Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000e6-cbf6-76d4-b464-0203c66690b2', 'es-ES', 'Permite al usuario transformarse en un híbrido de paquicefalosaurio o en un paquicefalosaurio prehistórico completo, otorgándole un cráneo abovedado extraordinariamente grueso, un poder de cabezazo extremo y resistencia de Zoan Ancestral.', ARRAY['Ulti-Meteo (Ulti Meteor): Ulti sujeta a un objetivo con las manos para inmovilizarlo, salta por los aires y estrella su cabeza abovedada directamente contra la de su rival. El puro impacto cinético genera ondas de choque localizadas capaces de agrietar piedra, resquebrajar blindajes y romper el cráneo del oponente.','Sinergia de Haki: Reforzando con Haki de Armadura (Busoshoku Haki) su denso cráneo de dinosaurio, eleva su cabezazo a un golpe letal similar a un cañonazo, capaz de tambalear incluso a luchadores de alto nivel como Monkey D. Luffy.','Tenacidad Implacable: Ulti recibió golpes a quemarropa de Luffy, un rayo sorpresa de Nami, un ataque combinado de Yamato y un ataque combinado a plena potencia de Big Mom (Maser Cannon), y aun así se levantó una y otra vez para seguir luchando.','Combate Híbrido Agresivo: En su forma híbrida, Ulti conserva su rápida locomoción humana mientras gana garras de dinosaurio, una cola musculosa y su estructura craneal reforzada, convirtiéndola en una luchadora de cuerpo a cuerpo extremadamente agresiva de corto alcance.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000e6-cbf6-76d4-b464-0203c66690b2' AND updated_at <= '2026-08-14T15:32:01.500175Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000e6-cbf6-76d4-b464-0203c66690b2' AND updated_at <= '2026-08-14T15:32:01.500175Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000e6-cbf6-76d4-b464-0203c66690b2', 'ca-ES', 'Permet a l''usuari transformar-se en un híbrid de paquicefalosaure o en un paquicefalosaure prehistòric complet, atorgant-li un crani abovedat extraordinàriament gruixut, un poder de cop de cap extrem i resistència de Zoan Ancestral.', ARRAY['Ulti-Meteo (Ulti Meteor): Ulti agafa un objectiu amb les mans per immobilitzar-lo, salta pels aires i estampa el seu cap abovedat directament contra el del rival. El pur impacte cinètic genera ones de xoc localitzades capaces d''esquerdar pedra, trencar blindatges i trencar el crani de l''oponent.','Sinergia de Haki: Reforçant amb Haki d''Armadura (Busoshoku Haki) el seu dens crani de dinosaure, eleva el seu cop de cap a un atac letal semblant a una canonada, capaç de fer trontollar fins i tot lluitadors d''alt nivell com Monkey D. Luffy.','Tenacitat Implacable: Ulti va rebre cops a boca de canó de Luffy, un llamp sorpresa de Nami, un atac combinat de Yamato i un atac combinat a plena potència de Big Mom (Maser Cannon), i tot i així es va aixecar una vegada i una altra per seguir lluitant.','Combat Híbrid Agressiu: En la seva forma híbrida, Ulti conserva la seva ràpida locomoció humana mentre guanya urpes de dinosaure, una cua musculosa i la seva estructura cranial reforçada, convertint-la en una lluitadora de cos a cos extremadament agressiva de curt abast.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000e6-cbf6-76d4-b464-0203c66690b2' AND updated_at <= '2026-08-14T15:32:01.500175Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000e6-cbf6-76d4-b464-0203c66690b2' AND updated_at <= '2026-08-14T15:32:01.500175Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000e1-9b8f-733f-9d96-a2fdd0496e47', 'es-ES', 'Permite al usuario transformarse en un híbrido de pteranodonte o en un pteranodonte prehistórico completo, otorgándole velocidades de vuelo extremas, un inmenso impacto aéreo y una piel resistente.', ARRAY['Empuje Contra Barcos: Su pura fuerza cinética y su envergadura son lo bastante fuertes como para derribar él solo el gigantesco buque insignia de Big Mom, el Queen Mama Chanter, desde lo alto de la Cascada de Wano.','Cuchillas Aladas Afiladas: Los bordes de sus alas de aspecto correoso actúan como enormes cuchillas rígidas capaces de cortar piedra, metal y cascos de barco en pleno vuelo.','Tempura Udon (Snort Rubber): El usuario estira hacia atrás como una honda la cresta orientada hacia atrás de su cabeza, tensando su rostro antes de soltarlo para lanzar su cabeza hacia delante. Esto dispara un golpe de pico a alta velocidad, similar a un láser (Imperial Deep Stinger), que se mueve demasiado rápido para percibirlo y puede perforar limpiamente roca y metal.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000e1-9b8f-733f-9d96-a2fdd0496e47' AND updated_at <= '2026-08-14T15:26:21.366063Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000e1-9b8f-733f-9d96-a2fdd0496e47' AND updated_at <= '2026-08-14T15:26:21.366063Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000e1-9b8f-733f-9d96-a2fdd0496e47', 'en-GB', 'Allows the user to transform into a pteranodon hybrid or a full prehistoric pteranodon, granting extreme flight speeds, immense aerial impact, and durable hide.', ARRAY['Ship Knockback: His sheer kinetic force and wingspan are strong enough to single-handedly knock Big Mom''s giant flagship, the Queen Mama Chanter, off the top of the Waterfall of Wano.','Sharp Wing Blades: The edges of his leather-like wings act as giant, rigid blades capable of slicing through stone, metal, and ship hulls mid-flight.','Tempura Udon (Snort Rubber): The user pulls the backward-facing crest on his head like a slingshot, stretching his face back before releasing it to snap his head forward. This fires a high-velocity, laser-like beak strike (Imperial Deep Stinger) that moves too fast to perceive and can punch clean holes through rock and metal.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000e1-9b8f-733f-9d96-a2fdd0496e47' AND updated_at <= '2026-08-14T15:26:21.366063Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000e1-9b8f-733f-9d96-a2fdd0496e47' AND updated_at <= '2026-08-14T15:26:21.366063Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000e1-9b8f-733f-9d96-a2fdd0496e47', 'ca-ES', 'Permet a l''usuari transformar-se en un híbrid de pteranodont o en un pteranodont prehistòric complet, atorgant-li velocitats de vol extremes, un immens impacte aeri i una pell resistent.', ARRAY['Empenta Contra Vaixells: La seva pura força cinètica i la seva envergadura són prou fortes com per fer caure ell sol el gegantí vaixell insígnia de Big Mom, el Queen Mama Chanter, des de dalt de la Cascada de Wano.','Fulles Alades Esmolades: Les vores de les seves ales d''aspecte coriaci actuen com a enormes fulles rígides capaces de tallar pedra, metall i cascos de vaixell en ple vol.','Tempura Udon (Snort Rubber): L''usuari estira cap enrere com un tirador la cresta orientada cap enrere del seu cap, tensant el seu rostre abans d''alliberar-lo per llançar el cap cap endavant. Això dispara un cop de bec a alta velocitat, semblant a un làser (Imperial Deep Stinger), que es mou massa ràpid per percebre''l i pot perforar netament roca i metall.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000e1-9b8f-733f-9d96-a2fdd0496e47' AND updated_at <= '2026-08-14T15:26:21.366063Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000e1-9b8f-733f-9d96-a2fdd0496e47' AND updated_at <= '2026-08-14T15:26:21.366063Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000df-7a6e-73d7-8275-7655594e3c77', 'ca-ES', 'Permet a l''usuari transformar-se en un híbrid d''espinosaure o en un espinosaure prehistòric complet, atorgant-li una mida física massiva, urpes esmoladíssimes, un poder de mossegada immens i una resistència extrema de Zoan Ancestral.', ARRAY['Mossegades Aixafadores: Les seves mandíbules allargades exerceixen una força de subjecció pura capaç de mossegar a través d''edificis, estructures de pedra i oponents blindats.','Vela Massiva i Cops de Cua: La seva pesada i musculosa cua pot escombrar múltiples oponents alhora, mentre que el seu llarg musell li dona un abast de cop més gran en comparació amb els teròpodes estàndard.','Alta Tolerància al Dany','Recuperació i Resistència de Zoan Ancestral']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000df-7a6e-73d7-8275-7655594e3c77' AND updated_at <= '2026-08-14T15:24:01.957479Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000df-7a6e-73d7-8275-7655594e3c77' AND updated_at <= '2026-08-14T15:24:01.957479Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000df-7a6e-73d7-8275-7655594e3c77', 'en-GB', 'Allows the user to transform into a spinosaurus hybrid or a full prehistoric spinosaurus, granting massive physical size, razor-sharp claws, immense biting power, and extreme Ancient Zoan durability.', ARRAY['Crushing Bites: His elongated jaws deliver sheer clamping force capable of biting through buildings, stone structures, and armored opponents.','Massive Sail & Tail Whips: His heavy, muscular tail can sweep away multiple opponents, while his long snout gives him an extended striking range compared to standard theropods.','High Damage Tolerance','Ancient Zoan Recovery & Durability']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000df-7a6e-73d7-8275-7655594e3c77' AND updated_at <= '2026-08-14T15:24:01.957479Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000df-7a6e-73d7-8275-7655594e3c77' AND updated_at <= '2026-08-14T15:24:01.957479Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000df-7a6e-73d7-8275-7655594e3c77', 'es-ES', 'Permite al usuario transformarse en un híbrido de espinosaurio o en un espinosaurio prehistórico completo, otorgándole un tamaño físico masivo, garras afiladísimas, un poder de mordida inmenso y una extrema resistencia de Zoan Ancestral.', ARRAY['Mordiscos Aplastantes: Sus mandíbulas alargadas ejercen una fuerza de sujeción pura capaz de morder a través de edificios, estructuras de piedra y oponentes blindados.','Vela Masiva y Coletazos: Su pesada y musculosa cola puede barrer a múltiples oponentes a la vez, mientras que su largo hocico le da un alcance de golpeo mayor en comparación con los terópodos estándar.','Alta Tolerancia al Daño','Recuperación y Resistencia de Zoan Ancestral']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000df-7a6e-73d7-8275-7655594e3c77' AND updated_at <= '2026-08-14T15:24:01.957479Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000df-7a6e-73d7-8275-7655594e3c77' AND updated_at <= '2026-08-14T15:24:01.957479Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000e8-5a85-750f-80ea-f41ea191a23e', 'en-GB', 'Allows the user to transform into a triceratops hybrid or a full prehistoric triceratops, granting three massive facial horns, a dense defensive frill, and immense charging momentum.', ARRAY['Goring Charges: A full-speed charge from Sasaki can break through thick steel plating, concrete fortifications, and Franky''s giant battle mech (General Franky).','Frontal Defense: The large, bony neck frill acts as a heavy shield, deflecting direct gunfire, sword slashes, and artillery shells from the front.','Rapid Stamina Regrowth: Allows Sasaki to take heavy explosives and physical blows while recovering quickly to re-engage in battle.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000e8-5a85-750f-80ea-f41ea191a23e' AND updated_at <= '2026-08-14T15:33:43.301257Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000e8-5a85-750f-80ea-f41ea191a23e' AND updated_at <= '2026-08-14T15:33:43.301257Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000e8-5a85-750f-80ea-f41ea191a23e', 'es-ES', 'Permite al usuario transformarse en un híbrido de triceratops o en un triceratops prehistórico completo, otorgándole tres enormes cuernos faciales, un denso collar defensivo y un inmenso impulso de carga.', ARRAY['Cargas de Corneada: Una carga a plena velocidad de Sasaki puede atravesar gruesas planchas de acero, fortificaciones de hormigón y el gigantesco mecha de batalla de Franky (General Franky).','Defensa Frontal: Su gran collar óseo en el cuello actúa como un escudo pesado, desviando disparos directos, tajos de espada y proyectiles de artillería desde el frente.','Rápida Regeneración de Resistencia: Permite a Sasaki encajar explosivos pesados y golpes físicos mientras se recupera rápidamente para volver a entrar en batalla.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000e8-5a85-750f-80ea-f41ea191a23e' AND updated_at <= '2026-08-14T15:33:43.301257Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000e8-5a85-750f-80ea-f41ea191a23e' AND updated_at <= '2026-08-14T15:33:43.301257Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000e8-5a85-750f-80ea-f41ea191a23e', 'ca-ES', 'Permet a l''usuari transformar-se en un híbrid de triceratops o en un triceratops prehistòric complet, atorgant-li tres enormes banyes facials, un dens coll defensiu i un immens impuls de càrrega.', ARRAY['Càrregues de Cornada: Una càrrega a plena velocitat de Sasaki pot travessar gruixudes planxes d''acer, fortificacions de formigó i el gegantí mecha de batalla de Franky (General Franky).','Defensa Frontal: El seu gran coll ossi al voltant del coll actua com un escut pesant, desviant trets directes, ganivetades d''espasa i projectils d''artilleria des del davant.','Ràpida Regeneració de Resistència: Permet a Sasaki encaixar explosius pesants i cops físics mentre es recupera ràpidament per tornar a entrar en batalla.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000e8-5a85-750f-80ea-f41ea191a23e' AND updated_at <= '2026-08-14T15:33:43.301257Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000e8-5a85-750f-80ea-f41ea191a23e' AND updated_at <= '2026-08-14T15:33:43.301257Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00067-72bf-7c60-badf-604afea71360', 'en-GB', 'Its main power grants the consumer the ability to transform into a full axolotl or an axolotl-human hybrid, gaining amphibious traits and aquatic creature physiology.', ARRAY['Amphibious Traits: Grants axolotl features such as external frilled gills, quadrupedal movement, and aquatic-type physical flexibility.','Axolotl Regenerative Properties: Real-world axolotls are famous for limb and organ regeneration. In One Piece, this trait allowed Smiley''s gel-like body to reform and stitch itself back together when split apart by physical attacks.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00067-72bf-7c60-badf-604afea71360' AND updated_at <= '2026-08-14T13:14:24.062823Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00067-72bf-7c60-badf-604afea71360' AND updated_at <= '2026-08-14T13:14:24.062823Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00067-72bf-7c60-badf-604afea71360', 'es-ES', 'Su poder principal otorga a quien la consume la capacidad de transformarse en un ajolote completo o en un híbrido humano-ajolote, adquiriendo rasgos anfibios y una fisiología de criatura acuática.', ARRAY['Rasgos Anfibios: Otorga características de ajolote como branquias externas con volantes, movimiento cuadrúpedo y una flexibilidad física de tipo acuático.','Propiedades Regenerativas de Ajolote: En el mundo real, los ajolotes son famosos por regenerar extremidades y órganos. En One Piece, este rasgo permitió que el cuerpo gelatinoso de Smiley se recompusiera y volviera a coserse a sí mismo cuando era partido por ataques físicos.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00067-72bf-7c60-badf-604afea71360' AND updated_at <= '2026-08-14T13:14:24.062823Z'::timestamptz)
