INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00067-72bf-7c60-badf-604afea71360', 'ca-ES', 'El seu poder principal atorga a qui la consumeix la capacitat de transformar-se en un axolot complet o en un híbrid humà-axolot, adquirint trets amfibis i una fisiologia de criatura aquàtica.', ARRAY['Trets Amfibis: Atorga característiques d''axolot com brànquies externes amb volants, moviment quadrúpede i una flexibilitat física de tipus aquàtic.','Propietats Regeneratives d''Axolot: Al món real, els axolots són famosos per regenerar extremitats i òrgans. A One Piece, aquest tret va permetre que el cos gelatinós de Smiley es recomposés i es tornés a cosir a si mateix quan era partit per atacs físics.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00067-72bf-7c60-badf-604afea71360' AND updated_at <= '2026-08-14T13:14:24.062823Z'::timestamptz)
