INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019fea4a-f80d-7266-b28b-166026156d3a', 'ca-ES', 'Usuari: Jean Pierre Polnareff

Silver Chariot és un Stand de curt abast reconegut per la seva immensa velocitat, destresa i precisió en l''esgrima.', ARRAY['Domini de l''Esgrima: Mostra una precisió i velocitat extraordinàries amb el seu fioret, sent capaç de desviar bales, tallar foc i travessar materials densos.','Treure''s l''Armadura: Pot desprendre''s de la seva pesada armadura per incrementar dràsticament la seva velocitat, movent-se tan de pressa que crea múltiples imatges residuals per confondre l''adversari.','Dispar de Fioret: Pot projectar la fulla del seu fioret com un projectil sorpresa amb molta velocitat i precisió.']::text[]
