INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a06bdf-a524-796b-bf91-01a0f79a5c40', 'en-GB', 'User: Jotaro Kujo

Star Platinum is a short-range Stand, with a basic range of only 2 metres from its user''s body, but with incredible strength, speed and precision.

Time Stop: Allows the user to freeze the flow of time for everyone except himself.
Time limit: At his peak power (Stardust Crusaders), Jotaro can stop time for a maximum of 5 seconds.', ARRAY['Stop Time','Super Strength','Super Speed','Self-Preservation','Precision','Enhanced Vision','Star Finger']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a06bdf-a524-796b-bf91-01a0f79a5c40' AND updated_at <= '2026-09-27T14:47:41.522895Z'::timestamptz)
