INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019ffff7-65dc-7563-a4ee-96fe64e3d95d', 'en-GB', 'The Sube Sube no Mi is a Devil Fruit that makes the user''s body smooth and slippery, which in turn makes most attacks and objects slide off their body, protecting the user from harm in most situations.', ARRAY['Friction Elimination: The user can slide across surfaces like a ice skater at high speeds—even barefoot—by completely removing friction from their skin or soles.','Physical Transformation: As a side effect, the fruit strips away all excess weight, skin blemishes, and rough features, leaving the user with flawless, sleek skin and a noticeably slimmer physique.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019ffff7-65dc-7563-a4ee-96fe64e3d95d' AND updated_at <= '2026-08-14T11:10:47.874539Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019ffff7-65dc-7563-a4ee-96fe64e3d95d' AND updated_at <= '2026-08-14T11:10:47.874539Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019ffff7-65dc-7563-a4ee-96fe64e3d95d', 'es-ES', 'La Sube Sube no Mi es una Fruta del Diablo que vuelve el cuerpo del usuario liso y resbaladizo, lo que a su vez hace que la mayoría de ataques y objetos se deslicen sobre su cuerpo, protegiéndolo de daño en la mayoría de las situaciones.', ARRAY['Eliminación de la Fricción: El usuario puede deslizarse sobre las superficies como un patinador sobre hielo a gran velocidad —incluso descalzo— eliminando por completo la fricción de su piel o de las plantas de sus pies.','Transformación Física: Como efecto secundario, la fruta elimina todo el peso sobrante, las imperfecciones de la piel y los rasgos ásperos, dejando al usuario con una piel impecable y tersa y una complexión notablemente más esbelta.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019ffff7-65dc-7563-a4ee-96fe64e3d95d' AND updated_at <= '2026-08-14T11:10:47.874539Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019ffff7-65dc-7563-a4ee-96fe64e3d95d' AND updated_at <= '2026-08-14T11:10:47.874539Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '019ffff7-65dc-7563-a4ee-96fe64e3d95d', 'ca-ES', 'La Sube Sube no Mi és una Fruita del Diable que fa que el cos de l''usuari sigui llis i lliscós, la qual cosa fa que la majoria d''atacs i objectes rellisquin sobre el seu cos, protegint-lo de mal en la majoria de situacions.', ARRAY['Eliminació de la Fricció: L''usuari pot lliscar sobre les superfícies com un patinador sobre gel a gran velocitat —fins i tot descalç— eliminant completament la fricció de la seva pell o de les plantes dels peus.','Transformació Física: Com a efecte secundari, la fruita elimina tot el pes sobrant, les imperfeccions de la pell i els trets aspres, deixant l''usuari amb una pell impecable i tersa i una constitució notablement més esvelta.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '019ffff7-65dc-7563-a4ee-96fe64e3d95d' AND updated_at <= '2026-08-14T11:10:47.874539Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '019ffff7-65dc-7563-a4ee-96fe64e3d95d' AND updated_at <= '2026-08-14T11:10:47.874539Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0007a-6ede-73f7-a7fa-90e767d2c15d', 'en-GB', 'Allows the user to create, control, and transform their body into sand at will.', ARRAY['Intangibility & Form Manipulation: Physical attacks pass harmlessly through Crocodile''s sand form. He can disperse into sandstorms to travel long distances, fly, or dodge incoming strikes by opening holes in his body.','Organic Targets: Touching a person dehydrates them instantly, leaving them as a dried husk (Ground Death).','Environment: Prolonged contact with terrain turns rock, soil, and vegetation into desert sand.','Devastating Sand Attacks: Crocodile can shape sand into razor-sharp blades (Desert Spada), massive quicksand pits, or localized sandstorms that erode everything in their path.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0007a-6ede-73f7-a7fa-90e767d2c15d' AND updated_at <= '2026-08-14T13:33:39.495184Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0007a-6ede-73f7-a7fa-90e767d2c15d' AND updated_at <= '2026-08-14T13:33:39.495184Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0007a-6ede-73f7-a7fa-90e767d2c15d', 'es-ES', 'Permite al usuario crear, controlar y transformar su cuerpo en arena a voluntad.', ARRAY['Intangibilidad y Manipulación de Forma: Los ataques físicos atraviesan inofensivamente la forma de arena de Crocodile. Puede dispersarse en tormentas de arena para viajar largas distancias, volar o esquivar golpes entrantes abriendo huecos en su cuerpo.','Objetivos Orgánicos: Tocar a una persona la deshidrata al instante, dejándola como un pellejo reseco (Ground Death).','Entorno: El contacto prolongado con el terreno convierte roca, tierra y vegetación en arena del desierto.','Ataques de Arena Devastadores: Crocodile puede moldear la arena en cuchillas afiladísimas (Desert Spada), enormes pozos de arenas movedizas o tormentas de arena localizadas que erosionan todo a su paso.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0007a-6ede-73f7-a7fa-90e767d2c15d' AND updated_at <= '2026-08-14T13:33:39.495184Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0007a-6ede-73f7-a7fa-90e767d2c15d' AND updated_at <= '2026-08-14T13:33:39.495184Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0007a-6ede-73f7-a7fa-90e767d2c15d', 'ca-ES', 'Permet a l''usuari crear, controlar i transformar el seu cos en sorra a voluntat.', ARRAY['Intangibilitat i Manipulació de Forma: Els atacs físics travessen inofensivament la forma de sorra de Crocodile. Pot dispersar-se en tempestes de sorra per viatjar llargues distàncies, volar o esquivar cops entrants obrint forats en el seu cos.','Objectius Orgànics: Tocar una persona la deshidrata a l''instant, deixant-la com una pell resseca (Ground Death).','Entorn: El contacte prolongat amb el terreny converteix roca, terra i vegetació en sorra de desert.','Atacs de Sorra Devastadors: Crocodile pot modelar la sorra en fulles esmoladíssimes (Desert Spada), enormes pous de sorres movedisses o tempestes de sorra localitzades que erosionen tot al seu pas.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0007a-6ede-73f7-a7fa-90e767d2c15d' AND updated_at <= '2026-08-14T13:33:39.495184Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0007a-6ede-73f7-a7fa-90e767d2c15d' AND updated_at <= '2026-08-14T13:33:39.495184Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0000c-7d10-7a52-9c7f-61e82b187dfa', 'en-GB', 'Grants the user the power to transform any part of their body into sharp, razor-edged steel blades, as well as making their entire body as hard as steel.', ARRAY['Steel-Hard Durability: The user''s body gains the natural hardness of solid steel, making them virtually immune to standard physical attacks, bullets, and normal bladed weapons.','Bladed Body Parts: The user can turn fingers, forearms, legs, torso, or feet into razor-sharp swords or rotating, chainsaw-like blades (Spider or Sparkling Daisy).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0000c-7d10-7a52-9c7f-61e82b187dfa' AND updated_at <= '2026-08-14T11:33:34.115332Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0000c-7d10-7a52-9c7f-61e82b187dfa' AND updated_at <= '2026-08-14T11:33:34.115332Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0000c-7d10-7a52-9c7f-61e82b187dfa', 'es-ES', 'Otorga al usuario el poder de transformar cualquier parte de su cuerpo en cuchillas de acero afiladas como navajas, además de volver todo su cuerpo tan duro como el acero.', ARRAY['Dureza de Acero: El cuerpo del usuario adquiere la dureza natural del acero macizo, haciéndolo prácticamente inmune a los ataques físicos estándar, las balas y las armas blancas normales.','Partes del Cuerpo Cortantes: El usuario puede convertir dedos, antebrazos, piernas, torso o pies en espadas afiladísimas o en cuchillas giratorias tipo motosierra (Spider o Sparkling Daisy).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0000c-7d10-7a52-9c7f-61e82b187dfa' AND updated_at <= '2026-08-14T11:33:34.115332Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0000c-7d10-7a52-9c7f-61e82b187dfa' AND updated_at <= '2026-08-14T11:33:34.115332Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0000c-7d10-7a52-9c7f-61e82b187dfa', 'ca-ES', 'Atorga a l''usuari el poder de transformar qualsevol part del seu cos en fulles d''acer esmolades com navalles, a més de fer que tot el seu cos sigui tan dur com l''acer.', ARRAY['Duresa d''Acer: El cos de l''usuari adquireix la duresa natural de l''acer massís, fent-lo pràcticament immune als atacs físics estàndard, les bales i les armes blanques normals.','Parts del Cos Tallants: L''usuari pot convertir dits, avantbraços, cames, tors o peus en espases esmoladíssimes o en fulles giratòries tipus motoserra (Spider o Sparkling Daisy).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0000c-7d10-7a52-9c7f-61e82b187dfa' AND updated_at <= '2026-08-14T11:33:34.115332Z'::timestamptz)
