INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0009a-273f-712e-b661-0989a5bfcb15', 'en-GB', 'Allows the user to create, control, and transform their body into dark soot and ash particles at will.', ARRAY['Soot Construct Generation (Crow Swarms): Karasu''s signature application of the fruit is shaping his soot into massive, sentient-like swarms of black crows.','Reconnaissance & Communication: The soot crows can carry messages, transport allies on their backs, or disarm enemies across large battlefields simultaneously.','Combat Swarms: The crows can attack in massive, sharp clusters, stripping weapons from enemy soldiers or peck-slashing opponents.','Suffocation & Blinding: Because soot is composed of fine, toxic carbon residue, dispersing thick ash clouds into the air allows Karasu to blind surrounding enemies and suffocate targets by clogging their lungs and respiratory tracts.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0009a-273f-712e-b661-0989a5bfcb15' AND updated_at <= '2026-08-14T14:08:38.572546Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0009a-273f-712e-b661-0989a5bfcb15' AND updated_at <= '2026-08-14T14:08:38.572546Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0009a-273f-712e-b661-0989a5bfcb15', 'es-ES', 'Permite al usuario crear, controlar y transformar su cuerpo en partículas oscuras de hollín y ceniza a voluntad.', ARRAY['Generación de Constructos de Hollín (Enjambres de Cuervos): La aplicación característica de Karasu de esta fruta consiste en dar forma a su hollín en enjambres masivos y casi conscientes de cuervos negros.','Reconocimiento y Comunicación: Los cuervos de hollín pueden transportar mensajes, llevar aliados a hombros o desarmar enemigos simultáneamente por todo un campo de batalla.','Enjambres de Combate: Los cuervos pueden atacar en agrupaciones masivas y afiladas, arrancando armas a los soldados enemigos o acuchillando a picotazos a los oponentes.','Asfixia y Cegamiento: Dado que el hollín está compuesto por finos residuos tóxicos de carbono, dispersar densas nubes de ceniza en el aire permite a Karasu cegar a los enemigos circundantes y asfixiar a los objetivos obstruyéndoles los pulmones y las vías respiratorias.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0009a-273f-712e-b661-0989a5bfcb15' AND updated_at <= '2026-08-14T14:08:38.572546Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0009a-273f-712e-b661-0989a5bfcb15' AND updated_at <= '2026-08-14T14:08:38.572546Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0009a-273f-712e-b661-0989a5bfcb15', 'ca-ES', 'Permet a l''usuari crear, controlar i transformar el seu cos en partícules fosques de sutge i cendra a voluntat.', ARRAY['Generació de Constructes de Sutge (Eixams de Corbs): L''aplicació característica de Karasu d''aquesta fruita consisteix a donar forma al seu sutge en eixams massius i gairebé conscients de corbs negres.','Reconeixement i Comunicació: Els corbs de sutge poden transportar missatges, portar aliats a l''esquena o desarmar enemics simultàniament per tot un camp de batalla.','Eixams de Combat: Els corbs poden atacar en agrupacions massives i esmolades, arrencant armes als soldats enemics o acoltellant a becades els oponents.','Asfíxia i Enlluernament: Com que el sutge està compost per fins residus tòxics de carboni, dispersar núvols densos de cendra a l''aire permet a Karasu encegar els enemics circumdants i asfixiar els objectius obstruint-los els pulmons i les vies respiratòries.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0009a-273f-712e-b661-0989a5bfcb15' AND updated_at <= '2026-08-14T14:08:38.572546Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0009a-273f-712e-b661-0989a5bfcb15' AND updated_at <= '2026-08-14T14:08:38.572546Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000f2-f19c-7051-a8cc-8f98861c21ad', 'en-GB', 'Gives the user an egg-like body composition that allows them to continuously evolve into stronger avian forms every time they suffer fatal or heavy damage in combat.', ARRAY['Viscount Hiyoko (Chick Form): Triggered when Tamago''s egg form is sliced or crushed open. He hatches into a giant chick wielding twin knives, gaining higher speed and combat aggressiveness.','Count Niwatori (Rooster Form): Triggered when Viscount Hiyoko takes fatal damage. He hatches into a powerful rooster-man, granting his peak physical strength, speed, and endurance.','Infinite Resuscitation Loop: If Count Niwatori is eventually defeated, his body reverts back into the base Baron Tamago egg form, resetting the entire cycle and making him practically immortal through battle resurrection.','Stat Escalation: Each progressive form (Egg → Chick → Rooster) grows significantly faster, stronger, and more lethal than the previous state.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000f2-f19c-7051-a8cc-8f98861c21ad' AND updated_at <= '2026-08-14T15:45:17.331782Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000f2-f19c-7051-a8cc-8f98861c21ad' AND updated_at <= '2026-08-14T15:45:17.331782Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000f2-f19c-7051-a8cc-8f98861c21ad', 'es-ES', 'Otorga a quien la consume una composición corporal similar a la de un huevo, que le permite evolucionar de forma continua hacia formas aviares cada vez más fuertes cada vez que sufre daño fatal o grave en combate.', ARRAY['Vizconde Hiyoko (Forma de Polluelo): Se activa cuando la forma de huevo de Tamago es cortada o aplastada. Eclosiona convirtiéndose en un polluelo gigante que empuña dos cuchillos, ganando mayor velocidad y agresividad en combate.','Conde Niwatori (Forma de Gallo): Se activa cuando el Vizconde Hiyoko sufre daño fatal. Eclosiona convirtiéndose en un poderoso hombre-gallo, alcanzando su máxima fuerza física, velocidad y resistencia.','Bucle de Resurrección Infinito: Si el Conde Niwatori es finalmente derrotado, su cuerpo vuelve a la forma base de huevo del Barón Tamago, reiniciando todo el ciclo y volviéndolo prácticamente inmortal gracias a la resurrección en combate.','Escalada de Estadísticas: Cada forma progresiva (Huevo → Polluelo → Gallo) se vuelve considerablemente más rápida, fuerte y letal que el estado anterior.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000f2-f19c-7051-a8cc-8f98861c21ad' AND updated_at <= '2026-08-14T15:45:17.331782Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000f2-f19c-7051-a8cc-8f98861c21ad' AND updated_at <= '2026-08-14T15:45:17.331782Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000f2-f19c-7051-a8cc-8f98861c21ad', 'ca-ES', 'Atorga a qui la consumeix una composició corporal semblant a la d''un ou, que li permet evolucionar de manera contínua cap a formes aviàries cada cop més fortes cada vegada que pateix un dany fatal o greu en combat.', ARRAY['Vescomte Hiyoko (Forma de Pollet): S''activa quan la forma d''ou de Tamago és tallada o esclafada. Eclosiona i es converteix en un pollet gegant que empunya dos ganivets, guanyant més velocitat i agressivitat en combat.','Comte Niwatori (Forma de Gall): S''activa quan el Vescomte Hiyoko rep un dany fatal. Eclosiona i es converteix en un poderós home-gall, assolint la seva màxima força física, velocitat i resistència.','Bucle de Ressurrecció Infinit: Si el Comte Niwatori acaba sent derrotat, el seu cos torna a la forma base d''ou del Baró Tamago, reiniciant tot el cicle i fent-lo pràcticament immortal gràcies a la ressurrecció en combat.','Escalada d''Estadístiques: Cada forma progressiva (Ou → Pollet → Gall) esdevé considerablement més ràpida, forta i letal que l''estat anterior.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000f2-f19c-7051-a8cc-8f98861c21ad' AND updated_at <= '2026-08-14T15:45:17.331782Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000f2-f19c-7051-a8cc-8f98861c21ad' AND updated_at <= '2026-08-14T15:45:17.331782Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000f7-e041-76ed-8b81-e81991c78c6e', 'en-GB', 'Gives the user the power to transform any part of their body into sharp, solid metallic spikes capable of piercing stone, steel, and flesh.', ARRAY['Stabbing & Piercing: Spikes can elongate several feet instantly to impale opponents or trap them against walls (Stinger Finger / Double Stinger).','Wall-Walking & Locomotion: The user can manifest spikes on the soles of her feet or knees to walk up walls, cling to ceilings, or anchor herself during heavy wind and shockwaves.','Muscle Enhancement (Spike Acupuncture): By stabbing her own body with her spikes in specific pressure points, she can perform Spike Acupuncture (Toge Acupuncture). This technique triggers an adrenaline rush that dramatically inflates her muscle mass, giving her superhuman physical strength and enhanced speed.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000f7-e041-76ed-8b81-e81991c78c6e' AND updated_at <= '2026-08-14T15:50:40.545665Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000f7-e041-76ed-8b81-e81991c78c6e' AND updated_at <= '2026-08-14T15:50:40.545665Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000f7-e041-76ed-8b81-e81991c78c6e', 'ca-ES', 'Atorga a qui la consumeix el poder de transformar qualsevol part del seu cos en punxes metàl·liques afilades i sòlides, capaces de perforar pedra, acer i carn.', ARRAY['Apunyalar i Perforar: Les punxes poden allargar-se diversos metres a l''instant per empalar els oponents o atrapar-los contra parets (Dit Fibló / Doble Fibló).','Escalar Parets i Locomoció: La usuària pot fer sorgir punxes a les plantes dels peus o als genolls per caminar per parets, aferrar-se a sostres o ancorar-se durant vents forts i ones expansives.','Potenciació Muscular (Acupuntura de Punxes): Clavant-se les seves pròpies punxes en punts de pressió específics, pot realitzar l''Acupuntura de Punxes (Toge Acupuncture). Aquesta tècnica desencadena una descàrrega d''adrenalina que augmenta dràsticament la seva massa muscular, atorgant-li una força física sobrehumana i una velocitat millorada.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000f7-e041-76ed-8b81-e81991c78c6e' AND updated_at <= '2026-08-14T15:50:40.545665Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000f7-e041-76ed-8b81-e81991c78c6e' AND updated_at <= '2026-08-14T15:50:40.545665Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000f7-e041-76ed-8b81-e81991c78c6e', 'es-ES', 'Otorga a quien la consume el poder de transformar cualquier parte de su cuerpo en púas metálicas afiladas y sólidas, capaces de perforar piedra, acero y carne.', ARRAY['Apuñalar y Perforar: Las púas pueden alargarse varios metros al instante para empalar a los oponentes o atraparlos contra paredes (Dedo Aguijón / Doble Aguijón).','Escalar Paredes y Locomoción: La usuaria puede hacer surgir púas en las plantas de los pies o en las rodillas para caminar por paredes, aferrarse a techos o anclarse durante fuertes vientos y ondas expansivas.','Potenciación Muscular (Acupuntura de Púas): Clavándose sus propias púas en puntos de presión específicos, puede realizar la Acupuntura de Púas (Toge Acupuncture). Esta técnica desencadena una descarga de adrenalina que aumenta drásticamente su masa muscular, otorgándole una fuerza física sobrehumana y una velocidad mejorada.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000f7-e041-76ed-8b81-e81991c78c6e' AND updated_at <= '2026-08-14T15:50:40.545665Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000f7-e041-76ed-8b81-e81991c78c6e' AND updated_at <= '2026-08-14T15:50:40.545665Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000a4-14e7-7ac1-9b8f-533441807513', 'en-GB', 'Allows the user to transform into a falcon hybrid or a full falcon at will, granting high-speed aerial flight, sharp talons, and enhanced physical attributes.', ARRAY['Hybrid Form: Retains a humanoid body with bird-like features, wings, and sharp talons, enabling wielded weapons (like swords or guns) alongside aerial acrobatics.','Lethal Strikes: The sharp beak and talons can slash through armor or grab heavy objects while airborne.','Aerial Mobility & High-Speed Flight The user can fly at incredible speeds, making it ideal for aerial reconnaissance, rapid transport, and surprise dives.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000a4-14e7-7ac1-9b8f-533441807513' AND updated_at <= '2026-08-14T14:19:08.939052Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000a4-14e7-7ac1-9b8f-533441807513' AND updated_at <= '2026-08-14T14:19:08.939052Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000a4-14e7-7ac1-9b8f-533441807513', 'es-ES', 'Permite a quien la consume transformarse a voluntad en un híbrido de halcón o en un halcón completo, otorgándole vuelo aéreo de alta velocidad, garras afiladas y atributos físicos mejorados.', ARRAY['Forma Híbrida: Conserva un cuerpo humanoide con rasgos de ave, alas y garras afiladas, lo que permite empuñar armas (como espadas o pistolas) junto con acrobacias aéreas.','Golpes Letales: El pico afilado y las garras pueden cortar armaduras o agarrar objetos pesados mientras está en pleno vuelo.','Movilidad Aérea y Vuelo de Alta Velocidad: El usuario puede volar a velocidades increíbles, lo que resulta ideal para el reconocimiento aéreo, el transporte rápido y los descensos sorpresa.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000a4-14e7-7ac1-9b8f-533441807513' AND updated_at <= '2026-08-14T14:19:08.939052Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000a4-14e7-7ac1-9b8f-533441807513' AND updated_at <= '2026-08-14T14:19:08.939052Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000a4-14e7-7ac1-9b8f-533441807513', 'ca-ES', 'Permet a qui la consumeix transformar-se a voluntat en un híbrid de falcó o en un falcó complet, atorgant-li vol aeri d''alta velocitat, urpes afilades i atributs físics millorats.', ARRAY['Forma Híbrida: Conserva un cos humanoide amb trets d''au, ales i urpes afilades, cosa que permet empunyar armes (com espases o pistoles) juntament amb acrobàcies aèries.','Cops Letals: El bec afilat i les urpes poden tallar armadures o agafar objectes pesants mentre és en ple vol.','Mobilitat Aèria i Vol d''Alta Velocitat: L''usuari pot volar a velocitats increïbles, cosa que el fa ideal per al reconeixement aeri, el transport ràpid i els descensos sorpresa.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000a4-14e7-7ac1-9b8f-533441807513' AND updated_at <= '2026-08-14T14:19:08.939052Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000a4-14e7-7ac1-9b8f-533441807513' AND updated_at <= '2026-08-14T14:19:08.939052Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00064-c83c-7b94-ad6f-245135dba0b7', 'en-GB', 'Its main power grants the user the ability to transform into a legendary, blue-flamed Phoenix or a human-phoenix hybrid, combining the stat boosts of a Zoan fruit with the flight and self-regeneration properties of a Mythical creature.', ARRAY['Beast Form (Full Phoenix): Transforms completely into a majestic, towering bird made of brilliant cyan and yellow flames.','Hybrid Form (Human-Phoenix): Transforms limbs (such as turning arms into fiery wings or legs into sharp talons) while retaining a humanoid body for high-speed aerial combat.','Flames of Rebirth (Blue Flames): The fruit generates special blue flames that do not burn or spread like ordinary fire. Instead, these flames possess extraordinary healing and regenerative properties.','Instant Self-Regeneration: Any physical damage the user takes—whether from slashes, bullets, cannonballs, or elemental attacks—is instantly healed by the blue flames as soon as it occurs, making the user nearly immortal in battle','Healing Others (再生の炎 - Saisei no Honō): The user can spread their blue flames onto allies to accelerate their natural healing process, treat injuries, and cure illnesses (though the healing effect on others is less potent than on the user).','Shockwave Deflection (Fuzan no Aza): The dense density of the blue flames can be formed into physical shockwave barriers to block heavy incoming attacks, including elemental blasts from Admirals.','Flight & Aerial Mobility: Grants effortless, high-speed flight in both full bird and hybrid forms, allowing the user to navigate battlefields and transport allies quickly.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00064-c83c-7b94-ad6f-245135dba0b7' AND updated_at <= '2026-08-14T13:10:00.5712Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00064-c83c-7b94-ad6f-245135dba0b7' AND updated_at <= '2026-08-14T13:10:00.5712Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00064-c83c-7b94-ad6f-245135dba0b7', 'es-ES', 'Su poder principal otorga a quien la consume la capacidad de transformarse en un legendario Fénix de llamas azules o en un híbrido humano-fénix, combinando las mejoras de estadísticas propias de una fruta Zoan con las propiedades de vuelo y autorregeneración de una criatura Mítica.', ARRAY['Forma Bestia (Fénix Completo): Se transforma por completo en un ave majestuosa e imponente hecha de brillantes llamas cian y amarillas.','Forma Híbrida (Humano-Fénix): Transforma sus extremidades (convirtiendo los brazos en alas de fuego o las piernas en garras afiladas, por ejemplo) mientras conserva un cuerpo humanoide para el combate aéreo de alta velocidad.','Llamas del Renacimiento (Llamas Azules): La fruta genera unas llamas azules especiales que no queman ni se propagan como el fuego ordinario. En cambio, estas llamas poseen extraordinarias propiedades curativas y regenerativas.','Autorregeneración Instantánea: Cualquier daño físico que sufre el usuario, ya sea por cortes, balas, cañonazos o ataques elementales, es curado al instante por las llamas azules en cuanto se produce, lo que lo vuelve casi inmortal en combate.','Curar a Otros (再生の炎 - Saisei no Honō): El usuario puede extender sus llamas azules sobre sus aliados para acelerar su proceso de curación natural, tratar heridas y curar enfermedades (aunque el efecto curativo en otros es menos potente que en el propio usuario).','Desviación de Ondas Expansivas (Fuzan no Aza): La densidad de las llamas azules puede moldearse en barreras físicas de ondas expansivas para bloquear ataques entrantes muy potentes, incluidas las explosiones elementales de los Almirantes.','Vuelo y Movilidad Aérea: Otorga un vuelo de alta velocidad sin esfuerzo tanto en la forma completa de ave como en la híbrida, permitiendo al usuario desplazarse por los campos de batalla y transportar aliados rápidamente.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00064-c83c-7b94-ad6f-245135dba0b7' AND updated_at <= '2026-08-14T13:10:00.5712Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00064-c83c-7b94-ad6f-245135dba0b7' AND updated_at <= '2026-08-14T13:10:00.5712Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00064-c83c-7b94-ad6f-245135dba0b7', 'ca-ES', 'El seu poder principal atorga a qui la consumeix la capacitat de transformar-se en un llegendari Fènix de flames blaves o en un híbrid humà-fènix, combinant les millores d''estadístiques pròpies d''una fruita Zoan amb les propietats de vol i autoregeneració d''una criatura Mítica.', ARRAY['Forma Bèstia (Fènix Complet): Es transforma completament en una au majestuosa i imponent feta de brillants flames cian i grogues.','Forma Híbrida (Humà-Fènix): Transforma les seves extremitats (convertint els braços en ales de foc o les cames en urpes afilades, per exemple) mentre conserva un cos humanoide per al combat aeri d''alta velocitat.','Flames del Renaixement (Flames Blaves): La fruita genera unes flames blaves especials que no cremen ni es propaguen com el foc ordinari. En canvi, aquestes flames posseeixen extraordinàries propietats curatives i regeneratives.','Autoregeneració Instantània: Qualsevol dany físic que pateix l''usuari, ja sigui per talls, bales, canonades o atacs elementals, és curat a l''instant per les flames blaves tan bon punt es produeix, cosa que el fa gairebé immortal en combat.','Curar Altres (再生の炎 - Saisei no Honō): L''usuari pot estendre les seves flames blaves sobre els seus aliats per accelerar el seu procés de curació natural, tractar ferides i curar malalties (tot i que l''efecte curatiu en altres és menys potent que en el mateix usuari).','Desviació d''Ones Expansives (Fuzan no Aza): La densitat de les flames blaves es pot modelar en barreres físiques d''ones expansives per bloquejar atacs entrants molt potents, incloses les explosions elementals dels Almiralls.','Vol i Mobilitat Aèria: Atorga un vol d''alta velocitat sense esforç tant en la forma completa d''au com en la híbrida, permetent a l''usuari desplaçar-se pels camps de batalla i transportar aliats ràpidament.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00064-c83c-7b94-ad6f-245135dba0b7' AND updated_at <= '2026-08-14T13:10:00.5712Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00064-c83c-7b94-ad6f-245135dba0b7' AND updated_at <= '2026-08-14T13:10:00.5712Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0006b-94ca-74c0-9c26-c70ee9a239b4', 'en-GB', 'The fruit is based on the Eastern myth of the carp swimming up a waterfall to become a dragon. It grants the user the ability to transform into a colossal Azure Dragon or an empowered human-dragon hybrid.', ARRAY['Beast Form (Full Azure Dragon): Transforms into a gigantic, serpentine blue dragon hundreds of meters long, capable of flight and capable of destroying mountain ranges with single attacks.','Hybrid Form (Human-Dragon): Combines the user''s humanoid frame with scales, horns, a tail, and sharp claws—blending immense speed, martial arts mastery, and dragon attributes into the ultimate close-quarters combat state.','Flight via Flame Clouds (Homuradama): The user generates fiery clouds that act as footholds in the sky. By creating massive amounts of these clouds, the user can lift and transport entire landmasses through the air (such as moving the island of Onigashima across the ocean).','Blast Breath (Boro Breath): Fires a massive, concentrated beam of heat and fire from the mouth capable of vaporizing fortresses, mountains, and ancient ruins in seconds.','Lightning & Wind Manipulation: The user can roar to summon lightning bolts or slash their tail/horns to launch razor-sharp wind blades (Kaifu) that slice clean through stone and flesh.','Rising Dragon: Flame Bagua (Shoryu: Kaen Hakke): The fruit''s ultimate offensive state, where the user coats their entire full dragon body in an ultra-dense, sun-hot aura of fire, melting anything that comes near it.','Impenetrable Scales: The dragon''s scales act as biological armor, making the user virtually immune to standard physical attacks, cannon fire, blades, and basic Haki.','Extreme Stat Boosts: As a Mythical Zoan, it grants extraordinary boosts to physical strength, stamina, and passive recovery speed, making the user nearly impossible to defeat in a battle of attrition.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0006b-94ca-74c0-9c26-c70ee9a239b4' AND updated_at <= '2026-08-14T13:17:26.192193Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0006b-94ca-74c0-9c26-c70ee9a239b4' AND updated_at <= '2026-08-14T13:17:26.192193Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0006b-94ca-74c0-9c26-c70ee9a239b4', 'ca-ES', 'La fruita es basa en el mite oriental de la carpa que neda cascada amunt per convertir-se en drac. Atorga a qui la consumeix la capacitat de transformar-se en un colossal Drac Atzur o en un potenciat híbrid humà-drac.', ARRAY['Forma Bèstia (Drac Atzur Complet): Es transforma en un gegantí drac blau d''aspecte serpentí, de centenars de metres de llarg, capaç de volar i de destruir serralades senceres amb un sol atac.','Forma Híbrida (Humà-Drac): Combina la constitució humanoide de l''usuari amb escates, banyes, cua i urpes afilades, fusionant una velocitat immensa, un domini de les arts marcials i atributs dracònics en l''estat definitiu per al combat cos a cos.','Vol mitjançant Núvols de Foc (Homuradama): L''usuari genera núvols ígnis que actuen com a punts de suport al cel. En crear-ne quantitats enormes, pot alçar i transportar per l''aire masses de terra senceres (com moure l''illa d''Onigashima a través de l''oceà).','Alè Explosiu (Boro Breath): Dispara per la boca un enorme raig concentrat de calor i foc capaç de vaporitzar fortaleses, muntanyes i ruïnes antigues en qüestió de segons.','Manipulació de Llamp i Vent: L''usuari pot rugir per invocar llamps o donar un cop de fuet amb la cua o les banyes per llançar fulles de vent afiladíssimes (Kaifu) que tallen netament la pedra i la carn.','Drac Ascendent: Bagua Flamejant (Shoryu: Kaen Hakke): L''estat ofensiu definitiu de la fruita, en què l''usuari cobreix tot el seu cos de drac complet amb una aura de foc ultradensa i tan calenta com el sol, fonent tot allò que s''hi acosta.','Escates Impenetrables: Les escates del drac actuen com una armadura biològica, fent l''usuari pràcticament immune als atacs físics convencionals, al foc de canó, a les fulles i al Haki bàsic.','Millores Extremes d''Estadístiques: En ser una Zoan Mítica, atorga extraordinàries millores a la força física, la resistència i la velocitat de recuperació passiva, fent que l''usuari sigui gairebé impossible de derrotar en una batalla de desgast.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0006b-94ca-74c0-9c26-c70ee9a239b4' AND updated_at <= '2026-08-14T13:17:26.192193Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0006b-94ca-74c0-9c26-c70ee9a239b4' AND updated_at <= '2026-08-14T13:17:26.192193Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0006b-94ca-74c0-9c26-c70ee9a239b4', 'es-ES', 'La fruta se basa en el mito oriental de la carpa que nada río arriba por una cascada para convertirse en dragón. Otorga a quien la consume la capacidad de transformarse en un colosal Dragón Azur o en un potenciado híbrido humano-dragón.', ARRAY['Forma Bestia (Dragón Azur Completo): Se transforma en un gigantesco dragón azul de aspecto serpentino, de cientos de metros de largo, capaz de volar y de destruir cordilleras enteras con un solo ataque.','Forma Híbrida (Humano-Dragón): Combina la constitución humanoide del usuario con escamas, cuernos, cola y garras afiladas, fusionando una velocidad inmensa, un dominio de las artes marciales y atributos dracónicos en el estado definitivo para el combate cuerpo a cuerpo.','Vuelo mediante Nubes de Fuego (Homuradama): El usuario genera nubes ígneas que actúan como puntos de apoyo en el cielo. Al crear enormes cantidades de estas nubes, puede levantar y transportar por el aire masas de tierra enteras (como mover la isla de Onigashima a través del océano).','Aliento Explosivo (Boro Breath): Dispara por la boca un enorme rayo concentrado de calor y fuego capaz de vaporizar fortalezas, montañas y ruinas antiguas en cuestión de segundos.','Manipulación de Rayo y Viento: El usuario puede rugir para invocar rayos o dar un latigazo con su cola o cuernos para lanzar cuchillas de viento afiladísimas (Kaifu) que cortan limpiamente la piedra y la carne.','Dragón Ascendente: Bagua Llameante (Shoryu: Kaen Hakke): El estado ofensivo definitivo de la fruta, en el que el usuario cubre todo su cuerpo de dragón completo con un aura de fuego ultradensa y tan caliente como el sol, derritiendo todo lo que se le acerca.','Escamas Impenetrables: Las escamas del dragón actúan como una armadura biológica, haciendo al usuario prácticamente inmune a los ataques físicos convencionales, al fuego de cañón, a las cuchillas y al Haki básico.','Mejoras Extremas de Estadísticas: Al ser una Zoan Mítica, otorga extraordinarias mejoras a la fuerza física, la resistencia y la velocidad de recuperación pasiva, haciendo que el usuario sea casi imposible de derrotar en una batalla de desgaste.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0006b-94ca-74c0-9c26-c70ee9a239b4' AND updated_at <= '2026-08-14T13:17:26.192193Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0006b-94ca-74c0-9c26-c70ee9a239b4' AND updated_at <= '2026-08-14T13:17:26.192193Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0003b-83e9-71cf-b6fb-e199d57245ab', 'en-GB', 'Its main power allows the user to transform into a bison or a human-bison hybrid, granting substantial boosts to raw physical power, durability, speed, and endurance.', ARRAY['Beast Form (Full Bison): Transforms the user entirely into a massive, four-legged bison with thick fur and sharp horns, ideal for high-speed charging and trampling groups of enemies.','Hybrid Form (Human-Beast): Combines human stature with bison physical traits, creating a hulking, bipedal beast with hooves, a bovine head, horns, and heavily muscled upper body mass.','Enhanced Physicality: As a Zoan-type fruit, it significantly amplifies physical attributes—granting immense brute strength to overwhelm opponents, thick hide to absorb physical blunt force, and enhanced stamina for prolonged combat.','High-Speed Charging Attacks (Fiddle Banjo): In hybrid or full beast form, the user can sprint at incredible speeds toward a target, using the momentum and hard horns to impale or shatter enemy formations.','Cold Resistance: The thick fur layer granted by the bison transformation naturally protects the user from extreme freezing conditions, making it exceptionally effective in winter environments like Drum Island.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0003b-83e9-71cf-b6fb-e199d57245ab' AND updated_at <= '2026-08-14T12:24:56.20284Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0003b-83e9-71cf-b6fb-e199d57245ab' AND updated_at <= '2026-08-14T12:24:56.20284Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0003b-83e9-71cf-b6fb-e199d57245ab', 'es-ES', 'Su poder principal permite a quien la consume transformarse en un bisonte o en un híbrido humano-bisonte, otorgando notables mejoras a la fuerza física bruta, la durabilidad, la velocidad y la resistencia.', ARRAY['Forma Bestia (Bisonte Completo): Transforma por completo al usuario en un enorme bisonte cuadrúpedo de pelaje grueso y cuernos afilados, ideal para embestidas a gran velocidad y para arrollar grupos de enemigos.','Forma Híbrida (Humano-Bestia): Combina la estatura humana con los rasgos físicos del bisonte, creando una bestia bípeda corpulenta con pezuñas, cabeza bovina, cuernos y una musculatura superior extremadamente desarrollada.','Físico Potenciado: Al ser una fruta de tipo Zoan, amplifica notablemente los atributos físicos, otorgando una fuerza bruta inmensa para abrumar a los oponentes, una piel gruesa que absorbe los impactos contundentes y una resistencia mejorada para el combate prolongado.','Ataques de Embestida a Alta Velocidad (Fiddle Banjo): En forma híbrida o de bestia completa, el usuario puede lanzarse a velocidades increíbles hacia un objetivo, usando el impulso y sus duros cuernos para empalar o destrozar formaciones enemigas.','Resistencia al Frío: La gruesa capa de pelaje que otorga la transformación en bisonte protege de forma natural al usuario de condiciones de frío extremo, resultando excepcionalmente eficaz en entornos invernales como la Isla Drum.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0003b-83e9-71cf-b6fb-e199d57245ab' AND updated_at <= '2026-08-14T12:24:56.20284Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0003b-83e9-71cf-b6fb-e199d57245ab' AND updated_at <= '2026-08-14T12:24:56.20284Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a0003b-83e9-71cf-b6fb-e199d57245ab', 'ca-ES', 'El seu poder principal permet a qui la consumeix transformar-se en un bisó o en un híbrid humà-bisó, atorgant notables millores a la força física bruta, la durabilitat, la velocitat i la resistència.', ARRAY['Forma Bèstia (Bisó Complet): Transforma completament l''usuari en un enorme bisó quadrúpede de pèl gruixut i banyes afilades, ideal per a envestides a gran velocitat i per esclafar grups d''enemics.','Forma Híbrida (Humà-Bèstia): Combina l''estatura humana amb els trets físics del bisó, creant una bèstia bípede corpulenta amb peülles, cap boví, banyes i una musculatura superior extremadament desenvolupada.','Físic Potenciat: En ser una fruita de tipus Zoan, amplifica notablement els atributs físics, atorgant una força bruta immensa per aclaparar els oponents, una pell gruixuda que absorbeix els impactes contundents i una resistència millorada per al combat prolongat.','Atacs d''Envestida a Alta Velocitat (Fiddle Banjo): En forma híbrida o de bèstia completa, l''usuari pot llançar-se a velocitats increïbles cap a un objectiu, fent servir l''impuls i les seves dures banyes per empalar o destrossar formacions enemigues.','Resistència al Fred: La gruixuda capa de pèl que atorga la transformació en bisó protegeix de manera natural l''usuari de condicions de fred extrem, cosa que la fa excepcionalment eficaç en entorns hivernals com l''Illa Drum.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a0003b-83e9-71cf-b6fb-e199d57245ab' AND updated_at <= '2026-08-14T12:24:56.20284Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a0003b-83e9-71cf-b6fb-e199d57245ab' AND updated_at <= '2026-08-14T12:24:56.20284Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00062-d2fa-700d-b16e-1d5a652d3ac7', 'en-GB', 'Its main power grants the user the ability to transform into a full giraffe or a human-giraffe hybrid, providing dramatic boosts to physical reach, leverage, raw physical power, and durability.', ARRAY['Beast Form (Full Giraffe): Transforms the user completely into a massive, four-legged giraffe with a long neck and long legs.','Hybrid Form (Human-Beast): Combines human stature with giraffe traits, creating a tall, blocky, square-shaped bipedal creature with a long square neck, hoofed feet, and long limbs.','Immense Reach & Mechanical Leverage: The long neck and extended limbs provide extraordinary range for close-quarters combat and sweeping area-of-effect strikes.','Neck Retraction & Piston Compression (Kama Kirin): By retracting their long neck into their torso using muscle control, the user can fire their head outward like a high-velocity steel piston or spear.','Streamlined Awakened Hybrid: Upon awakening, the user retains full control of their mind while transforming into a sleeker, darker hybrid form enveloped by a floating black flame/cloud sash (hagoromo).','Nose Pistol (Bigan): By infusing Busoshoku Haki into their hardened, square-shaped giraffe nose, the user turns their long neck into a heavy piercing battering ram.','Massive Slicing Centrifugal Force (Kiri Shigure & Amanedachi): By spinning their long neck and body at extreme speeds, the user can fire a 360-degree circular air-blade capable of slicing clean through massive stone towers and fortresses.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00062-d2fa-700d-b16e-1d5a652d3ac7' AND updated_at <= '2026-08-14T13:07:52.282532Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00062-d2fa-700d-b16e-1d5a652d3ac7' AND updated_at <= '2026-08-14T13:07:52.282532Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00062-d2fa-700d-b16e-1d5a652d3ac7', 'es-ES', 'Su poder principal otorga a quien la consume la capacidad de transformarse en una jirafa completa o en un híbrido humano-jirafa, proporcionando notables mejoras al alcance físico, la palanca mecánica, la fuerza física bruta y la durabilidad.', ARRAY['Forma Bestia (Jirafa Completa): Transforma por completo al usuario en una enorme jirafa cuadrúpeda de cuello largo y patas largas.','Forma Híbrida (Humano-Bestia): Combina la estatura humana con los rasgos de la jirafa, creando una criatura bípeda alta, robusta y de forma angular, con un largo cuello cuadrado, pies con pezuñas y extremidades alargadas.','Alcance Inmenso y Palanca Mecánica: El largo cuello y las extremidades extendidas proporcionan un alcance extraordinario para el combate cercano y para golpes de área envolventes.','Retracción de Cuello y Compresión de Pistón (Kama Kirin): Al retraer su largo cuello hacia el torso mediante el control muscular, el usuario puede disparar su cabeza hacia afuera como un pistón de acero o una lanza de alta velocidad.','Híbrido Despertado Aerodinámico: Tras el despertar, el usuario conserva el control total de su mente mientras se transforma en una forma híbrida más esbelta y oscura, envuelta por una faja flotante de llamas o nubes negras (hagoromo).','Pistola de Nariz (Bigan): Al infundir Busoshoku Haki en su endurecida y angulosa nariz de jirafa, el usuario convierte su largo cuello en un pesado ariete perforante.','Fuerza Centrífuga Cortante Masiva (Kiri Shigure y Amanedachi): Al girar su largo cuello y su cuerpo a velocidades extremas, el usuario puede lanzar una cuchilla de aire circular de 360 grados capaz de cortar limpiamente enormes torres y fortalezas de piedra.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00062-d2fa-700d-b16e-1d5a652d3ac7' AND updated_at <= '2026-08-14T13:07:52.282532Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00062-d2fa-700d-b16e-1d5a652d3ac7' AND updated_at <= '2026-08-14T13:07:52.282532Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00062-d2fa-700d-b16e-1d5a652d3ac7', 'ca-ES', 'El seu poder principal atorga a qui la consumeix la capacitat de transformar-se en una girafa completa o en un híbrid humà-girafa, proporcionant notables millores a l''abast físic, la palanca mecànica, la força física bruta i la durabilitat.', ARRAY['Forma Bèstia (Girafa Completa): Transforma completament l''usuari en una enorme girafa quadrúpede de coll llarg i potes llargues.','Forma Híbrida (Humà-Bèstia): Combina l''estatura humana amb els trets de la girafa, creant una criatura bípede alta, robusta i de forma angular, amb un coll llarg i quadrat, peus amb peülles i extremitats allargades.','Abast Immens i Palanca Mecànica: El coll llarg i les extremitats esteses proporcionen un abast extraordinari per al combat cos a cos i per a cops d''àrea envoltants.','Retracció de Coll i Compressió de Pistó (Kama Kirin): En retreure el seu llarg coll cap al tors mitjançant el control muscular, l''usuari pot disparar el seu cap cap enfora com un pistó d''acer o una llança d''alta velocitat.','Híbrid Despertat Aerodinàmic: Després del despertar, l''usuari conserva el control total de la seva ment mentre es transforma en una forma híbrida més esvelta i fosca, embolcallada per una faixa flotant de flames o núvols negres (hagoromo).','Pistola de Nas (Bigan): En infondre Busoshoku Haki al seu endurit i angulós nas de girafa, l''usuari converteix el seu llarg coll en un pesat ariet perforant.','Força Centrífuga Tallant Massiva (Kiri Shigure i Amanedachi): En fer girar el seu llarg coll i el seu cos a velocitats extremes, l''usuari pot llançar una fulla d''aire circular de 360 graus capaç de tallar netament enormes torres i fortaleses de pedra.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00062-d2fa-700d-b16e-1d5a652d3ac7' AND updated_at <= '2026-08-14T13:07:52.282532Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00062-d2fa-700d-b16e-1d5a652d3ac7' AND updated_at <= '2026-08-14T13:07:52.282532Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00031-c0b1-788b-b419-e2df38d6beb7', 'en-GB', 'Its main power grants the user the ability to transport the consciousness of anyone who hears them sing into a virtual reality dimension known as Uta World.', ARRAY['Uta World (Virtual Dimension): When people hear the user''s singing, their minds are pulled into an alternate reality controlled completely by the user, while their real-world physical bodies fall into a deep sleep.','Reality Warping in Uta World: Inside Uta World, the user possesses near-godlike omnipotence. They can bend reality to their will—manifesting giant weapons, changing clothing, generating food, spawning floating musical notes as attacks, and controlling the landscape effortlessly.','Body Manipulation in the Real World: The user can control the sleeping physical bodies of their victims in the real world like puppets, forcing them to attack or move according to the user''s wishes.','Summoning Totamusica: By singing a specific ancient score, the user can summon Totamusica, a colossal demon entity that exists simultaneously in both the real world and Uta World, requiring coordinated attacks across both dimensions to defeat.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00031-c0b1-788b-b419-e2df38d6beb7' AND updated_at <= '2026-08-14T12:15:15.095703Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00031-c0b1-788b-b419-e2df38d6beb7' AND updated_at <= '2026-08-14T12:15:15.095703Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00031-c0b1-788b-b419-e2df38d6beb7', 'ca-ES', 'El seu poder principal atorga a qui la consumeix la capacitat de transportar la consciència de qualsevol que la senti cantar a una dimensió de realitat virtual coneguda com a Uta World.', ARRAY['Uta World (Dimensió Virtual): Quan la gent sent el cant de l''usuari, les seves ments són arrossegades a una realitat alternativa controlada completament per l''usuari, mentre els seus cossos físics en el món real cauen en un son profund.','Distorsió de la Realitat a Uta World: Dins d''Uta World, l''usuari posseeix una omnipotència gairebé divina. Pot doblegar la realitat al seu gust: manifestar armes gegants, canviar de roba, generar menjar, fer aparèixer notes musicals flotants com a atacs i controlar el paisatge sense esforç.','Manipulació Corporal al Món Real: L''usuari pot controlar com a titelles els cossos físics adormits de les seves víctimes al món real, obligant-los a atacar o moure''s segons la seva voluntat.','Invocar Totamusica: En cantar una partitura antiga específica, l''usuari pot invocar Totamusica, una colossal entitat demoníaca que existeix simultàniament tant al món real com a Uta World, i que requereix atacs coordinats en ambdues dimensions per ser derrotada.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00031-c0b1-788b-b419-e2df38d6beb7' AND updated_at <= '2026-08-14T12:15:15.095703Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00031-c0b1-788b-b419-e2df38d6beb7' AND updated_at <= '2026-08-14T12:15:15.095703Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00031-c0b1-788b-b419-e2df38d6beb7', 'es-ES', 'Su poder principal otorga a quien la consume la capacidad de transportar la conciencia de cualquiera que la escuche cantar a una dimensión de realidad virtual conocida como Uta World.', ARRAY['Uta World (Dimensión Virtual): Cuando la gente escucha el canto del usuario, sus mentes son arrastradas a una realidad alternativa controlada completamente por el usuario, mientras sus cuerpos físicos en el mundo real caen en un sueño profundo.','Distorsión de la Realidad en Uta World: Dentro de Uta World, el usuario posee una omnipotencia casi divina. Puede doblegar la realidad a su voluntad: manifestar armas gigantes, cambiar de ropa, generar comida, hacer aparecer notas musicales flotantes como ataques y controlar el paisaje sin esfuerzo.','Manipulación Corporal en el Mundo Real: El usuario puede controlar como marionetas los cuerpos físicos dormidos de sus víctimas en el mundo real, obligándolos a atacar o moverse según su voluntad.','Invocar a Totamusica: Al cantar una partitura antigua específica, el usuario puede invocar a Totamusica, una colosal entidad demoníaca que existe simultáneamente tanto en el mundo real como en Uta World, y que requiere ataques coordinados en ambas dimensiones para ser derrotada.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00031-c0b1-788b-b419-e2df38d6beb7' AND updated_at <= '2026-08-14T12:15:15.095703Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00031-c0b1-788b-b419-e2df38d6beb7' AND updated_at <= '2026-08-14T12:15:15.095703Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00080-b80a-77fa-b3ed-f985e44238c3', 'en-GB', 'Allows the user to create, control, and transform into darkness, which functions like a black hole with infinite gravitational pull.', ARRAY['Devil Fruit Power Nullification: The fruit''s most dangerous ability: by establishing physical contact with another Devil Fruit user, Blackbeard completely nullifies their abilities. Unlike Haki (which allows striking the real body), the Yami Yami no Mi actively shuts off the target''s powers as long as contact is maintained—forcing Logia, Paramecia, and Zoan users to fight as normal humans.','Infiltration & Crush: Blackbeard can spread darkness across the ground, swallowing entire towns or armies into an infinite void (Black Hole).','Crush & Eject: Anything swallowed by the darkness can be crushed by intense gravitational forces and ejected at high speed (Liberation).','Attraction: The user can pull targets directly into his hand from a distance (Kurouzu / Black Spiral).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00080-b80a-77fa-b3ed-f985e44238c3' AND updated_at <= '2026-08-14T13:40:31.423319Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00080-b80a-77fa-b3ed-f985e44238c3' AND updated_at <= '2026-08-14T13:40:31.423319Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00080-b80a-77fa-b3ed-f985e44238c3', 'es-ES', 'Permite a quien la consume crear, controlar y transformarse en oscuridad, la cual funciona como un agujero negro con una fuerza gravitatoria infinita.', ARRAY['Anulación de Poderes de Fruta del Diablo: La habilidad más peligrosa de la fruta: al establecer contacto físico con otro usuario de una Fruta del Diablo, Barbanegra anula por completo sus habilidades. A diferencia del Haki (que permite golpear el cuerpo real), la Yami Yami no Mi desactiva activamente los poderes del objetivo mientras se mantenga el contacto, obligando a usuarios Logia, Paramecia y Zoan a luchar como humanos normales.','Infiltración y Aplastamiento: Barbanegra puede extender la oscuridad por el suelo, engullendo ciudades enteras o ejércitos en un vacío infinito (Agujero Negro).','Aplastar y Expulsar: Cualquier cosa engullida por la oscuridad puede ser aplastada por intensas fuerzas gravitatorias y expulsada a gran velocidad (Liberación).','Atracción: El usuario puede atraer objetivos directamente hacia su mano a distancia (Kurouzu / Espiral Negra).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00080-b80a-77fa-b3ed-f985e44238c3' AND updated_at <= '2026-08-14T13:40:31.423319Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00080-b80a-77fa-b3ed-f985e44238c3' AND updated_at <= '2026-08-14T13:40:31.423319Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00080-b80a-77fa-b3ed-f985e44238c3', 'ca-ES', 'Permet a qui la consumeix crear, controlar i transformar-se en foscor, la qual funciona com un forat negre amb una força gravitatòria infinita.', ARRAY['Anul·lació de Poders de Fruita del Diable: L''habilitat més perillosa de la fruita: en establir contacte físic amb un altre usuari d''una Fruita del Diable, Barbanegra anul·la completament les seves habilitats. A diferència del Haki (que permet colpejar el cos real), la Yami Yami no Mi desactiva activament els poders de l''objectiu mentre es mantingui el contacte, obligant els usuaris Logia, Paramecia i Zoan a lluitar com a humans normals.','Infiltració i Aixafament: Barbanegra pot estendre la foscor pel terra, engolint ciutats senceres o exèrcits en un buit infinit (Forat Negre).','Aixafar i Expulsar: Qualsevol cosa engolida per la foscor pot ser aixafada per intenses forces gravitatòries i expulsada a gran velocitat (Alliberament).','Atracció: L''usuari pot atreure objectius directament cap a la seva mà a distància (Kurouzu / Espiral Negra).']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00080-b80a-77fa-b3ed-f985e44238c3' AND updated_at <= '2026-08-14T13:40:31.423319Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00080-b80a-77fa-b3ed-f985e44238c3' AND updated_at <= '2026-08-14T13:40:31.423319Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00019-b25c-74b3-ae9b-1fc0d4111a90', 'en-GB', 'Its fundamental power grants the user''s soul a second life, allowing them to return from the underworld after dying their first physical death.', ARRAY['Resurrection: Upon the user''s initial death, the soul travels back from the afterlife to inhabit their body once again. Even if the body has decayed into a skeleton before the soul finds it, the user remains fully alive and functional.','Cold of the Underworld (Chill Soul): The user can channel the freezing chill of the underworld through their soul energy and infuse it into weapons, unleashing powerful ice-based slicing attacks that freeze enemies from the inside out.','Soul Dominance: Because the fruit grants authority over souls, the user can damage, manipulate, or outright destroy artificial souls and soul-constructs (such as Big Mom''s Chess Homies).','Soul Energy & Astral Projection: The user can detach their soul from their body to phase through solid walls, scout areas undetected, and remain completely immune to physical attacks in this spectral form.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00019-b25c-74b3-ae9b-1fc0d4111a90' AND updated_at <= '2026-08-14T11:48:08.276304Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00019-b25c-74b3-ae9b-1fc0d4111a90' AND updated_at <= '2026-08-14T11:48:08.276304Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00019-b25c-74b3-ae9b-1fc0d4111a90', 'es-ES', 'Su poder fundamental otorga al alma de quien la consume una segunda vida, permitiéndole regresar del inframundo tras sufrir su primera muerte física.', ARRAY['Resurrección: Tras la muerte inicial del usuario, su alma regresa desde el más allá para habitar de nuevo su cuerpo. Incluso si el cuerpo se ha descompuesto hasta quedar reducido a un esqueleto antes de que el alma lo encuentre, el usuario permanece completamente vivo y funcional.','Frío del Inframundo (Chill Soul): El usuario puede canalizar el frío glacial del inframundo a través de la energía de su alma e infundirlo en armas, desatando poderosos ataques cortantes de hielo que congelan a los enemigos de dentro hacia afuera.','Dominio de las Almas: Como la fruta otorga autoridad sobre las almas, el usuario puede dañar, manipular o directamente destruir almas artificiales y constructos de alma (como los Chess Homies de Big Mom).','Energía del Alma y Proyección Astral: El usuario puede separar su alma de su cuerpo para atravesar paredes sólidas, explorar zonas sin ser detectado y permanecer completamente inmune a los ataques físicos en esta forma espectral.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00019-b25c-74b3-ae9b-1fc0d4111a90' AND updated_at <= '2026-08-14T11:48:08.276304Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00019-b25c-74b3-ae9b-1fc0d4111a90' AND updated_at <= '2026-08-14T11:48:08.276304Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00019-b25c-74b3-ae9b-1fc0d4111a90', 'ca-ES', 'El seu poder fonamental atorga a l''ànima de qui la consumeix una segona vida, permetent-li tornar de l''inframón després de patir la seva primera mort física.', ARRAY['Ressurrecció: Després de la mort inicial de l''usuari, la seva ànima torna des de l''altra vida per habitar de nou el seu cos. Fins i tot si el cos s''ha descompost fins a quedar reduït a un esquelet abans que l''ànima el trobi, l''usuari roman completament viu i funcional.','Fred de l''Inframón (Chill Soul): L''usuari pot canalitzar el fred glacial de l''inframón a través de l''energia de la seva ànima i infondre''l en armes, desfermant poderosos atacs tallants de gel que congelen els enemics de dins cap enfora.','Domini de les Ànimes: Com que la fruita atorga autoritat sobre les ànimes, l''usuari pot danyar, manipular o destruir directament ànimes artificials i constructes d''ànima (com els Chess Homies de Big Mom).','Energia de l''Ànima i Projecció Astral: L''usuari pot separar la seva ànima del seu cos per travessar parets sòlides, explorar zones sense ser detectat i romandre completament immune als atacs físics en aquesta forma espectral.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00019-b25c-74b3-ae9b-1fc0d4111a90' AND updated_at <= '2026-08-14T11:48:08.276304Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00019-b25c-74b3-ae9b-1fc0d4111a90' AND updated_at <= '2026-08-14T11:48:08.276304Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00095-e7c6-7f3c-b28a-7e966a6d4b2b', 'en-GB', 'Allows the user to create, control, and transform their body into snow at will.', ARRAY['Snow Defense & Barriers: Monet can construct thick, solid walls of hardened snow (Kamakura) capable of withstanding heavy physical blows.','Intangibility: Incoming non-Haki attacks pass harmlessly through her powdery snow form, allowing her to reform her body at will.','Hypothermia & Sleep Induction: By surrounding targets in dense snowstorms (Yuki Rabi), the user lowers the surrounding air temperature. The extreme cold lulls victims into a deep freeze, causing paralysis, severe hypothermia, and eventual death as their body temperature drops.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00095-e7c6-7f3c-b28a-7e966a6d4b2b' AND updated_at <= '2026-08-14T14:03:40.150791Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00095-e7c6-7f3c-b28a-7e966a6d4b2b' AND updated_at <= '2026-08-14T14:03:40.150791Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00095-e7c6-7f3c-b28a-7e966a6d4b2b', 'es-ES', 'Permite a quien la consume crear, controlar y transformar su cuerpo en nieve a voluntad.', ARRAY['Defensa y Barreras de Nieve: Monet puede construir gruesos muros sólidos de nieve endurecida (Kamakura) capaces de resistir golpes físicos contundentes.','Intangibilidad: Los ataques entrantes que no usan Haki atraviesan sin causar daño su forma de nieve pulverulenta, permitiéndole recomponer su cuerpo a voluntad.','Hipotermia e Inducción del Sueño: Al rodear a sus objetivos con densas tormentas de nieve (Yuki Rabi), el usuario reduce la temperatura del aire circundante. El frío extremo sume a las víctimas en una congelación profunda, causando parálisis, hipotermia grave y, finalmente, la muerte a medida que desciende su temperatura corporal.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00095-e7c6-7f3c-b28a-7e966a6d4b2b' AND updated_at <= '2026-08-14T14:03:40.150791Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00095-e7c6-7f3c-b28a-7e966a6d4b2b' AND updated_at <= '2026-08-14T14:03:40.150791Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a00095-e7c6-7f3c-b28a-7e966a6d4b2b', 'ca-ES', 'Permet a qui la consumeix crear, controlar i transformar el seu cos en neu a voluntat.', ARRAY['Defensa i Barreres de Neu: Monet pot construir gruixuts murs sòlids de neu endurida (Kamakura) capaços de resistir cops físics contundents.','Intangibilitat: Els atacs entrants que no fan servir Haki travessen sense causar dany la seva forma de neu polvoritzada, permetent-li recompondre el seu cos a voluntat.','Hipotèrmia i Inducció del Son: En envoltar els seus objectius amb denses tempestes de neu (Yuki Rabi), l''usuari redueix la temperatura de l''aire circumdant. El fred extrem submergeix les víctimes en una congelació profunda, causant paràlisi, hipotèrmia greu i, finalment, la mort a mesura que baixa la seva temperatura corporal.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a00095-e7c6-7f3c-b28a-7e966a6d4b2b' AND updated_at <= '2026-08-14T14:03:40.150791Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a00095-e7c6-7f3c-b28a-7e966a6d4b2b' AND updated_at <= '2026-08-14T14:03:40.150791Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000d5-a543-76e0-ade9-d1880dad77f6', 'en-GB', 'Allows the user (or object) to transform into a full elephant or an elephant-hybrid state at will.', ARRAY['Flexible Reach: In its hybrid form, the sword''s blade extends into a giant, razor-sharp elephant trunk. Spandam can swing the sword normally, while the blade flexes, lengthens, and strikes targets from unpredictable angles.','Immense Weight & Trampling Power: In full elephant form, Funkfreed gains the full mass, thick hide, and crushing power of a massive elephant, easily crushing opponents underfoot.','Steel-Reinforced Tusks & Blade: Because the fruit''s base was a high-grade sword, the elephant''s tusks and trunk remain made of razor-sharp steel, allowing for lethal goring and slashing strikes.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000d5-a543-76e0-ade9-d1880dad77f6' AND updated_at <= '2026-08-14T15:13:17.478761Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000d5-a543-76e0-ade9-d1880dad77f6' AND updated_at <= '2026-08-14T15:13:17.478761Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000d5-a543-76e0-ade9-d1880dad77f6', 'es-ES', 'Permite a quien la consume (u objeto que la contenga) transformarse a voluntad en un elefante completo o en un estado híbrido de elefante.', ARRAY['Alcance Flexible: En su forma híbrida, la hoja de la espada se extiende hasta convertirse en una gigantesca trompa de elefante afiladísima. Spandam puede blandir la espada con normalidad, mientras la hoja se flexiona, se alarga y golpea a los objetivos desde ángulos imprevisibles.','Peso Inmenso y Poder de Pisoteo: En su forma de elefante completo, Funkfreed adquiere toda la masa, la gruesa piel y el poder aplastante de un elefante colosal, aplastando fácilmente a sus oponentes bajo sus patas.','Colmillos y Hoja Reforzados de Acero: Como la base de la fruta era una espada de alta calidad, los colmillos y la trompa del elefante siguen hechos de acero afiladísimo, permitiendo letales embestidas y cortes.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000d5-a543-76e0-ade9-d1880dad77f6' AND updated_at <= '2026-08-14T15:13:17.478761Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000d5-a543-76e0-ade9-d1880dad77f6' AND updated_at <= '2026-08-14T15:13:17.478761Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000d5-a543-76e0-ade9-d1880dad77f6', 'ca-ES', 'Permet a qui la consumeix (o objecte que la contingui) transformar-se a voluntat en un elefant complet o en un estat híbrid d''elefant.', ARRAY['Abast Flexible: En la seva forma híbrida, la fulla de l''espasa s''estén fins a convertir-se en una gegantina trompa d''elefant afiladíssima. Spandam pot brandir l''espasa amb normalitat, mentre la fulla es flexiona, s''allarga i colpeja els objectius des d''angles imprevisibles.','Pes Immens i Poder d''Esclafament: En la seva forma d''elefant complet, Funkfreed adquireix tota la massa, la pell gruixuda i el poder aixafador d''un elefant colossal, esclafant fàcilment els seus oponents sota les seves potes.','Ullals i Fulla Reforçats d''Acer: Com que la base de la fruita era una espasa d''alta qualitat, els ullals i la trompa de l''elefant continuen sent d''acer afiladíssim, cosa que permet letals envestides i talls.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000d5-a543-76e0-ade9-d1880dad77f6' AND updated_at <= '2026-08-14T15:13:17.478761Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000d5-a543-76e0-ade9-d1880dad77f6' AND updated_at <= '2026-08-14T15:13:17.478761Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000d8-0cca-7305-91ba-9bbc30306d94', 'en-GB', 'Allows the user to transform into a mammoth hybrid or a full prehistoric mammoth at will, granting overwhelming physical size, destructive power, and extreme durability.', ARRAY['City-Level Trampling: A single swing of the user''s mammoth trunk or a few steps can level entire streets, city buildings, and fortified defenses.','Massive Tusks: Giant, curved prehistoric tusks capable of goring through heavy armor, stone walls, and warships.','Relentless Stamina: Jack fought non-stop for 5 days and 5 nights against the Mink leaders (Inuarashi and Nekomamushi) without taking a break to rest or eat.','Thick Hide: The dense fur and thick skin insulate the user against heavy physical attacks, blade strikes, and environmental extremes.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000d8-0cca-7305-91ba-9bbc30306d94' AND updated_at <= '2026-08-14T15:15:54.989706Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000d8-0cca-7305-91ba-9bbc30306d94' AND updated_at <= '2026-08-14T15:15:54.989706Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000d8-0cca-7305-91ba-9bbc30306d94', 'es-ES', 'Permite a quien la consume transformarse a voluntad en un híbrido de mamut o en un mamut prehistórico completo, otorgando un tamaño físico abrumador, un poder destructivo y una durabilidad extrema.', ARRAY['Pisoteo a Escala de Ciudad: Un solo golpe con la trompa de mamut del usuario, o unos pocos pasos, pueden arrasar calles enteras, edificios urbanos y defensas fortificadas.','Colmillos Masivos: Gigantescos colmillos prehistóricos curvados capaces de perforar armaduras pesadas, muros de piedra y buques de guerra.','Resistencia Implacable: Jack luchó sin parar durante 5 días y 5 noches contra los líderes Mink (Inuarashi y Nekomamushi) sin detenerse ni a descansar ni a comer.','Piel Gruesa: El denso pelaje y la gruesa piel aíslan al usuario frente a ataques físicos pesados, golpes de arma blanca y condiciones ambientales extremas.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000d8-0cca-7305-91ba-9bbc30306d94' AND updated_at <= '2026-08-14T15:15:54.989706Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000d8-0cca-7305-91ba-9bbc30306d94' AND updated_at <= '2026-08-14T15:15:54.989706Z'::timestamptz);
INSERT INTO power_translations (power_id, locale, description, skills)
SELECT '01a000d8-0cca-7305-91ba-9bbc30306d94', 'ca-ES', 'Permet a qui la consumeix transformar-se a voluntat en un híbrid de mamut o en un mamut prehistòric complet, atorgant una mida física aclaparadora, un poder destructiu i una durabilitat extrema.', ARRAY['Esclafament a Escala de Ciutat: Un sol cop amb la trompa de mamut de l''usuari, o uns pocs passos, poden arrasar carrers sencers, edificis urbans i defenses fortificades.','Ullals Massius: Gegantins ullals prehistòrics corbats capaços de perforar armadures pesants, murs de pedra i vaixells de guerra.','Resistència Implacable: Jack va lluitar sense parar durant 5 dies i 5 nits contra els líders Mink (Inuarashi i Nekomamushi) sense aturar-se ni a descansar ni a menjar.','Pell Gruixuda: El dens pèl i la pell gruixuda aïllen l''usuari davant atacs físics pesants, cops d''arma blanca i condicions ambientals extremes.']::text[]
WHERE EXISTS (SELECT 1 FROM powers WHERE id = '01a000d8-0cca-7305-91ba-9bbc30306d94' AND updated_at <= '2026-08-14T15:15:54.989706Z'::timestamptz)
ON CONFLICT (power_id, locale) DO UPDATE
  SET description = EXCLUDED.description, skills = EXCLUDED.skills
  WHERE power_translations.power_id IN (SELECT id FROM powers WHERE id = '01a000d8-0cca-7305-91ba-9bbc30306d94' AND updated_at <= '2026-08-14T15:15:54.989706Z'::timestamptz);
INSERT INTO character_translations (character_id, locale, description)
SELECT '01a09a88-80fe-730b-8bba-875589a70549', 'es-ES', 'Jotaro Kujo es el estoico y formidable protagonista de JoJo''s Bizarre Adventure: Stardust Crusaders. Conocido por su imponente estatura, su característico uniforme escolar con la gorra rasgada y su carácter sereno, posee una inteligencia excepcional en combate. Controla a Star Platinum, un Stand sumamente poderoso famoso por su velocidad devastadora, fuerza sobrehumana, precisión y, con el tiempo, la habilidad de detener brevemente el tiempo.'
WHERE EXISTS (SELECT 1 FROM characters WHERE id = '01a09a88-80fe-730b-8bba-875589a70549' AND updated_at <= '2026-09-13T19:43:31.127162Z'::timestamptz)
ON CONFLICT (character_id, locale) DO UPDATE
  SET description = EXCLUDED.description
  WHERE character_translations.character_id IN (SELECT id FROM characters WHERE id = '01a09a88-80fe-730b-8bba-875589a70549' AND updated_at <= '2026-09-13T19:43:31.127162Z'::timestamptz);
INSERT INTO character_translations (character_id, locale, description)
SELECT '01a09a88-80fe-730b-8bba-875589a70549', 'ca-ES', 'Jotaro Kujo és l''estoic i formidable protagonista de JoJo''s Bizarre Adventure: Stardust Crusaders. Conegut per la seva alçada imponent, el seu característic uniforme escolar amb la gorra esquinçada i un caràcter serè, posseeix una intel·ligència excepcional en combat. Controla Star Platinum, un Stand summament poderós famós per la seva velocitat devastadora, força sobrehumana, precisió i, amb el temps, l''habilitat d''aturar breument el temps.'
WHERE EXISTS (SELECT 1 FROM characters WHERE id = '01a09a88-80fe-730b-8bba-875589a70549' AND updated_at <= '2026-09-13T19:43:31.127162Z'::timestamptz)
ON CONFLICT (character_id, locale) DO UPDATE
  SET description = EXCLUDED.description
  WHERE character_translations.character_id IN (SELECT id FROM characters WHERE id = '01a09a88-80fe-730b-8bba-875589a70549' AND updated_at <= '2026-09-13T19:43:31.127162Z'::timestamptz);
INSERT INTO character_translations (character_id, locale, description)
SELECT '01a09a88-80fe-730b-8bba-875589a70549', 'en-GB', 'Jotaro Kujo is the stoic and formidable protagonist of JoJo''s Bizarre Adventure: Stardust Crusaders. Renowned for his imposing stature, trademark school uniform with a torn cap, and calm demeanor, he possesses exceptional intellect in battle. He wields Star Platinum, an immensely powerful Stand famous for its devastating speed, superhuman strength, precision, and eventually, the ability to briefly stop time.'
WHERE EXISTS (SELECT 1 FROM characters WHERE id = '01a09a88-80fe-730b-8bba-875589a70549' AND updated_at <= '2026-09-13T19:43:31.127162Z'::timestamptz)
ON CONFLICT (character_id, locale) DO UPDATE
  SET description = EXCLUDED.description
  WHERE character_translations.character_id IN (SELECT id FROM characters WHERE id = '01a09a88-80fe-730b-8bba-875589a70549' AND updated_at <= '2026-09-13T19:43:31.127162Z'::timestamptz);
INSERT INTO character_translations (character_id, locale, description)
SELECT '01a09cdb-0fb3-799d-95d1-6e467d318523', 'ca-ES', 'Kars és el brillant i implacable líder dels Homes del Pilar i l''antagonista principal de JoJo''s Bizarre Adventure: Battle Tendency. Mogut per l''obsessió de conquerir el sol i assolir la veritable perfecció biològica, va crear les Màscares de Pedra. Mitjançant la Pedra Vermella d''Aja assoleix la seva major ambició: convertir-se en la Forma de Vida Definitiva, un ésser immortal capaç de replicar i dominar els trets genètics de qualsevol organisme de la Terra.'
WHERE EXISTS (SELECT 1 FROM characters WHERE id = '01a09cdb-0fb3-799d-95d1-6e467d318523' AND updated_at <= '2026-09-13T22:19:59.123251Z'::timestamptz)
ON CONFLICT (character_id, locale) DO UPDATE
  SET description = EXCLUDED.description
  WHERE character_translations.character_id IN (SELECT id FROM characters WHERE id = '01a09cdb-0fb3-799d-95d1-6e467d318523' AND updated_at <= '2026-09-13T22:19:59.123251Z'::timestamptz);
INSERT INTO character_translations (character_id, locale, description)
SELECT '01a09cdb-0fb3-799d-95d1-6e467d318523', 'en-GB', 'Kars is the brilliant, ruthless leader of the Pillar Men and the primary antagonist of JoJo''s Bizarre Adventure: Battle Tendency. Driven by an obsession to conquer the sun and attain true biological perfection, he created the Stone Masks. Through the Red Stone of Aja, he achieves his ultimate ambition, transforming into the Ultimate Lifeform—an immortal being capable of replicating and mastering the genetic traits of any organism on Earth.'
WHERE EXISTS (SELECT 1 FROM characters WHERE id = '01a09cdb-0fb3-799d-95d1-6e467d318523' AND updated_at <= '2026-09-13T22:19:59.123251Z'::timestamptz)
ON CONFLICT (character_id, locale) DO UPDATE
  SET description = EXCLUDED.description
  WHERE character_translations.character_id IN (SELECT id FROM characters WHERE id = '01a09cdb-0fb3-799d-95d1-6e467d318523' AND updated_at <= '2026-09-13T22:19:59.123251Z'::timestamptz);
INSERT INTO character_translations (character_id, locale, description)
SELECT '01a09cdb-0fb3-799d-95d1-6e467d318523', 'es-ES', 'Kars es el brillante e implacable líder de los Hombres del Pilar y el antagonista principal de JoJo''s Bizarre Adventure: Battle Tendency. Movido por la obsesión de conquistar el sol y alcanzar la verdadera perfección biológica, creó las Máscaras de Piedra. Mediante la Piedra Roja de Aja logra su mayor ambición: convertirse en la Forma de Vida Definitiva, un ser inmortal capaz de replicar y dominar los rasgos genéticos de cualquier organismo de la Tierra.'
WHERE EXISTS (SELECT 1 FROM characters WHERE id = '01a09cdb-0fb3-799d-95d1-6e467d318523' AND updated_at <= '2026-09-13T22:19:59.123251Z'::timestamptz)
ON CONFLICT (character_id, locale) DO UPDATE
  SET description = EXCLUDED.description
  WHERE character_translations.character_id IN (SELECT id FROM characters WHERE id = '01a09cdb-0fb3-799d-95d1-6e467d318523' AND updated_at <= '2026-09-13T22:19:59.123251Z'::timestamptz);
INSERT INTO character_translations (character_id, locale, description)
SELECT '01a09c4f-178d-7c1e-99d4-c1bff812630d', 'ca-ES', 'Monkey D. Luffy és l''alegre, despreocupat i ferotgement determinat protagonista de One Piece. Capità dels Pirates del Barret de Palla, el seu somni és trobar el tresor llegendari i convertir-se en el Rei dels Pirates. Després de menjar la Fruita Goma Goma (Gomu Gomu no Mi), el seu cos va adquirir les propietats de la goma, fet que li permet estirar-se i inventar tècniques creatives de combat combinades amb el domini de poderoses formes de Haki.'
WHERE EXISTS (SELECT 1 FROM characters WHERE id = '01a09c4f-178d-7c1e-99d4-c1bff812630d' AND updated_at <= '2026-09-13T21:20:44.629946Z'::timestamptz)
ON CONFLICT (character_id, locale) DO UPDATE
  SET description = EXCLUDED.description
  WHERE character_translations.character_id IN (SELECT id FROM characters WHERE id = '01a09c4f-178d-7c1e-99d4-c1bff812630d' AND updated_at <= '2026-09-13T21:20:44.629946Z'::timestamptz);
INSERT INTO character_translations (character_id, locale, description)
SELECT '01a09c4f-178d-7c1e-99d4-c1bff812630d', 'en-GB', 'Monkey D. Luffy is the cheerful, carefree, and fiercely determined protagonist of One Piece. Captain of the Straw Hat Pirates, his dream is to find the legendary treasure and become the Pirate King. After eating the Gum-Gum Fruit (Gomu Gomu no Mi), his body gained the properties of rubber, allowing him to stretch and invent creative combat gears alongside mastering formidable forms of Haki.'
WHERE EXISTS (SELECT 1 FROM characters WHERE id = '01a09c4f-178d-7c1e-99d4-c1bff812630d' AND updated_at <= '2026-09-13T21:20:44.629946Z'::timestamptz)
ON CONFLICT (character_id, locale) DO UPDATE
  SET description = EXCLUDED.description
  WHERE character_translations.character_id IN (SELECT id FROM characters WHERE id = '01a09c4f-178d-7c1e-99d4-c1bff812630d' AND updated_at <= '2026-09-13T21:20:44.629946Z'::timestamptz);
INSERT INTO character_translations (character_id, locale, description)
SELECT '01a09c4f-178d-7c1e-99d4-c1bff812630d', 'es-ES', 'Monkey D. Luffy es el alegre, despreocupado y ferozmente determinado protagonista de One Piece. Capitán de los Piratas de Sombrero de Paja, su sueño es encontrar el legendario tesoro y convertirse en el Rey de los Piratas. Tras comerse la Fruta Goma Goma (Gomu Gomu no Mi), su cuerpo adquirió las propiedades de la goma, lo que le permite estirarse e inventar creativas técnicas de combate combinadas con el dominio de poderosas formas de Haki.'
WHERE EXISTS (SELECT 1 FROM characters WHERE id = '01a09c4f-178d-7c1e-99d4-c1bff812630d' AND updated_at <= '2026-09-13T21:20:44.629946Z'::timestamptz)
ON CONFLICT (character_id, locale) DO UPDATE
  SET description = EXCLUDED.description
  WHERE character_translations.character_id IN (SELECT id FROM characters WHERE id = '01a09c4f-178d-7c1e-99d4-c1bff812630d' AND updated_at <= '2026-09-13T21:20:44.629946Z'::timestamptz);
INSERT INTO character_translations (character_id, locale, description)
SELECT '01a09ce0-75f1-7dbe-b641-7c0aa6db1f3d', 'ca-ES', 'Trafalgar D. Water Law, conegut com el «Cirurgià de la Mort», és el perspicaç capità i metge dels Pirates de Heart a One Piece. Únic supervivent de la tràgica purga de Flevance, és portador de la misteriosa «Voluntat de D.» i acostuma a actuar com un calculador estrateg. Va menjar la Fruita Op-Op (Ope Ope no Mi), que li permet desplegar un territori esfèric anomenat «ROOM», dins del qual pot manipular, seccionar i alterar quirúrgicament qualsevol element amb absoluta precisió.'
WHERE EXISTS (SELECT 1 FROM characters WHERE id = '01a09ce0-75f1-7dbe-b641-7c0aa6db1f3d' AND updated_at <= '2026-09-13T22:25:52.447025Z'::timestamptz)
ON CONFLICT (character_id, locale) DO UPDATE
  SET description = EXCLUDED.description
  WHERE character_translations.character_id IN (SELECT id FROM characters WHERE id = '01a09ce0-75f1-7dbe-b641-7c0aa6db1f3d' AND updated_at <= '2026-09-13T22:25:52.447025Z'::timestamptz);
INSERT INTO character_translations (character_id, locale, description)
SELECT '01a09ce0-75f1-7dbe-b641-7c0aa6db1f3d', 'en-GB', 'Trafalgar D. Water Law, known as the "Surgeon of Death," is the sharp-witted captain and doctor of the Heart Pirates in One Piece. A survivor of the tragic purge of Flevance, he carries the mysterious "Will of D." and often acts as a calculated strategist. He ate the Op-Op Fruit (Ope Ope no Mi), which grants him the ability to manifest a spherical territory called "ROOM," allowing him to manipulate, slice, and surgically alter anything within it with pinpoint precision.'
WHERE EXISTS (SELECT 1 FROM characters WHERE id = '01a09ce0-75f1-7dbe-b641-7c0aa6db1f3d' AND updated_at <= '2026-09-13T22:25:52.447025Z'::timestamptz)
ON CONFLICT (character_id, locale) DO UPDATE
  SET description = EXCLUDED.description
  WHERE character_translations.character_id IN (SELECT id FROM characters WHERE id = '01a09ce0-75f1-7dbe-b641-7c0aa6db1f3d' AND updated_at <= '2026-09-13T22:25:52.447025Z'::timestamptz);
INSERT INTO character_translations (character_id, locale, description)
SELECT '01a09ce0-75f1-7dbe-b641-7c0aa6db1f3d', 'es-ES', 'Trafalgar D. Water Law, conocido como el «Cirujano de la Muerte», es el perspicaz capitán y médico de los Piratas de Heart en One Piece. Único superviviente de la trágica purga de Flevance, es portador de la misteriosa «Voluntad de D.» y suele actuar como un calculador estratega. Tomó la Fruta Op-Op (Ope Ope no Mi), que le permite desplegar un territorio esférico denominado «ROOM», en cuyo interior puede manipular, seccionar y alterar quirúrgicamente cualquier elemento con absoluta precisión.'
WHERE EXISTS (SELECT 1 FROM characters WHERE id = '01a09ce0-75f1-7dbe-b641-7c0aa6db1f3d' AND updated_at <= '2026-09-13T22:25:52.447025Z'::timestamptz)
ON CONFLICT (character_id, locale) DO UPDATE
  SET description = EXCLUDED.description
  WHERE character_translations.character_id IN (SELECT id FROM characters WHERE id = '01a09ce0-75f1-7dbe-b641-7c0aa6db1f3d' AND updated_at <= '2026-09-13T22:25:52.447025Z'::timestamptz);

